INSERT INTO `aa_aioseo_notifications` (`id`, `slug`, `addon`, `title`, `content`, `type`, `level`, `notification_id`, `notification_name`, `start`, `end`, `button1_label`, `button1_action`, `button2_label`, `button2_action`, `dismissed`, `new`, `created`, `updated`) VALUES
(1, '644d3d84a82c1', NULL, 'Introducing SEO Stats for WordPress - Track Your Keyword Rankings and See Important SEO Metrics with 1-click 🔎 🚀', 'Want to see exactly how your content ranks in search results inside of WordPress? You can do just that with our brand new <strong>Google Search Console integration</strong>!\r\n<br><br>\r\nTrack important keywords and get in-plugin tips to help you grow your traffic. <strong>Plus: Try out the new speed test tool!</strong> 🚀\r\n<br><br>\r\n<strong>Upgrade to AIOSEO 4.3.0 (Elite) TODAY to ignite your SEO and outrank competitors!</strong>\r\n<br><br>\r\n<img src=\"data:image/png;base64,\" />', 'success', '[\"4-x\",\"lite\"]', 570, NULL, '2023-05-03 19:02:15', NULL, 'Learn More', 'https://aioseo.com/google-search-console-integration/?utm_source=WordPress&utm_campaign=google-search-console-integration-v4-lite&utm_medium=plugin-notification&utm_content=Learn%20More', 'Get AIOSEO Pro 🚀', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=google-search-console-integration-v4-lite&utm_medium=plugin-notification&utm_content=Get%20AIOSEO%20Pro', 0, 0, '2023-04-29 15:53:40', '2023-05-25 13:43:44'),
(2, '64595efcaa30e', NULL, '🗣️ [AIOSEO 4.3.6] Announcing Content Rankings: SEO Performance Tracking Made Easy', 'Get valuable insights about how your content is performing on search engines using our <strong>NEW Content Rankings report</strong>.\r\n<br><br>\r\nThis includes SEO data to help you <strong>optimize your articles for better rankings</strong>. Plus, you can also easily spot <strong>content decay</strong>, making it easier to combat it.\r\n<br><br>\r\nSo, <strong>upgrade to AIOSEO Pro TODAY</strong> and boost your rankings and drive more traffic to your content!', 'success', '[\"4-x\",\"lite\"]', 677, NULL, '2023-05-03 19:02:15', NULL, 'Learn More', 'https://aioseo.com/announcing-content-rankings-seo-performance-tracking-made-easy/?utm_source=WordPress&utm_campaign=content-rankings-v4-lite&utm_medium=plugin-notification&utm_content=Learn%20More', 'Get AIOSEO Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=content-rankings-v4-lite&utm_medium=plugin-notification&utm_content=Get%20AIOSEO%20Pro', 0, 0, '2023-05-08 20:43:40', '2023-05-25 13:43:44');
