(2222, 'monsterinsights_notifications', 'a:5:{s:6:\"update\";i:1759261323;s:4:\"feed\";a:2:{i:0;a:7:{s:5:\"title\";s:35:\"NEW: Advanced Forms Report is Here!\";s:7:\"content\";s:325:\"Traffic is great - but leads are better. With the new Advanced Forms Report in MonsterInsights 9.6, you can easily see how many visitors complete your forms and which traffic sources or campaigns bring the best leads. Upgrade to Pro to unlock this powerful report and make smarter marketing decisions that grow your business!\";s:4:\"type\";a:1:{i:0;s:4:\"lite\";}s:2:\"id\";i:268;s:4:\"btns\";a:2:{s:4:\"main\";a:2:{s:3:\"url\";s:155:\"https://www.monsterinsights.com/pricing/?utm_source=liteplugin&utm_medium=monsterinsights-notifications-sidebar&utm_campaign=notifications&utm_content=9-6 \";s:4:\"text\";s:14:\"Upgrade to Pro\";}s:3:\"alt\";a:2:{s:3:\"url\";s:185:\"https://www.monsterinsights.com/introducing-the-advanced-forms-report/?utm_source=liteplugin&utm_medium=monsterinsights-notifications-sidebar&utm_campaign=notifications&utm_content=9-6 \";s:4:\"text\";s:10:\"Learn More\";}}s:5:\"start\";s:19:\"2025-06-25 00:00:00\";s:3:\"end\";s:19:\"2025-12-25 00:00:00\";}i:1;a:7:{s:5:\"title\";s:49:\"[MonsterInsights 9.5] - Pinterest Ads Integration\";s:7:\"content\";s:305:\"📊 Struggling to track your Pinterest Ads ROI? Our new Pinterest Ads integration helps you track ad performance directly in your WordPress dashboard. Upgrade to MonsterInsights Pro to unlock detailed Pinterest metrics and make smarter advertising decisions. See how your campaigns perform, automatically\";s:4:\"type\";a:1:{i:0;s:4:\"lite\";}s:2:\"id\";i:263;s:4:\"btns\";a:1:{s:4:\"main\";a:2:{s:3:\"url\";s:107:\"https://www.monsterinsights.com/lite?utm_campaign=liteplugin&utm_medium=notifications&utm_source=liteplugin\";s:4:\"text\";s:11:\"Upgrade Now\";}}s:5:\"start\";s:19:\"2025-05-07 00:00:00\";s:3:\"end\";s:19:\"2025-11-07 00:00:00\";}}s:6:\"events\";a:50:{i:0;a:10:{s:2:\"id\";s:59:\"monsterinsights_notification_install_