(815, 397, 'cost_info_label', 'Cost Info'),
(816, 397, 'cost_info_price_includes_title', 'Price includes'),
(817, 397, 'cost_info_price_includes_description', '<ol>\r\n 	<li>Pick-up or Drop-off service from and to Airport(in our own vehicle)</li>\r\n 	<li>Transportation to and from!!</li>\r\n 	<li>Food all along the trip(Breakfast, Lunch, Dinner and a cup of coffee or tea) and accommodations during the trip in hotels with family environment</li>\r\n 	<li>Transportation, food, accommodation and insurance of Guide during the trip</li>\r\n 	<li>First Aid Medical Kit(Your guide will carry the Medical Kit but we also advise to bring yourself for your own use, as far as possible)</li>\r\n 	<li>All the required permits and paperwork</li>\r\n</ol>'),
(818, 397, 'cost_info_price_excludes_title', 'Price excludes'),
(819, 397, 'cost_info_price_excludes_description', '<ol>\r\n 	<li>International Airfare</li>\r\n 	<li>Visa Charges</li>\r\n 	<li>Hotel Expenses(some packages do include hotel expenses)</li>\r\n 	<li>Your travel and medical insurance</li>\r\n 	<li>Personal Expenses such as shopping, bar bills, hot shower, telephone, laundry, titbits etc</li>\r\n 	<li>Food and accommodations in Kathmandu</li>\r\n 	<li>Services not mentioned or not promised by the agent/agency</li>\r\n 	<li>Emergency expenses such as expenses on chartered helicopte</li>\r\n</ol>'),
