(5550, 1, '2023-03-23 15:08:37', '2023-03-23 20:08:37', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"100%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:100%\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:spacer {\"height\":\"57px\"} -->\n<div style=\"height:57px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h1 class=\"has-text-align-left has-text-color\" style=\"color:#05577d;letter-spacing:1px\">AEROALLIANCE SAS</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#77797f\"><meta charset=\"utf-8\">Compañía dedicada a la prestación de servicios aeronáuticos, negocios internacionales y servicios turísticos a nivel nacional e internacional.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\",\"flexWrap\":\"nowrap\"},\"style\":{\"typography\":{\"fontSize\":\"10px\"}}} -->\n<div class=\"wp-block-buttons has-custom-font-size\" style=\"font-size:10px\"><!-- wp:button {\"style\":{\"typography\":{\"fontSize\":\"11px\"},\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/acerca/\" style=\"border-radius:0px\"><strong>Acerca de ...</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#c1cbcd\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#c1cbcd\"><!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h2 class=\"has-text-align-center has-text-color\" style=\"color:#05577d;letter-spacing:1px\">QUIENES SOMOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-align-left has-text-color\" style=\"color:#77797f\">Somos un equipo de profesionales en diferentes áreas propias del sector Aeronáutico y Comercio Exterior, que ofrece servicios de Comercialización de Productos, Importación y Exportación de Bienes y Servicios y Promoción Turística a nivel Nacional e Internacional.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"typography\":{\"fontSize\":\"11px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/acerca/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6762,\"width\":503,\"height\":197,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-resized is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Quienes-Somos-1.png\" alt=\"\" class=\"wp-image-6762\" width=\"503\" height=\"197\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"color\":{\"text\":\"#05577d\"}}} -->\n<h1 class=\"has-text-align-center has-text-color\" style=\"color:#05577d\">NUESTROS SERVICIOS</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6764,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Servicios-Aeronauticos.png\" alt=\"\" class=\"wp-image-6764\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h2 class=\"has-text-align-center has-text-color\" style=\"color:#05577d;letter-spacing:1px\">SERVICIOS AERONÁUTICOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-color\" style=\"color:#77797f\">Nuestra empresa cuenta con un equipo de profesionales en diferentes áreas del sector aeronáutico así como alianzas estrátegicas con empresas nacionales e internacionales para ofrecer servicios en el desarrrollo de actividades aeronáuticas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"bottom\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"typography\":{\"fontSize\":\"11px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/aeronauticos/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#c1cbcd\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#c1cbcd\"><!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h2 class=\"has-text-align-center has-text-color\" style=\"color:#05577d;letter-spacing:1px\">SERVICIOS TURÍSTICOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-align-left has-text-color\" style=\"color:#77797f\">Prestamos servicios turísticos en sinergia con aerolíneas, hoteles y operadores de la mejor calidad a todo destino Nacional e Internacional.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"typography\":{\"fontSize\":\"11px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/project/turistico/\" style=\"border-radius:0px\" target=\"_blank\" rel=\"noreferrer noopener\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6760,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Servicios-Turisticos.png\" alt=\"\" class=\"wp-image-6760\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6767,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Negocios-Internacionales.png\" alt=\"\" class=\"wp-image-6767\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h2 class=\"has-text-align-center has-text-color\" style=\"color:#05577d;letter-spacing:1px\">NEGOCIOS INTERNACIONALES</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-color\" style=\"color:#77797f\">Está constituida por un conjunto de alianzas estratégicas con empresas nacionales e internacionales de alta calidad y experiencia, que permiten la prestación de un servicio integral en negocios internacionales y comercio exterior garantizando así la eficacia y calidad en la gestión de negocios y la comercialización de bienes y servicios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"bottom\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"typography\":{\"fontSize\":\"11px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/project/negocios/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"black\"} -->\n<div class=\"wp-block-group alignfull has-black-background-color has-background\"><!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}},\"textColor\":\"white\",\"fontSize\":\"large\"} -->\n<h1 class=\"has-text-align-center has-white-color has-text-color has-large-font-size\" style=\"letter-spacing:1px\">NUESTRO PORTAFOLIO</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:wpzoom-blocks/portfolio {\"align\":\"full\",\"categories\":[],\"layout\":\"masonry\",\"order\":\"asc\",\"orderBy\":\"title\",\"secondaryColor\":\"#ffffff\",\"className\":\"portfolio-dark\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"useFeaturedImage\":true,\"hasParallax\":true,\"dimRatio\":40,\"overlayColor\":\"black\",\"minHeight\":375,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull has-parallax is-position-center-center\" style=\"min-height:375px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim-40 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"1px\",\"fontSize\":\"26px\"}},\"textColor\":\"white\"} -->\n<h3 class=\"has-text-align-center has-white-color has-text-color\" style=\"font-size:26px;letter-spacing:1px;text-transform:uppercase\"></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"white\"} -->\n<p class=\"has-text-align-center has-white-color has-text-color\"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"39px\"} -->\n<div style=\"height:39px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"textColor\":\"white\",\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-fill\",\"fontSize\":\"small\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-fill has-small-font-size\"><a class=\"wp-block-button__link has-white-color has-text-color wp-element-button\" href=\"http://localhost/aa/contactenos/\" style=\"border-radius:0px\">CONTÁCTENOS</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->', 'Homepage', '', 'publish', 'closed', 'closed', '', 'aeroalliancesas', '', '', '2023-04-03 23:30:57', '2023-04-04 04:30:57', '', 0, 'http://demo.wpzoom.com/inspiro/?page_id=5550', 0, 'page', '', 0),
(5592, 1, '2023-03-23 09:17:34', '2023-03-23 14:17:34', '<!-- wp:group {\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/quienessomos-1.jpg\",\"id\":7079,\"dimRatio\":0,\"minHeight\":679,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull is-light\" style=\"min-height:679px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-7079\" alt=\"\" src=\"http://localhost/aa/wp-content/uploads/2023/03/quienessomos-1.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Escribe el título…\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"level\":1} -->\n<h1>Acerca de Nosotros</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"43px\"} -->\n<div style=\"height:43px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\">AEROALLIANCE S.A.S es una empresa colombiana, constituida mediante documento privado bajo el número 02911743, del 30 de enero de 2018, con NIT 901150400-4 y cuyo establecimiento comercial constituido mediante documento privado bajo el número 02913816, del 02 de febrero de 2018 se denomina AEROALLIANCE TRAVELS.</p>\n<!-- /wp:html -->\n\n<!-- wp:spacer {\"height\":\"43px\"} -->\n<div style=\"height:43px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\">El objeto social de la empresa entre otros, es prestar asesoría técnica y legal en el sector aeronáutico en operaciones, mantenimiento y comerciales; prestar asesorías en procedimientos técnicos y jurídicos en la creación y certificación de empresas de aviación y otros; prestar servicios de ingeniería y mantenimiento en el área de aviación y afines; ofertar talento humano licenciado y calificado para hacer mantenimiento de aeronaves y sus partes; prestar servicios de turismo nacional e internacional; comercializar bienes y servicios nacionales e internacionales de cualquier índole así como importar y exportar productos y demás actividades que tengan relación directa con el objeto mencionado.</p>\n<!-- /wp:html -->\n\n<!-- wp:spacer {\"height\":\"43px\"} -->\n<div style=\"height:43px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-Justify\">AEROALLIANCE S.A.S está ubicada en la calle 8C No. 78C 43, en la ciudad de Bogotá, Distrito Capital, con número de teléfono 316 679 2223, correo electrónico <a href=\"mailto:info\">info@aeroalliancesas.com</a>, y página web www.aeroalliancesas.com</p>\n<!-- /wp:html -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}}} -->\n<h1 style=\"letter-spacing:1px\">QUIENES SOMOS</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\">Somos un equipo de profesionales en diferentes áreas propias del sector aeronáutico, turístico y de comercio exterior, que ofrece servicios para el desarrollo de actividades aeronáuticas tanto en talento humano como en gestión para la certificación de organizaciones aeronáuticas y afines, además de la comercialización de productos, importación y exportación de bienes y servicios y promoción turística a nivel nacional e internacional.</p>\n<!-- /wp:html -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button /--></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":7101,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"wp-block-image size-full is-style-rounded\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Jose-2.png\" alt=\"\" class=\"wp-image-7101\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"top\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"has-text-align-center\">MISIÓN</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\">Promover la comercialización de diferentes productos, bienes y servicios en el mercado nacional e internacional, respondiendo a las necesidades del sector comercial, industrial, aeronáutico y turístico, prestando un excelente servicio de calidad con eficiencia y responsabilidad.</p>\n<!-- /wp:html --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"id\":7112,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Quienes-Somos-2.png\" alt=\"\" class=\"wp-image-7112\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}}} -->\n<h1 class=\"has-text-align-center\" style=\"letter-spacing:1px\">VISIÓN</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\">Ser una organización consolidada, reconocida a nivel nacional e internacional por su calidad en los servicios que presta, acorde con nuestros valores corporativos.</p>\n<!-- /wp:html -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"bottom\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button /--></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}}} -->\n<h1 style=\"letter-spacing:1px\">NUESTROS VALORES CORPORATIVOS</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\"><strong>Calidad:</strong>&nbsp;Somos un equipo de trabajo competente en la solución de necesidades propias del sector aeronáutico, turístico y de comercio internacional, garantizando la excelencia en nuestros servicios.</p>\n<!-- /wp:html -->\n\n<!-- wp:spacer {\"height\":\"43px\"} -->\n<div style=\"height:43px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\"><strong>Eficiencia:</strong>&nbsp;Tenemos la capacidad, el conocimiento y las destrezas para realizar y cumplir las expectativas que ofrecemos en nuestros servicios.</p>\n<!-- /wp:html -->\n\n<!-- wp:spacer {\"height\":\"43px\"} -->\n<div style=\"height:43px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\"><strong>Respeto:</strong>&nbsp;Tenemos la disponibilidad, la dignidad y el criterio para atender todas sus inquietudes, fomentando la tolerancia y el acompañamiento necesario para responder a sus necesidades.<strong></strong></p>\n<!-- /wp:html -->\n\n<!-- wp:spacer {\"height\":\"43px\"} -->\n<div style=\"height:43px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<p class=\"has-text-align-justify\"><strong>Responsabilidad:</strong>&nbsp;Somos una empresa que lleva a cabo procedimientos de reflexión, coordinación, administración y orientación, para garantizar el cumplimiento y la satisfacción en todos nuestros servicios.</p>\n<!-- /wp:html -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button /--></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":7106,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"wp-block-image size-full is-style-rounded\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Anakarina-1.png\" alt=\"\" class=\"wp-image-7106\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:cover {\"useFeaturedImage\":true,\"hasParallax\":true,\"dimRatio\":50,\"overlayColor\":\"black\",\"minHeight\":316,\"minHeightUnit\":\"px\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"right\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px;min-height:316px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-fill\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-fill has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/contactenos/\" style=\"border-radius:0px\">CONTÁCTENOS</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->', 'Acerca de Nosotros', '', 'publish', 'closed', 'closed', '', 'acerca', '', '', '2023-03-23 22:08:38', '2023-03-24 03:08:38', '', 0, 'http://demo.wpzoom.com/inspiro/?page_id=5592', 0, 'page', '', 0),
