(5701, 1, '2023-03-23 11:58:43', '2023-03-23 16:58:43', '<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading -->\n<h2><strong>Elaboración de Manuales y Documentos Regulatorios</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Elaboramos y desarrollamos Manuales Aeronáuticos, Manuales de Procedimientos y Documentos Regulatorios para todo tipo de empresas, tanto del sector aeronáutico como en otros sectores comerciales e industriales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Realizamos el asesoramiento en la presentación y aprobación de documentos ante la Autoridad Respectiva.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button /--></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6819,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2017/09/manuales.jpg\" alt=\"\" class=\"wp-image-6819\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"has-text-align-center\">Algunos de los manuales que desarrollamos son:&nbsp;</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"top\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Manual general de operaciones (<strong>MGO</strong>)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Manual general de mantenimiento (<strong>MGM</strong>)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Manual de procedimientos de inspección (<strong>MPI</strong>)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Sistema de gestión operacional (<strong>SMS</strong>)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Manual de control de calidad (<strong>MCC</strong>)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Manual de taller aeronáutico de reparación (<strong>MTAR</strong>)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"bottom\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button /--></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"useFeaturedImage\":true,\"hasParallax\":true,\"dimRatio\":50,\"overlayColor\":\"black\",\"minHeight\":316,\"minHeightUnit\":\"px\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"right\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px;min-height:316px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"has-text-align-center has-white-color has-text-color\">Si el manual que usted necesita no se encuentra en el listado, se puede contactar con nosotros para brindarle una asesoría personalizada.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:wpforms/form-selector {\"formId\":\"7309\",\"displayTitle\":false} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":339,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/contact.png\" alt=\"\" class=\"wp-image-339\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/aa/politicas-de-privacidad/\" target=\"_blank\" rel=\"noopener\" title=\"\">Ver Política de Tratamiento de Datos</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'MANUALES AERONÁUTICOS', '', 'publish', 'closed', 'closed', '', 'manuales', '', '', '2023-03-23 23:46:11', '2023-03-24 04:46:11', '', 0, 'http://demo.wpzoom.com/inspiro-video/?post_type=portfolio_item&#038;p=5701', 0, 'portfolio_item', '', 0),
