\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"black\"} -->\n<div class=\"wp-block-group alignfull has-black-background-color has-background\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}},\"textColor\":\"white\",\"fontSize\":\"medium\"} -->\n<h3 class=\"has-text-align-center has-white-color has-text-color has-medium-font-size\" style=\"letter-spacing:1px\">NUESTRO PORTAFOLIO</h3>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:wpzoom-blocks/portfolio {\"align\":\"full\",\"categories\":[\"-1\"],\"layout\":\"masonry\",\"secondaryColor\":\"#ffffff\",\"className\":\"portfolio-dark\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Learget-45.jpg\",\"id\":6780,\"hasParallax\":true,\"dimRatio\":40,\"overlayColor\":\"black\",\"minHeight\":375,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull is-light has-parallax is-position-center-center\" style=\"min-height:375px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim-40 has-background-dim\"></span><div role=\"img\" class=\"wp-block-cover__image-background wp-image-6780 has-parallax\" style=\"background-position:50% 50%;background-image:url(http://localhost/aa/wp-content/uploads/2023/03/Learget-45.jpg)\"></div><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpac