age {\"id\":6886,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/MSC-Europa.jpg\" alt=\"\" class=\"wp-image-6886\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6888,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Regiotram.jpg\" alt=\"\" class=\"wp-image-6888\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6889,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Glacier-Express.jpg\" alt=\"\" class=\"wp-image-6889\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6890,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Avianca.jpeg\" alt=\"\" class=\"wp-image-6890\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6891,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Lufthansa.jpg\" alt=\"\" class=\"wp-image-6891\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6892,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Autobuses.jpg\" alt=\"\" class=\"wp-image-6892\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6893,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Autobus.jpg\" alt=\"\" class=\"wp-image-6893\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6894,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Puerto-Miami.jpg\" alt=\"\" class=\"wp-image-6894\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6895,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Wonder_of_the_Seas.jpg\" alt=\"\" class=\"wp-image-6895\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6896,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Trenes.jpg\" alt=\"\" class=\"wp-image-6896\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6897,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Tren.jpg\" alt=\"\" class=\"wp-image-6897\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6898,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Latam.jpg\" alt=\"\" class=\"wp-image-6898\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6899,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Volaris.jpg\" alt=\"\" class=\"wp-image-6899\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6900,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Turistico-Cartagena.jpg\" alt=\"\" class=\"wp-image-6900\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6901,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Turistico-Roma.jpg\" alt=\"\" class=\"wp-image-6901\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":6902,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Viaje-en-Tren.jpg\" alt=\"\" class=\"wp-image-6902\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6916,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Hotel.png\" alt=\"\" class=\"wp-image-6916\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading -->\n<h2>Hoteles, Hostales, Apartamentos, Glamping, Camping y Resorts</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Venta de hospedaje a nivel nacional e internacional con más de 300.000 operadores con los más altos estandares de calidad de acuerdo a la necesidad de nuestros clientes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"61px\"} -->\n<div style=\"height:61px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-outl