(7739, 1, '2023-04-03 23:03:28', '2023-04-04 04:03:28', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"100%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:100%\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:spacer {\"height\":\"57px\"} -->\n<div style=\"height:57px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}}} -->\n<h1 class=\"has-text-align-left\" style=\"letter-spacing:1px\">AEROALLIANCE SAS</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"43px\"} -->\n<div style=\"height:43px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><meta charset=\"utf-8\">Compañía dedicada a la prestación de servicios aeronáuticos, negocios internacionales y servicios turísticos a nivel nacional e internacional.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/acerca/\" style=\"border-radius:0px\"><strong>Acerca de ...</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#c1cbcd\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#c1cbcd\"><!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}}} -->\n<h2 class=\"has-text-align-center\" style=\"letter-spacing:1px\">QUIENES SOMOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">Somos un equipo de profesionales en diferentes áreas propias del sector Aeronáutico y Comercio Exterior, que ofrece servicios de Comercialización de Productos, Importación y Exportación de Bienes y Servicios y Promoción Turística a nivel Nacional e Internacional.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/acerca/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6762,\"width\":503,\"height\":197,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-resized is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Quienes-Somos-1.png\" alt=\"\" class=\"wp-image-6762\" width=\"503\" height=\"197\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"has-text-align-center\">NUESTROS SERVICIOS</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6764,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Servicios-Aeronauticos.png\" alt=\"\" class=\"wp-image-6764\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}}} -->\n<h2 class=\"has-text-align-center\" style=\"letter-spacing:1px\">SERVICIOS AERONÁUTICOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>Nuestra empresa cuenta con un equipo de profesionales en diferentes áreas del sector aeronáutico así como alianzas estrátegicas con empresas nacionales e internacionales para ofrecer servicios en el desarrrollo de actividades aeronáuticas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"bottom\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/aeronauticos/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#c1cbcd\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#c1cbcd\"><!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}}} -->\n<h2 class=\"has-text-align-center\" style=\"letter-spacing:1px\">SERVICIOS TURÍSTICOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">Prestamos servicios turísticos en sinergia con aerolíneas, hoteles y operadores de la mejor calidad a todo destino Nacional e Internacional.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/project/turistico/\" style=\"border-radius:0px\" target=\"_blank\" rel=\"noreferrer noopener\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6760,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Servicios-Turisticos.png\" alt=\"\" class=\"wp-image-6760\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6767,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Negocios-Internacionales.png\" alt=\"\" class=\"wp-image-6767\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}}} -->\n<h2 class=\"has-text-align-center\" style=\"letter-spacing:1px\">NEGOCIOS INTERNACIONALES</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>Está constituida por un conjunto de alianzas estratégicas con empresas nacionales e internacionales de alta calidad y experiencia, que permiten la prestación de un servicio integral en negocios internacionales y comercio exterior garantizando así la eficacia y calidad en la gestión de negocios y la comercialización de bienes y servicios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"45px\"} -->\n<div style=\"height:45px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"bottom\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/project/negocios/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"black\"} -->\n<div class=\"wp-block-group alignfull has-black-background-color has-background\"><!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}},\"textColor\":\"white\",\"fontSize\":\"large\"} -->\n<h1 class=\"has-text-align-center has-white-color has-text-color has-large-font-size\" style=\"letter-spacing:1px\">NUESTRO PORTAFOLIO</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:wpzoom-blocks/portfolio {\"align\":\"full\",\"categories\":[],\"layout\":\"masonry\",\"order\":\"asc\",\"orderBy\":\"title\",\"secondaryColor\":\"#ffffff\",\"className\":\"portfolio-dark\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"useFeaturedImage\":true,\"hasParallax\":true,\"dimRatio\":40,\"overlayColor\":\"black\",\"minHeight\":375,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull has-parallax is-position-center-center\" style=\"min-height:375px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim-40 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"1px\",\"fontSize\":\"26px\"}},\"textColor\":\"white\"} -->\n<h3 class=\"has-text-align-center has-white-color has-text-color\" style=\"font-size:26px;letter-spacing:1px;text-transform:uppercase\"></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"white\"} -->\n<p class=\"has-text-align-center has-white-color has-text-color\"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"39px\"} -->\n<div style=\"height:39px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-fill\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-fill has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/contactenos/\" style=\"border-radius:0px\">CONTÁCTENOS</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'Homepage', '', 'inherit', 'closed', 'closed', '', '5550-revision-v1', '', '', '2023-04-03 23:03:28', '2023-04-04 04:03:28', '', 5550, 'http://localhost/aa/?p=7739', 0, 'revision', '', 0),
