(7746, 1, '2023-04-03 23:22:34', '2023-04-04 04:22:34', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"100%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:100%\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:spacer {\"height\":\"57px\"} -->\n<div style=\"height:57px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h1 class=\"has-text-align-left has-text-color\" style=\"color:#05577d;letter-spacing:1px\">AEROALLIANCE SAS</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-align-center has-text-color\" style=\"color:#77797f\"><meta charset=\"utf-8\">Compañía dedicada a la prestación de servicios aeronáuticos, negocios internacionales y servicios turísticos a nivel nacional e internacional.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\",\"flexWrap\":\"nowrap\"},\"style\":{\"typography\":{\"fontSize\":\"10px\"}}} -->\n<div class=\"wp-block-buttons has-custom-font-size\" style=\"font-size:10px\"><!-- wp:button {\"style\":{\"typography\":{\"fontSize\":\"11px\"},\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/acerca/\" style=\"border-radius:0px\"><strong>Acerca de ...</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#c1cbcd\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#c1cbcd\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h2 class=\"has-text-align-center has-text-color\" style=\"color:#05577d;letter-spacing:1px\">QUIENES SOMOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-align-left has-text-color\" style=\"color:#77797f\">Somos un equipo de profesionales en diferentes áreas propias del sector Aeronáutico y Comercio Exterior, que ofrece servicios de Comercialización de Productos, Importación y Exportación de Bienes y Servicios y Promoción Turística a nivel Nacional e Internacional.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"typography\":{\"fontSize\":\"11px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/acerca/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6762,\"width\":503,\"height\":197,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-defaul