:\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Servicios-Aeronauticos.png\" alt=\"\" class=\"wp-image-6764\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h2 class=\"has-text-align-center has-text-color\" style=\"color:#05577d;letter-spacing:1px\">SERVICIOS AERONÁUTICOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-color\" style=\"color:#77797f\">Nuestra empresa cuenta con un equipo de profesionales en diferentes áreas del sector aeronáutico así como alianzas estrátegicas con empresas nacionales e internacionales para ofrecer servicios en el desarrrollo de actividades aeronáuticas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"bottom\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"typography\":{\"fontSize\":\"11px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/aeronauticos/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#c1cbcd\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#c1cbcd\"><!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h2 class=\"has-text-align-center has-text-color\" style=\"color:#05577d;letter-spacing:1px\">SERVICIOS TURÍSTICOS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-align-left has-text-color\" style=\"color:#77797f\">Prestamos servicios turísticos en sinergia con aerolíneas, hoteles y operadores de la mejor calidad a todo destino Nacional e Internacional.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"typography\":{\"fontSize\":\"11px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/project/turistico/\" style=\"border-radius:0px\" target=\"_blank\" rel=\"noreferrer noopener\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6760,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Servicios-Turisticos.png\" alt=\"\" class=\"wp-image-6760\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:spacer {\"height\":\"48px\"} -->\n<div style=\"height:48px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6767,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/Negocios-Internacionales.png\" alt=\"\" class=\"wp-image-6767\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"letterSpacing\":\"1px\"},\"color\":{\"text\":\"#05577d\"}}} -->\n<h2 class=\"has-text-align-center has-text-color\" style=\"color:#05577d;letter-spacing:1px\">NEGOCIOS INTERNACIONALES</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#77797f\"}}} -->\n<p class=\"has-text-color\" style=\"color:#77797f\">Está constituida por un conjunto de alianzas estratégicas con empresas nacionales e internacionales de alta calidad y experiencia, que permiten la prestación de un servicio integral en negocios internacionales y comercio exterior garantizando así la eficacia y calidad en la gestión de negocios y la comercialización de bienes y servicios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"verticalAlignment\":\"bottom\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"typography\":{\"fontSize\":\"11px\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline\" style=\"font-size:11px\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/aa/project/negocios/\" style=\"border-radius:0px\"><strong>ver mas</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"black\"} -->\n<div class=\"wp-block-group alignfull has-black-background-color has-background\"><!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"letterSpacing\":\"1px\"}},\"textColor\":\"white\",\"fontSize\":\"large\"} -->\n<h1 class=\"has-text-align-center has-white-color has-text-color has-large-font-size\" style=\"letter-spacing:1px\">NUESTRO PORTAFOLIO</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:wpzoom-blocks/portfolio {\"align\":\"full\",\"categories\":[],\"layout\":\"masonry\",\"order\":\"asc\",\"orderBy\":\"title\",\"secondaryColor\":\"#ffffff\",\"className\":\"portfolio-dark\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"useFeaturedImage\":true,\"hasParallax\":true,\"dimRatio\":40,\"overlayColor\":\"black\",\"minHeight\":375,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull has-parallax is-position-center-center\" style=\"min-height:375px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim-40 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"1px\",\"fontSize\":\"26px\"}},\"textColor\":\"white\"} -->\n<h3 class=\"has-text-align-center has-white-color has-text-color\" style=\"font-size:26px;letter-spacing:1px;text-transform:uppercase\"></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"white\"} -->\n<p class=\"has-text-align-center has-white-color has-text-color\"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"39px\"} -->\n<div style=\"height:39px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"textColor\":\"white\",\"style\":{\"border\":{\"radius\":\"0px\"}},\"className\":\"is-style-fill\",\"fontSize\":\"small\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-fill has-small-font-size\"><a class=\"wp-block-button__link has-white-color has-text-color wp-element-button\" href=\"http://localhost/aa/contactenos/\" style=\"border-radius:0px\">CONTÁCTENOS</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->', 'Homepage', '', 'inherit', 'closed', 'closed', '', '5550-revision-v1', '', '', '2023-04-03 23:30:50', '2023-04-04 04:30:50', '', 5550, 'http://localhost/aa/?p=7754', 0, 'revision', '', 0);
INSERT INTO `aa_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(7772, 1, '2023-09-07 22:09:27', '2023-09-08 03:09:27', '<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\",\"textColor\":\"black\"} -->\n<div class=\"wp-block-group alignfull has-black-color has-white-background-color has-text-color has-background\"><!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"dimRatio\":0,\"minHeight\":679,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:679px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-7326\" alt=\"\" src=\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Escribe el título…\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Tratamiento de Datos - Habeas Data</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:list {\"ordered\":true,\"type\":\"1\"} -->\n<ol type=\"1\"><!-- wp:list-item -->\n<li><strong>POLÍTICA DE PROTECCIÓN DE DATOS PERSONALES</strong></li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">Con este Manual Interno de Políticas y Procedimientos de Tratamiento de Datos Habeas Data, AEROALLIANCE S.A.S<em>,</em> pretende desarrollar el derecho constitucional que tienen todas las personas a conocer, actualizar y rectificar las informaciones que se hayan recogido sobre ellas en las bases de datos o archivos, y los demás derechos, libertades y garantías constitucionales a que se refiere el Artículo 15 de la Constitución Política; así como el derecho a la información consagrada en el Artículo 20 de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.1. <strong><u>Objetivo General</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El objetivo de la Política de Privacidad de AEROALLIANCE S.A.S es dar a conocer su oferta de servicios de acuerdo a las normas del derecho de Habeas Data, para realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que la sociedad llevará acabo de la información suministrada, será para hacer posible la prestación de nuestros servicios, y comunicar a los viajeros, clientes o usuarios, qué información y datos personales recolectamos, para qué finalidades, cómo los usamos, cuándo los compartimos y cómo los protegemos, así como los derechos que le asisten a los titulares de la información y los procedimientos para ejercerlos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) AEROALLIANCE S.A.S reconoce la importancia de la seguridad, privacidad y confidencialidad de la información y los datos personales de los viajeros, clientes o usuarios suministran a través de los diversos canales de comercialización de nuestros productos y servicios (incluyendo sitio&nbsp;web, oficinas de venta,&nbsp;y call centers), y está comprometido con la protección y tratamiento adecuado de los mismos, conforme al régimen legal de protección de datos personales aplicable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.2. <strong><u>Objetivos específicos</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Realizar oportunamente la actualización, rectificación o supresión de los datos en los términos dados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Actualizar la información reportada por los Responsables del Tratamiento dentro de los cinco (05) días hábiles, contados a partir de su recibo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tramitar las consultas y los reclamos formulados por los Titulares en los términos señalados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Adoptar un manual interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley, y en especial, para la atención de consultas y reclamos por parte de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Registrar en la base de datos la leyenda <em>“reclamo en trámite” </em>en la forma en que se regula la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Insertar en la base de datos la leyenda <em>“información en discusión judicial” </em>una vez notificado por parte de la autoridad competente sobre procesos judiciales relacionados con la calidad del dato personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Abstenerse de circular información que esté siendo controvertida por el Titular y cuyo bloqueo haya sido ordenado por la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Permitir el acceso a la información únicamente a las personas que pueden tener acceso a ella.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Informar a la Superintendencia de Industria y Comercio cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>2. <strong>VIGENCIA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El procedimiento de Manejo de Datos Personales, entrará en vigencia una vez haya sido admitido el registro por la Superintendencia de Industria y Comercio en forma permanente y será de libre consulta por los ciudadanos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>3. <strong>RESPONSABLE DEL MANEJO DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En AEROALLIANCE S.A.S, el responsable del Manejo de Datos del Personal, será el representante Legal y la persona que bajo su responsabilidad designe como Usuario Operativo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>AEROALLIANCE S.A.S no designa a ninguna persona natural o jurídica como encargado de Tratamiento de Datos.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El responsable del Manejo del Tratamiento de datos, será su Representante Legal, Gerente de AEROALLIANCE S.A.S y deberá cumplir los siguientes deberes, sin perjuicio de las demás disposiciones previstas en la Ley 1581 del 2012 y en otras que rijan su actividad, estos son:</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>a) Garantizar al Titular, en todo tiempo, el pleno y efectivo ejercicio del derecho de Hábeas Data.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar y conservar, en las condiciones previstas en la ley, copia de la respectiva autorización otorgada por el Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Informar debidamente al Titular sobre la finalidad de la recolección y los derechos que le asisten por la virtud de la autorización otorgada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Garantizar que la información que se suministre al Usuario Operativo sea veraz, completa, exacta, actualizada, comprobable y comprensible.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Actualizar la información, comunicando de forma oportuna al Usuario Operativo, todas las novedades respecto de los datos que previamente le haya suministrado y adoptar las demás medidas necesarias para que la información suministrada a éste se mantenga actualizada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Rectificar la información cuando sea incorrecta y comunicar lo pertinente al Usuario Operativo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Suministrar al Usuario Operativo, según el caso, únicamente datos cuyo Tratamiento esté previamente autorizado de conformidad con lo previsto en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Exigir al Usuario Operativo en todo momento, el respeto a las condiciones de seguridad y privacidad de la información del titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Tramitar las consultas y reclamos formulados en los términos señalados en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Adoptar un Manual Interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley y en especial, para la atención de consultas y reclamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>l) Informar al Usuario Operativo cuando determinada información se encuentra en discusión por parte del Titular, una vez se haya presentado la reclamación y no haya finalizado el trámite respectivo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>m) Informar a solicitud del Titular sobre el uso datos a sus datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>n) Informar a la autoridad de protección de datos cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>4. <strong>DEFINICIONES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.1. <strong><u>Autorización.</u></strong> Consentimiento previo, expreso e informado del Titular para llevar a cabo el Tratamiento de datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.2. <strong><u>Base de Datos.</u></strong> Conjunto organizado de datos personales que sea objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.3. <strong><u>Dato personal.</u></strong> Cualquier información vinculada o que pueda asociarse a una o varias personas naturales determinadas o determinables.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.4. <strong><u>Datos sensibles.</u></strong> Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.5. <strong><u>Encargado del tratamiento.</u></strong><strong> </strong>Persona natural o jurídica, pública o privada que por sí misma o en asocio con otros, decida sobre la base de datos y/o el Tratamiento de los datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.6. <strong><u>Titular.</u></strong> Persona natural cuyos datos personales sean objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.7. <strong><u>Tratamiento.</u></strong> Cualquier operación o conjunto de operaciones sobre datos personales, tales como la recolección, almacenamiento, uso, circulación o supresión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.8. <strong><u>Usuario Operativo.</u></strong> Persona natural designada por el responsable del Manejo del Tratamiento de datos para la operación de la información sin competencia para el tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>5. <strong>CATEGORÍA DE LOS DATOS TRATADOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La categoría de los datos tratados en AEROALLIANCE S.A.S son:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.1. <strong><u>Datos Privados.</u></strong><strong> </strong>El dato privado es el dato que por su naturaleza íntima o reservada sólo es relevante para el titular, (no controlados).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2. <strong><u>Datos Semi-Privados.</u></strong><strong> </strong>El dato semiprivado es aquel que no tiene naturaleza íntima, reservada, ni pública y cuyo conocimiento o divulgación puede interesar no sólo a su titular sino a cierto sector personas o a la sociedad en general, como el dato financiero y crediticio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Semi-Privados que trata AEROALLIANCE S.A.S en las bases de datos son los requeridos para comercializar los productos o servicios que ofrece esta sociedad.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3. <strong><u>Datos públicos.</u></strong><strong> </strong>Los datos serán públicos cuando la ley o la Constitución así lo establezcan, y cuando no sean de aquellos clasificados como semiprivados o privados. Son públicos, entre otros, los datos contenidos en documentos públicos, sentencias judiciales debidamente ejecutoriadas y los relativos al estado civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Públicos que trata AEROALLIANCE S.A.S serán los contenidos en documentos públicos de identidad, como nombre y apellido, tipo y número de identificación, fecha de nacimiento, direcciones postales y electrónicas (personales y/o laborales), Estado civil y/o parentesco en relación con personas menores de edad o discapacitados solicitantes de nuestros servicios, Nacionalidad y país de residencia, Teléfonos fijos y celulares de contacto (personales y/o laborales) e información necesaria para facilitar el viaje u otros servicios, incluyendo el nombre de acompañante(s) de viaje, contactos para casos de accidente o cualquier otra contingencia, preferencia en asientos, comidas especiales o requerimientos médicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4. <strong><u>Datos Sensibles.</u></strong><strong> </strong>Aquellos que afectan la intimidad del Titular o cuyo uso indebido pueden generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>AEROALLIANCE S.A.S para desarrollar el objeto social no tratara datos sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>6. <strong>BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El tratamiento que recibe esta base de datos por parte de AEROALLIANCE S.A.S. en su condición de responsable y encargado incluye la recolección, el almacenamiento, la custodia, la actualización, la circulación entre las diferentes áreas y el uso de los datos personales para cumplir con la finalidad de la empresa de prestar servicios de Turismo y servicios Técnicos Aeronáuticos. La información se consolida en los diferentes sistemas de información, y en archivos electrónicos. La información circula principalmente mediante los sistemas de información, correos electrónicos y la plataforma Sistema Integrado de Servicios Corporativos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información personal contenida en esta base de datos es resguardada en su mayoría en sistemas de información que son gestionados por roles con usuarios y contraseñas, de igual forma con accesos controlados al sistema. Es de uso exclusivo de AEROALLIANCE S.A.S, y puede ser suprimida, de acuerdo con lo regulado por la ley al respecto. Adicionalmente, se utiliza para darle los usos generales establecidos en el aparte 9 del presente Manual. No se usa para ninguna otra finalidad diferente a la establecida en este Manual.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.1. <strong><u>Base de Datos Personales Socios.</u></strong><strong> </strong>Las bases de datos de los socios de AEROALLIANCE S.A.S son de carácter público</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.2. <strong><u>Base de Datos Personales Colaboradores.</u></strong><strong> </strong>Datos personales del personal de empleados que prestan sus servicios en AEROALLIANCE S.A.S. Su finalidad es mantener actualizada la información para propósitos de pagos de nómina, Seguridad Social con entidades prestadoras de salud EPS, ARL y Caja de Compensación Familiar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.3. <strong><u>Base de Datos Personales de Clientes Externos.</u></strong><strong> </strong>AEROALLIANCE S.A.S utilizará su base de datos para los clientes externos para los siguientes casos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Para fines comerciales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Contabilización.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Cumplimiento de decisiones judiciales y disposiciones administrativas y legales, fiscales y regulatorias.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Cumplimiento de obligaciones contractuales, por lo cual la información podrá ser transferida a terceros, tales como entidades financieras, notarías, listas OFAC y de terrorismo, abogados, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Para realizar los procesos en que se encuentran vinculados los proveedores.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Cualquier otro uso que el proveedor autorice por escrito para el uso de su información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Transmisión de información y datos personales en procesos de auditorías.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>7. <strong>FORMA DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S establece que la base de datos será almacenada en dos formas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.1. <strong><u>Forma Física de la Base de Datos (Formatos en Documento y Medio Electrónico).</u></strong><strong> </strong>Base de datos en documentos físicos tales como folders o carpetas, formatos de entrevistas y hojas de vida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.2. <strong><u>Base de datos en archivos electrónicos</u></strong>. Bases de datos almacenada en medios electrónicos para lo cual usará un servidor en internet y/o computadora personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>8. <strong>RESPONSABILIDAD DEL MANEJO DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En AEROALLIANCE S.A.S, el responsable del tratamiento de Datos es el Representante Legal que aparece en el NIT, que por sí misma, decide sobre la base de datos y/o el tratamiento de los datos que puede hacer cualquier operación o conjunto de operaciones sobre los datos personales, como la recolección, almacenamiento, uso, circulación o supresión, entre otros.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>9. <strong>PROCEDIMIENTO CICLO DE VIDA DEL DATO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.1. <strong><u>Recolección.</u></strong><strong> </strong>Es el momento en que se recogen los datos. Puede ser del propio titular o, de un Tercero o de fuentes accesibles al público.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.2. <strong><u>Almacenamiento y/o Conservación.</u></strong><strong> </strong>Es el momento en que introducimos los datos recogidos en el Sistema Integrado de Servicios Corporativos y los utilizamos para una finalidad específica. Por ejemplo, elaborar cotizaciones, emisiones, facturas, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.3. <strong><u>Uso.</u></strong><strong> </strong>Es el momento en que AEROALLIANCE S.A.S comunica los datos, o el resultado del tratamiento a Terceros. Esta “cesión o comunicación de datos”, solamente se hará cuando el titular o su representante legal lo autorice expresamente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.4. <strong><u>Circulación y supresión del <em>Habeas Data.</em></u></strong><strong> </strong>Se establece como circulación y supresión del Habeas Data, cuando eliminamos definitivamente los datos porque ya no son necesarios o pertinentes para la finalidad para la cual fueron recabados en su momento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>10. <strong>AUTORIZACIÓN MANEJO DE DATOS PERSONALES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De acuerdo al artículo 5° del Decreto 1377 de 2013, en AEROALLIANCE S.A.S como Responsable del Tratamiento en todos los formatos que incluyen manejo de datos, se incluirá el término “<strong><em>aviso </em>de privacidad” </strong>el cual contiene el siguiente texto: “<em>Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales, quien permitirá conocer el uso, actualizar y rectificar las informaciones que ha recopilado en bases de datos o archivos, con el fin de garantizar mis derechos, libertades y garantías constitucionales.”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los datos personales que se encuentren en fuentes de acceso público, con independencia del medio por el cual se tenga acceso, pueden ser tratados por AEROALLIANCE S.A.S, siempre y cuando, por su naturaleza, sean Datos Públicos. Se entenderá que la autorización otorgada por el Titular a AEROALLIANCE S.A.S cumple con los requisitos exigidos en la legislación vigente aplicable, cuando ésta se manifieste:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Por escrito</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) De forma oral</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Mediante conductas inequívocas del Titular que permitan concluir de forma razonable que éste otorgó a la Institución la autorización respectiva.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) En ningún caso su silencio será asimilado por AEROALLIANCE S.A.S como una conducta inequívoca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S ha establecido canales para que el Titular de datos, pueda en todo momento solicitarle como Responsable del Tratamiento, la supresión de sus datos personales y/o revocar la autorización que nos ha otorgado para el Tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.1. <strong><u>Autorización del Titular para el Tratamiento de los Datos Sensibles.</u></strong><strong> </strong>En el tratamiento de datos personales sensibles, cuando dicho tratamiento sea posible conforme a lo establecido en el artículo 6° de la Ley 1581 de 2012, AEROALLIANCE S.A.S cumplirá con las siguientes obligaciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Informar al Titular que por tratarse de datos sensibles no está obligado a autorizar su Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Informar al Titular de forma explícita y previa, además de los requisitos generales de la autorización para la recolección de cualquier tipo de dato personal, cuáles de los datos que serán objeto de Tratamiento son sensibles y la finalidad de su Tratamiento, y además obtiene su consentimiento expreso. Ninguna de las actividades que realiza AEROALLIANCE S.A.S está ni estará condicionada a que usted como Titular suministre sus datos personales sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.2. <strong><u>Uso y Finalidad del Tratamiento de Datos Personales.</u></strong><strong> </strong>AEROALLIANCE S.A.S como entidad respetuosa de la privacidad de las personas reconoce que el Titular de los datos personales tiene derecho a contar con elementos adecuados que garanticen la misma, teniendo en todo caso para ello en cuenta sus responsabilidades, derechos y obligaciones. En virtud de la relación que se ha establecido o establezca entre el titular y AEROALLIANCE S.A.S es importante que el titular conozca que AEROALLIANCE S.A.S., recolecta, registra, almacena, usa sus datos personales, para su propio uso con los propósitos que fueron solicitados o por requerimientos de las entidades públicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales de los Titulares son utilizados por AEROALLIANCE S.A.S para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Ejecutar las actividades propias de AEROALLIANCE S.A.S para cumplir con su función de prestar Servicios de Venta de Productos Turísticos y Servicios Técnicos Aeronáuticos, lo cual se hará con base en la finalidad de la Base de Datos en la que reposan los Datos Personales de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Ofrecerle servicios y/o beneficios que buscan satisfacer las necesidades de los Titulares, o los productos y servicios AEROALLIANCE S.A.S, lo cual pueden hacerse por medios físicos o a través de correos electrónicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Enviar la información a entidades gubernamentales por exigencia legal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Registrar la información en las bases de datos de AEROALLIANCE S.A.S para el envío de información contractual, comercial y obligacional a que hubiere lugar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales serán utilizados por AEROALLIANCE S.A.S sólo para los propósitos aquí señalados, por lo tanto, AEROALLIANCE S.A.S, no venderá, licenciará, transmitirá o divulgará los Datos Personales, salvo que:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Titular autorice expresamente a hacerlo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Sea permitido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Para el manejo interno de los Datos, éstos podrán ser conocidos por el personal autorizado de AEROALLIANCE S.A.S. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S podrá subcontratar a terceros para el procesamiento de determinadas funciones o información. Cuando ello ocurra, dichos terceros estarán obligados a proteger los Datos Personales en los términos exigidos por la ley y en su condición de Encargados del Manejo de las Bases de Datos de AEROALLIANCE S.A.S. En el caso de transmisión de datos personales, AEROALLIANCE S.A.S ha suscrito o suscribirá el contrato de transmisión a que haya lugar en los términos del Decreto 1377 de 2013.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Igualmente, AEROALLIANCE S.A.S podrá transferir o transmitir (según corresponda), guardando las debidas medidas de seguridad, datos personales a otras entidades en Colombia o en el extranjero para la prestación de un mejor servicio, de conformidad con las autorizaciones que hayan sido otorgadas por los Titulares de los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>11. <strong>DERECHOS DE LOS TITULARES DE LOS DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La Ley 1581 de 2012, en su Artículo 8°, establece los siguientes derechos que a usted le asisten como Titular en relación con sus datos personales:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conocer, actualizar y rectificar sus datos personales frente a los Responsables del Tratamiento o Encargados del Tratamiento, este derecho se podrá ejercer, entre otros frente a datos parciales, inexactos, incompletos, fraccionados, que induzcan a error, o aquellos cuyo Tratamiento esté expresamente prohibido o no haya sido autorizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar prueba de la autorización otorgada al Responsable del Tratamiento salvo cuando expresamente se exceptúe como requisito para el Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Ser informado por el Responsable del Tratamiento o el Encargado del Tratamiento, previa solicitud, respecto del uso que les ha dado a sus datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Presentar ante la Superintendencia de Industria y Comercio quejas por infracciones a lo dispuesto en la Ley 1581 de 2012 y en las demás normas que la modifiquen, adicionen o complementen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Revocar la autorización y/o solicitar la supresión del dato cuando en el Tratamiento no se respeten los principios, derechos y garantías constitucionales y legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>12. <strong>CASOS QUE NO SON NECESARIOS DE ACTUALIZACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización del Titular no será necesaria cuando se trate de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Información requerida por una entidad pública o administrativa en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Datos de naturaleza pública.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Casos de urgencia médica o sanitaria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tratamiento de información autorizado por la Ley para fines históricos, estadísticos o científicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Datos relacionados con el Registro Civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Quien acceda a los datos personales sin que medie autorización previa, deberá en todo caso cumplir con las disposiciones contenidas en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>13. <strong>DEBER DE INFORMAR AL TITULAR</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El Responsable del Tratamiento en el momento de solicitar al Titular la autorización, deberá informarle de manera clara y expresa lo siguiente:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Tratamiento al cual serán sometidos sus datos personales y la finalidad del mismo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) El carácter facultativo de la respuesta a las preguntas que le sean hechas, cuando éstas versen sobre datos sensibles o sobre los datos de los niños, niñas y adolescentes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Los derechos que le asisten como Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) La identificación, dirección física o electrónica y teléfono del responsable del Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>14. <strong>PERSONAS A LAS QUE SE LES PUEDE SUMINISTRAR LA INFORMACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información que reúna las condiciones establecidas en la Ley 1581 de 2012, podrá suministrarse a las siguientes personas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) A los Titulares, sus causahabientes o sus representantes legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) A las entidades públicas o administrativas en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) A los terceros autorizados por el Titular o por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>15. <strong>PROCEDIMIENTOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.1. <u style=\"font-weight: bold;\">Consultas.</u><strong> </strong>Se podrá consultar la información personal del Titular que repose en las bases de datos de AEROALLIANCE S.A.S. quien se encargará de suministrar toda la información contenida en el registro individual o que esté vinculada con la identificación del solicitante.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La consulta una vez recibida por AEROALLIANCE S.A.S, será atendida en un término máximo de&nbsp;diez (10) días hábiles&nbsp;contados a partir de la fecha de recibo de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuando no fuere posible atender la consulta dentro de dicho término, se informará al interesado, expresando los motivos de la demora y señalando la nueva fecha en que se atenderá tal consulta, la cual en ningún caso podrá superar los&nbsp;cinco (5) días hábiles siguientes&nbsp;al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.2. <strong><u>Reclamos.</u></strong><strong> </strong>Cuando se considere que la información contenida en una base de datos de AEROALLIANCE S.A.S debe ser objeto de corrección, actualización o supresión, o cuando se advierta el presunto incumplimiento de cualquiera de los deberes contenidos en la Ley de Habeas Data, se podrán presentar reclamación ante AEROALLIANCE S.A.S, la cual será tramitada bajo las siguientes condiciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El reclamo se formulará mediante comunicación escrita dirigida a AEROALLIANCE S.A.S, con la identificación del Titular, la descripción de los hechos que dan lugar al reclamo, la dirección, y acompañando los documentos que se quiera hacer valer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Si el reclamo resulta incompleto, se requerirá al interesado dentro de los cinco&nbsp;(5)&nbsp;díassiguientes a la recepción del reclamo para que subsane las fallas.Transcurridos dos&nbsp;(2) meses&nbsp;desde la fecha del requerimiento, sin que el solicitante presente la información requerida, se entenderá que ha desistido del reclamo. En caso que AEROALLIANCE S.A.S reciba un reclamo del cual no sea competente para resolverlo, AEROALLIANCE S.A.S dará traslado a quien efectivamente corresponda en un término máximo de&nbsp;dos (2) días hábiles&nbsp;e informará al Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Una vez recibido el reclamo completo, AEROALLIANCE S.A.S incluirá en la respectiva base de datos una leyenda que diga&nbsp;\"reclamo en trámite\"&nbsp;y el motivo del mismo, en un término no mayor a&nbsp;dos (2) días hábiles. AEROALLIANCE S.A.S conservará dicha leyenda en el dato objeto de discusión hasta que el reclamo sea decidido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) El término máximo para atender el reclamo será de&nbsp;quince (15) días hábiles&nbsp;contados a partir del día siguiente a la fecha de su recibo. Cuando no fuere posible atender el reclamo dentro de dicho término, AEROALLIANCE S.A.S informará al Titular los motivos de la demora y la nueva fecha en que se atenderá su reclamo, la cual en ningún caso podrá superar los&nbsp;ocho (8) días hábiles&nbsp;siguientes al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textTransform\":\"none\"}}} -->\n<h1 class=\"wp-block-heading\" style=\"text-transform:none\"><strong>Autorización de Tratamiento de Información</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p><strong>HABEAS DATA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización suministrada en el presente formulario faculta a AEROALLIANCE S.A.S para que recopile, almacene, use y suprima los datos personales aquí suministrados, especialmente, aquellos que son definidos como Datos Sensibles (*).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S, como agencia de viajes y demás servicios aeronáuticos, con el propósito de cumplir el ejercicio del derecho de Habeas Data, requiere realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que AEROALLIANCE S.A.S llevará a cabo de la información suministrada, será netamente, administrativo y bajo ninguna circunstancia se realizará Tratamiento de Datos Personales con fines de comercialización o circulación en beneficio de la sociedad. En todo caso aplicarán las excepciones de ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En virtud del Artículo 8 de la Ley 1581 de 2013, el titular de la información personal que es recopilada, tiene los siguientes derechos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer, actualizar, rectificar y suprimir los datos suministrados.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer los usos que se han hecho de la información suministrada, cuando así lo solicite el titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Revocar la autorización y/o solicitar la supresión del dato suministrado cuando en el Tratamiento realizado no se respeten los principios, derechos y garantías constitucionales y legales a favor del titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El titular de la información suministrada, podrá ejercer cualquiera de los derechos mencionados, dirigiendo una petición en este sentido a la dirección electrónica <em>info@aeroalliancesas.com.</em> Recibida la solicitud en los términos dispuestos por AEROALLIANCE S.A.S, se le dará trámite al requerimiento según lo establecido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>(*) Datos Sensibles: Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>POLÍTICA DE PRIVACIDAD</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>La aceptación expresa de esta Política de Privacidad y del tratamiento de la información y los datos personales conforme a los términos de la misma, ocurre cuando el viajero, cliente o usuario titular de los mismos, proporciona los datos en los puntos de atención y venta, incluyendo&nbsp;<a href=\"http://www.avianca.com/co/es/call-center\">Call Center</a>, cuando adquiere o utiliza cualquiera de nuestros productos o servicios, cuando pulsa la función \"Cotizar\", cuando sigue navegando en nuestro sitio web&nbsp;www.aeroalliancesas.com; la prueba de cualquiera de esos hechos, será prueba inequívoca de la aceptación de esta Política de Privacidad y del tratamiento de los Datos Personales de los titulares de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yo titular de la información, en forma expresa y voluntaria Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales incorporados anteriormente tal y como lo dispone el Art. 15 de la Constitución Política Nacional, las Leyes estatutarias 1266 del 2008, la Ley estatutaria 1581 del 2012 y sus Decretos Reglamentarios: Decreto 1727 del 2009, Decreto 2952 del 2010, Decreto 1377 del 2013 y Decreto 886 del 2014; Los datos personales y/o sensibles suministrados, que sean sujetos a tratamiento, deberán ser utilizados por AEROALLIANCE S.A.S con fines históricos y estadísticos, que contribuyan a la comercialización de nuevos servicios aeronáuticos y turísticos relacionados con la prestación del servicio. AEROALLIANCE S.A.S me garantiza que podré ejercer mi derecho de acceso, rectificación y actualización relativo a este tratamiento, a través del sistema que AEROALLIANCE S.A.S establezca para tal fin. Así mismo, me comprometo a actualizar mis datos y eximo a AEROALLIANCE S.A.S, de cualquier responsabilidad derivada del incumplimiento o de la omisión de dicha obligación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Con la aceptación de la presente Política de Privacidad cada uno de nuestros viajeros, clientes o usuarios, en su calidad de titular de la información y de los datos personales recolectados autoriza el tratamiento de dichos datos para todas las finalidades establecidas en este documento y especialmente para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Usar la información y los datos personales suministrados para enviar a los correos electrónicos registrados por el viajero, cliente o usuario, el tiquete y/o el documento que confirme la transacción, así como cualquier información relacionada con el producto o servicio adquirido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Utilizar la información recibida para fines de mercadeo de nuestros productos y servicios, y de los productos y servicios de terceros con los que AEROALLIANCE S.A.S mantenga una relación de negocios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Compartir la información y los datos personales con representantes comerciales, operadores turísticos incluyendo hoteles, compañías de alquiler de vehículos, aseguradoras, entre otros, según sea requerido para el manejo de las reservaciones de planes de viajes y de otros servicios turísticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Suministrar la información y los datos personales a las autoridades de control y vigilancia, administrativas, de policía y judiciales, nacionales e internacionales, en virtud de un requerimiento legal o reglamentario y/o usar o revelar esta información y datos personales en defensa de los derechos y/o de la propiedad de AEROALLIANCE S.A.S, de sus clientes, de nuestro sitio&nbsp;web&nbsp;o de sus usuarios, para la detección o prevención de fraude, para la prevención, detección, aprehensión o persecución de actos criminales o cuando AEROALLIANCE S.A.S de buena fe considere que la entrega de la información y datos personales es en el mejor interés de la seguridad aérea.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Permitir el acceso a la información y datos personales a los auditores o terceros contratados para llevar a cabo procesos de auditoría interna o externa propios de la actividad comercial que desarrollamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Consultar y actualizar la información y los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S parte de la base que la información suministrada por los titulares, sus colaboradores, clientes y proveedores, tanto la propia como la de terceros es veraz, actualizada y cuenta con la autorización de los titulares. Así mismo se advierte que la información recibida y los datos personales contenidos en documentos proporcionados, tiene el propósito de ser utilizada con base en la normatividad sobre Habeas Data- Datos Personales (Art. 15 de la Constitución Política Nacional, la Ley Estatutaria No. 1266 del 2008; los Decretos Reglamentarios Decreto 1727 del 2009 y Decreto 2952 del 2010; la Ley Estatutaria No. 1581 del 2012 y sus Decretos reglamentarios 1377 del 2013 y 886 del 2014; y demás normas aplicables) para lo cual, toda persona que provea información de datos sensibles, será consultada sobre la aceptación o no del manejo de sus datos mediante la siguiente pregunta:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“El titular manifiesta que ha sido informado que </strong><strong>AEROALLIANCE S.A.S</strong><strong> hará tratamiento de sus datos personales con el único y exclusivo propósito de ofrecer los servicios de su actividad comercial y que tiene el derecho a acceder, modificar, rectificar, suprimir, solicitar la copia de su autorización y formular quejas, reclamos y consultas frente al tratamiento que haga </strong><strong>AEROALLIANCE S.A.S</strong><strong> de sus datos personales.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Acepta SI _____&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; NO _____”.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El acceso y consulta de los datos personales contenidos en los documentos remitidos, quedará de igual forma supeditado, y se deberá dar cumplimiento a lo previsto y dispuesto en las directrices sobre el manejo de datos personales expedida por AEROALLIANCE S.A.S la cual puede ser consultada en la parte superior donde se expone la información de Autorización de Tratamiento de Información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información contenida en este mensaje, así como cualquier archivo anexo, son confidenciales y de uso exclusivo del destinatario. Quien no lo sea, tiene prohibido hacer divulgación, copia o distribución del mensaje, o cualquier acción u omisión tomada en nombre del destinatario, bajo las leyes penales y civiles del país de origen de este correo. Si usted ha recibido este mensaje por error, por favor bórrelo y notifique inmediatamente al remitente.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"hasParallax\":true,\"dimRatio\":50,\"overlayColor\":\"black\",\"minHeight\":316,\"minHeightUnit\":\"px\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"right\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px;min-height:316px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim\"></span><div role=\"img\" class=\"wp-block-cover__image-background wp-image-7326 has-parallax\" style=\"background-position:50% 50%;background-image:url(http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg)\"></div><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Si tiene alguna Petición, Queja, Reclamo y/o Sugerencia</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Por favor háganoslo saber</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:wpforms/form-selector {\"clientId\":\"d54ebb26-db47-440d-b9e0-95b77cbd1cb2\",\"formId\":\"7309\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:false,\\u0022displayDesc\\u0022:false,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022labelSublabelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.55 )\\u0022,\\u0022labelErrorColor\\u0022:\\u0022#d63637\\u0022,\\u0022buttonSize\\u0022:\\u0022medium\\u0022,\\u0022buttonBorderRadius\\u0022:\\u00223px\\u0022,\\u0022buttonBackgroundColor\\u0022:\\u0022#066aab\\u0022,\\u0022buttonTextColor\\u0022:\\u0022#ffffff\\u0022}\"} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":339,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/contact.png\" alt=\"\" class=\"wp-image-339\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/aa/politicas-de-privacidad/\" target=\"_blank\" rel=\"noopener\" title=\"\">Ver Política de Tratamiento de Datos</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'Políticas de Privacidad', '', 'inherit', 'closed', 'closed', '', '7277-autosave-v1', '', '', '2023-09-07 22:09:27', '2023-09-08 03:09:27', '', 7277, 'http://localhost/aa/?p=7772', 0, 'revision', '', 0);
INSERT INTO `aa_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(7773, 1, '2023-09-07 22:06:28', '2023-09-08 03:06:28', '<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\"><!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"dimRatio\":0,\"minHeight\":679,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:679px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-7326\" alt=\"\" src=\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Escribe el título…\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Tratamiento de Datos - Habeas Data</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:list {\"ordered\":true,\"type\":\"1\"} -->\n<ol type=\"1\"><!-- wp:list-item -->\n<li><strong>POLÍTICA DE PROTECCIÓN DE DATOS PERSONALES</strong></li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Con este Manual Interno de Políticas y Procedimientos de Tratamiento de Datos Habeas Data, AEROALLIANCE S.A.S<em>,</em> pretende desarrollar el derecho constitucional que tienen todas las personas a conocer, actualizar y rectificar las informaciones que se hayan recogido sobre ellas en las bases de datos o archivos, y los demás derechos, libertades y garantías constitucionales a que se refiere el Artículo 15 de la Constitución Política; así como el derecho a la información consagrada en el Artículo 20 de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.1. <strong><u>Objetivo General</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El objetivo de la Política de Privacidad de AEROALLIANCE S.A.S es dar a conocer su oferta de servicios de acuerdo a las normas del derecho de Habeas Data, para realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que la sociedad llevará acabo de la información suministrada, será para hacer posible la prestación de nuestros servicios, y comunicar a los viajeros, clientes o usuarios, qué información y datos personales recolectamos, para qué finalidades, cómo los usamos, cuándo los compartimos y cómo los protegemos, así como los derechos que le asisten a los titulares de la información y los procedimientos para ejercerlos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) AEROALLIANCE S.A.S reconoce la importancia de la seguridad, privacidad y confidencialidad de la información y los datos personales de los viajeros, clientes o usuarios suministran a través de los diversos canales de comercialización de nuestros productos y servicios (incluyendo sitio&nbsp;web, oficinas de venta,&nbsp;y call centers), y está comprometido con la protección y tratamiento adecuado de los mismos, conforme al régimen legal de protección de datos personales aplicable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.2. <strong><u>Objetivos específicos</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Realizar oportunamente la actualización, rectificación o supresión de los datos en los términos dados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Actualizar la información reportada por los Responsables del Tratamiento dentro de los cinco (05) días hábiles, contados a partir de su recibo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tramitar las consultas y los reclamos formulados por los Titulares en los términos señalados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Adoptar un manual interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley, y en especial, para la atención de consultas y reclamos por parte de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Registrar en la base de datos la leyenda <em>“reclamo en trámite” </em>en la forma en que se regula la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Insertar en la base de datos la leyenda <em>“información en discusión judicial” </em>una vez notificado por parte de la autoridad competente sobre procesos judiciales relacionados con la calidad del dato personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Abstenerse de circular información que esté siendo controvertida por el Titular y cuyo bloqueo haya sido ordenado por la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Permitir el acceso a la información únicamente a las personas que pueden tener acceso a ella.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Informar a la Superintendencia de Industria y Comercio cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>2. <strong>VIGENCIA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El procedimiento de Manejo de Datos Personales, entrará en vigencia una vez haya sido admitido el registro por la Superintendencia de Industria y Comercio en forma permanente y será de libre consulta por los ciudadanos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>3. <strong>RESPONSABLE DEL MANEJO DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En AEROALLIANCE S.A.S, el responsable del Manejo de Datos del Personal, será el representante Legal y la persona que bajo su responsabilidad designe como Usuario Operativo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>AEROALLIANCE S.A.S no designa a ninguna persona natural o jurídica como encargado de Tratamiento de Datos.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El responsable del Manejo del Tratamiento de datos, será su Representante Legal, Gerente de AEROALLIANCE S.A.S y deberá cumplir los siguientes deberes, sin perjuicio de las demás disposiciones previstas en la Ley 1581 del 2012 y en otras que rijan su actividad, estos son:</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>a) Garantizar al Titular, en todo tiempo, el pleno y efectivo ejercicio del derecho de Hábeas Data.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar y conservar, en las condiciones previstas en la ley, copia de la respectiva autorización otorgada por el Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Informar debidamente al Titular sobre la finalidad de la recolección y los derechos que le asisten por la virtud de la autorización otorgada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Garantizar que la información que se suministre al Usuario Operativo sea veraz, completa, exacta, actualizada, comprobable y comprensible.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Actualizar la información, comunicando de forma oportuna al Usuario Operativo, todas las novedades respecto de los datos que previamente le haya suministrado y adoptar las demás medidas necesarias para que la información suministrada a éste se mantenga actualizada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Rectificar la información cuando sea incorrecta y comunicar lo pertinente al Usuario Operativo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Suministrar al Usuario Operativo, según el caso, únicamente datos cuyo Tratamiento esté previamente autorizado de conformidad con lo previsto en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Exigir al Usuario Operativo en todo momento, el respeto a las condiciones de seguridad y privacidad de la información del titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Tramitar las consultas y reclamos formulados en los términos señalados en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Adoptar un Manual Interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley y en especial, para la atención de consultas y reclamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>l) Informar al Usuario Operativo cuando determinada información se encuentra en discusión por parte del Titular, una vez se haya presentado la reclamación y no haya finalizado el trámite respectivo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>m) Informar a solicitud del Titular sobre el uso datos a sus datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>n) Informar a la autoridad de protección de datos cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>4. <strong>DEFINICIONES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.1. <strong><u>Autorización.</u></strong> Consentimiento previo, expreso e informado del Titular para llevar a cabo el Tratamiento de datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.2. <strong><u>Base de Datos.</u></strong> Conjunto organizado de datos personales que sea objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.3. <strong><u>Dato personal.</u></strong> Cualquier información vinculada o que pueda asociarse a una o varias personas naturales determinadas o determinables.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.4. <strong><u>Datos sensibles.</u></strong> Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.5. <strong><u>Encargado del tratamiento.</u></strong><strong> </strong>Persona natural o jurídica, pública o privada que por sí misma o en asocio con otros, decida sobre la base de datos y/o el Tratamiento de los datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.6. <strong><u>Titular.</u></strong> Persona natural cuyos datos personales sean objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.7. <strong><u>Tratamiento.</u></strong> Cualquier operación o conjunto de operaciones sobre datos personales, tales como la recolección, almacenamiento, uso, circulación o supresión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.8. <strong><u>Usuario Operativo.</u></strong> Persona natural designada por el responsable del Manejo del Tratamiento de datos para la operación de la información sin competencia para el tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>5. <strong>CATEGORÍA DE LOS DATOS TRATADOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La categoría de los datos tratados en AEROALLIANCE S.A.S son:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.1. <strong><u>Datos Privados.</u></strong><strong> </strong>El dato privado es el dato que por su naturaleza íntima o reservada sólo es relevante para el titular, (no controlados).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2. <strong><u>Datos Semi-Privados.</u></strong><strong> </strong>El dato semiprivado es aquel que no tiene naturaleza íntima, reservada, ni pública y cuyo conocimiento o divulgación puede interesar no sólo a su titular sino a cierto sector personas o a la sociedad en general, como el dato financiero y crediticio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Semi-Privados que trata AEROALLIANCE S.A.S en las bases de datos son los requeridos para comercializar los productos o servicios que ofrece esta sociedad.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3. <strong><u>Datos públicos.</u></strong><strong> </strong>Los datos serán públicos cuando la ley o la Constitución así lo establezcan, y cuando no sean de aquellos clasificados como semiprivados o privados. Son públicos, entre otros, los datos contenidos en documentos públicos, sentencias judiciales debidamente ejecutoriadas y los relativos al estado civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Públicos que trata AEROALLIANCE S.A.S serán los contenidos en documentos públicos de identidad, como nombre y apellido, tipo y número de identificación, fecha de nacimiento, direcciones postales y electrónicas (personales y/o laborales), Estado civil y/o parentesco en relación con personas menores de edad o discapacitados solicitantes de nuestros servicios, Nacionalidad y país de residencia, Teléfonos fijos y celulares de contacto (personales y/o laborales) e información necesaria para facilitar el viaje u otros servicios, incluyendo el nombre de acompañante(s) de viaje, contactos para casos de accidente o cualquier otra contingencia, preferencia en asientos, comidas especiales o requerimientos médicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4. <strong><u>Datos Sensibles.</u></strong><strong> </strong>Aquellos que afectan la intimidad del Titular o cuyo uso indebido pueden generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>AEROALLIANCE S.A.S para desarrollar el objeto social no tratara datos sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>6. <strong>BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El tratamiento que recibe esta base de datos por parte de AEROALLIANCE S.A.S. en su condición de responsable y encargado incluye la recolección, el almacenamiento, la custodia, la actualización, la circulación entre las diferentes áreas y el uso de los datos personales para cumplir con la finalidad de la empresa de prestar servicios de Turismo y servicios Técnicos Aeronáuticos. La información se consolida en los diferentes sistemas de información, y en archivos electrónicos. La información circula principalmente mediante los sistemas de información, correos electrónicos y la plataforma Sistema Integrado de Servicios Corporativos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información personal contenida en esta base de datos es resguardada en su mayoría en sistemas de información que son gestionados por roles con usuarios y contraseñas, de igual forma con accesos controlados al sistema. Es de uso exclusivo de AEROALLIANCE S.A.S, y puede ser suprimida, de acuerdo con lo regulado por la ley al respecto. Adicionalmente, se utiliza para darle los usos generales establecidos en el aparte 9 del presente Manual. No se usa para ninguna otra finalidad diferente a la establecida en este Manual.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.1. <strong><u>Base de Datos Personales Socios.</u></strong><strong> </strong>Las bases de datos de los socios de AEROALLIANCE S.A.S son de carácter público</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.2. <strong><u>Base de Datos Personales Colaboradores.</u></strong><strong> </strong>Datos personales del personal de empleados que prestan sus servicios en AEROALLIANCE S.A.S. Su finalidad es mantener actualizada la información para propósitos de pagos de nómina, Seguridad Social con entidades prestadoras de salud EPS, ARL y Caja de Compensación Familiar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.3. <strong><u>Base de Datos Personales de Clientes Externos.</u></strong><strong> </strong>AEROALLIANCE S.A.S utilizará su base de datos para los clientes externos para los siguientes casos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Para fines comerciales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Contabilización.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Cumplimiento de decisiones judiciales y disposiciones administrativas y legales, fiscales y regulatorias.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Cumplimiento de obligaciones contractuales, por lo cual la información podrá ser transferida a terceros, tales como entidades financieras, notarías, listas OFAC y de terrorismo, abogados, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Para realizar los procesos en que se encuentran vinculados los proveedores.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Cualquier otro uso que el proveedor autorice por escrito para el uso de su información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Transmisión de información y datos personales en procesos de auditorías.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>7. <strong>FORMA DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S establece que la base de datos será almacenada en dos formas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.1. <strong><u>Forma Física de la Base de Datos (Formatos en Documento y Medio Electrónico).</u></strong><strong> </strong>Base de datos en documentos físicos tales como folders o carpetas, formatos de entrevistas y hojas de vida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.2. <strong><u>Base de datos en archivos electrónicos</u></strong>. Bases de datos almacenada en medios electrónicos para lo cual usará un servidor en internet y/o computadora personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>8. <strong>RESPONSABILIDAD DEL MANEJO DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En AEROALLIANCE S.A.S, el responsable del tratamiento de Datos es el Representante Legal que aparece en el NIT, que por sí misma, decide sobre la base de datos y/o el tratamiento de los datos que puede hacer cualquier operación o conjunto de operaciones sobre los datos personales, como la recolección, almacenamiento, uso, circulación o supresión, entre otros.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>9. <strong>PROCEDIMIENTO CICLO DE VIDA DEL DATO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.1. <strong><u>Recolección.</u></strong><strong> </strong>Es el momento en que se recogen los datos. Puede ser del propio titular o, de un Tercero o de fuentes accesibles al público.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.2. <strong><u>Almacenamiento y/o Conservación.</u></strong><strong> </strong>Es el momento en que introducimos los datos recogidos en el Sistema Integrado de Servicios Corporativos y los utilizamos para una finalidad específica. Por ejemplo, elaborar cotizaciones, emisiones, facturas, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.3. <strong><u>Uso.</u></strong><strong> </strong>Es el momento en que AEROALLIANCE S.A.S comunica los datos, o el resultado del tratamiento a Terceros. Esta “cesión o comunicación de datos”, solamente se hará cuando el titular o su representante legal lo autorice expresamente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.4. <strong><u>Circulación y supresión del <em>Habeas Data.</em></u></strong><strong> </strong>Se establece como circulación y supresión del Habeas Data, cuando eliminamos definitivamente los datos porque ya no son necesarios o pertinentes para la finalidad para la cual fueron recabados en su momento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>10. <strong>AUTORIZACIÓN MANEJO DE DATOS PERSONALES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De acuerdo al artículo 5° del Decreto 1377 de 2013, en AEROALLIANCE S.A.S como Responsable del Tratamiento en todos los formatos que incluyen manejo de datos, se incluirá el término “<strong><em>aviso </em>de privacidad” </strong>el cual contiene el siguiente texto: “<em>Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales, quien permitirá conocer el uso, actualizar y rectificar las informaciones que ha recopilado en bases de datos o archivos, con el fin de garantizar mis derechos, libertades y garantías constitucionales.”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los datos personales que se encuentren en fuentes de acceso público, con independencia del medio por el cual se tenga acceso, pueden ser tratados por AEROALLIANCE S.A.S, siempre y cuando, por su naturaleza, sean Datos Públicos. Se entenderá que la autorización otorgada por el Titular a AEROALLIANCE S.A.S cumple con los requisitos exigidos en la legislación vigente aplicable, cuando ésta se manifieste:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Por escrito</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) De forma oral</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Mediante conductas inequívocas del Titular que permitan concluir de forma razonable que éste otorgó a la Institución la autorización respectiva.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) En ningún caso su silencio será asimilado por AEROALLIANCE S.A.S como una conducta inequívoca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S ha establecido canales para que el Titular de datos, pueda en todo momento solicitarle como Responsable del Tratamiento, la supresión de sus datos personales y/o revocar la autorización que nos ha otorgado para el Tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.1. <strong><u>Autorización del Titular para el Tratamiento de los Datos Sensibles.</u></strong><strong> </strong>En el tratamiento de datos personales sensibles, cuando dicho tratamiento sea posible conforme a lo establecido en el artículo 6° de la Ley 1581 de 2012, AEROALLIANCE S.A.S cumplirá con las siguientes obligaciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Informar al Titular que por tratarse de datos sensibles no está obligado a autorizar su Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Informar al Titular de forma explícita y previa, además de los requisitos generales de la autorización para la recolección de cualquier tipo de dato personal, cuáles de los datos que serán objeto de Tratamiento son sensibles y la finalidad de su Tratamiento, y además obtiene su consentimiento expreso. Ninguna de las actividades que realiza AEROALLIANCE S.A.S está ni estará condicionada a que usted como Titular suministre sus datos personales sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.2. <strong><u>Uso y Finalidad del Tratamiento de Datos Personales.</u></strong><strong> </strong>AEROALLIANCE S.A.S como entidad respetuosa de la privacidad de las personas reconoce que el Titular de los datos personales tiene derecho a contar con elementos adecuados que garanticen la misma, teniendo en todo caso para ello en cuenta sus responsabilidades, derechos y obligaciones. En virtud de la relación que se ha establecido o establezca entre el titular y AEROALLIANCE S.A.S es importante que el titular conozca que AEROALLIANCE S.A.S., recolecta, registra, almacena, usa sus datos personales, para su propio uso con los propósitos que fueron solicitados o por requerimientos de las entidades públicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales de los Titulares son utilizados por AEROALLIANCE S.A.S para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Ejecutar las actividades propias de AEROALLIANCE S.A.S para cumplir con su función de prestar Servicios de Venta de Productos Turísticos y Servicios Técnicos Aeronáuticos, lo cual se hará con base en la finalidad de la Base de Datos en la que reposan los Datos Personales de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Ofrecerle servicios y/o beneficios que buscan satisfacer las necesidades de los Titulares, o los productos y servicios AEROALLIANCE S.A.S, lo cual pueden hacerse por medios físicos o a través de correos electrónicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Enviar la información a entidades gubernamentales por exigencia legal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Registrar la información en las bases de datos de AEROALLIANCE S.A.S para el envío de información contractual, comercial y obligacional a que hubiere lugar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales serán utilizados por AEROALLIANCE S.A.S sólo para los propósitos aquí señalados, por lo tanto, AEROALLIANCE S.A.S, no venderá, licenciará, transmitirá o divulgará los Datos Personales, salvo que:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Titular autorice expresamente a hacerlo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Sea permitido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Para el manejo interno de los Datos, éstos podrán ser conocidos por el personal autorizado de AEROALLIANCE S.A.S. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S podrá subcontratar a terceros para el procesamiento de determinadas funciones o información. Cuando ello ocurra, dichos terceros estarán obligados a proteger los Datos Personales en los términos exigidos por la ley y en su condición de Encargados del Manejo de las Bases de Datos de AEROALLIANCE S.A.S. En el caso de transmisión de datos personales, AEROALLIANCE S.A.S ha suscrito o suscribirá el contrato de transmisión a que haya lugar en los términos del Decreto 1377 de 2013.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Igualmente, AEROALLIANCE S.A.S podrá transferir o transmitir (según corresponda), guardando las debidas medidas de seguridad, datos personales a otras entidades en Colombia o en el extranjero para la prestación de un mejor servicio, de conformidad con las autorizaciones que hayan sido otorgadas por los Titulares de los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>11. <strong>DERECHOS DE LOS TITULARES DE LOS DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La Ley 1581 de 2012, en su Artículo 8°, establece los siguientes derechos que a usted le asisten como Titular en relación con sus datos personales:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conocer, actualizar y rectificar sus datos personales frente a los Responsables del Tratamiento o Encargados del Tratamiento, este derecho se podrá ejercer, entre otros frente a datos parciales, inexactos, incompletos, fraccionados, que induzcan a error, o aquellos cuyo Tratamiento esté expresamente prohibido o no haya sido autorizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar prueba de la autorización otorgada al Responsable del Tratamiento salvo cuando expresamente se exceptúe como requisito para el Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Ser informado por el Responsable del Tratamiento o el Encargado del Tratamiento, previa solicitud, respecto del uso que les ha dado a sus datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Presentar ante la Superintendencia de Industria y Comercio quejas por infracciones a lo dispuesto en la Ley 1581 de 2012 y en las demás normas que la modifiquen, adicionen o complementen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Revocar la autorización y/o solicitar la supresión del dato cuando en el Tratamiento no se respeten los principios, derechos y garantías constitucionales y legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>12. <strong>CASOS QUE NO SON NECESARIOS DE ACTUALIZACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización del Titular no será necesaria cuando se trate de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Información requerida por una entidad pública o administrativa en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Datos de naturaleza pública.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Casos de urgencia médica o sanitaria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tratamiento de información autorizado por la Ley para fines históricos, estadísticos o científicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Datos relacionados con el Registro Civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Quien acceda a los datos personales sin que medie autorización previa, deberá en todo caso cumplir con las disposiciones contenidas en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>13. <strong>DEBER DE INFORMAR AL TITULAR</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El Responsable del Tratamiento en el momento de solicitar al Titular la autorización, deberá informarle de manera clara y expresa lo siguiente:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Tratamiento al cual serán sometidos sus datos personales y la finalidad del mismo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) El carácter facultativo de la respuesta a las preguntas que le sean hechas, cuando éstas versen sobre datos sensibles o sobre los datos de los niños, niñas y adolescentes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Los derechos que le asisten como Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) La identificación, dirección física o electrónica y teléfono del responsable del Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>14. <strong>PERSONAS A LAS QUE SE LES PUEDE SUMINISTRAR LA INFORMACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información que reúna las condiciones establecidas en la Ley 1581 de 2012, podrá suministrarse a las siguientes personas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) A los Titulares, sus causahabientes o sus representantes legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) A las entidades públicas o administrativas en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) A los terceros autorizados por el Titular o por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>15. <strong>PROCEDIMIENTOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.1. <u style=\"font-weight: bold;\">Consultas.</u><strong> </strong>Se podrá consultar la información personal del Titular que repose en las bases de datos de AEROALLIANCE S.A.S. quien se encargará de suministrar toda la información contenida en el registro individual o que esté vinculada con la identificación del solicitante.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La consulta una vez recibida por AEROALLIANCE S.A.S, será atendida en un término máximo de&nbsp;diez (10) días hábiles&nbsp;contados a partir de la fecha de recibo de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuando no fuere posible atender la consulta dentro de dicho término, se informará al interesado, expresando los motivos de la demora y señalando la nueva fecha en que se atenderá tal consulta, la cual en ningún caso podrá superar los&nbsp;cinco (5) días hábiles siguientes&nbsp;al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.2. <strong><u>Reclamos.</u></strong><strong> </strong>Cuando se considere que la información contenida en una base de datos de AEROALLIANCE S.A.S debe ser objeto de corrección, actualización o supresión, o cuando se advierta el presunto incumplimiento de cualquiera de los deberes contenidos en la Ley de Habeas Data, se podrán presentar reclamación ante AEROALLIANCE S.A.S, la cual será tramitada bajo las siguientes condiciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El reclamo se formulará mediante comunicación escrita dirigida a AEROALLIANCE S.A.S, con la identificación del Titular, la descripción de los hechos que dan lugar al reclamo, la dirección, y acompañando los documentos que se quiera hacer valer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Si el reclamo resulta incompleto, se requerirá al interesado dentro de los cinco&nbsp;(5)&nbsp;díassiguientes a la recepción del reclamo para que subsane las fallas.Transcurridos dos&nbsp;(2) meses&nbsp;desde la fecha del requerimiento, sin que el solicitante presente la información requerida, se entenderá que ha desistido del reclamo. En caso que AEROALLIANCE S.A.S reciba un reclamo del cual no sea competente para resolverlo, AEROALLIANCE S.A.S dará traslado a quien efectivamente corresponda en un término máximo de&nbsp;dos (2) días hábiles&nbsp;e informará al Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Una vez recibido el reclamo completo, AEROALLIANCE S.A.S incluirá en la respectiva base de datos una leyenda que diga&nbsp;\"reclamo en trámite\"&nbsp;y el motivo del mismo, en un término no mayor a&nbsp;dos (2) días hábiles. AEROALLIANCE S.A.S conservará dicha leyenda en el dato objeto de discusión hasta que el reclamo sea decidido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) El término máximo para atender el reclamo será de&nbsp;quince (15) días hábiles&nbsp;contados a partir del día siguiente a la fecha de su recibo. Cuando no fuere posible atender el reclamo dentro de dicho término, AEROALLIANCE S.A.S informará al Titular los motivos de la demora y la nueva fecha en que se atenderá su reclamo, la cual en ningún caso podrá superar los&nbsp;ocho (8) días hábiles&nbsp;siguientes al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textTransform\":\"none\"}}} -->\n<h1 class=\"wp-block-heading\" style=\"text-transform:none\"><strong>Autorización de Tratamiento de Información</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p><strong>HABEAS DATA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización suministrada en el presente formulario faculta a AEROALLIANCE S.A.S para que recopile, almacene, use y suprima los datos personales aquí suministrados, especialmente, aquellos que son definidos como Datos Sensibles (*).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S, como agencia de viajes y demás servicios aeronáuticos, con el propósito de cumplir el ejercicio del derecho de Habeas Data, requiere realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que AEROALLIANCE S.A.S llevará a cabo de la información suministrada, será netamente, administrativo y bajo ninguna circunstancia se realizará Tratamiento de Datos Personales con fines de comercialización o circulación en beneficio de la sociedad. En todo caso aplicarán las excepciones de ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En virtud del Artículo 8 de la Ley 1581 de 2013, el titular de la información personal que es recopilada, tiene los siguientes derechos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer, actualizar, rectificar y suprimir los datos suministrados.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer los usos que se han hecho de la información suministrada, cuando así lo solicite el titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Revocar la autorización y/o solicitar la supresión del dato suministrado cuando en el Tratamiento realizado no se respeten los principios, derechos y garantías constitucionales y legales a favor del titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El titular de la información suministrada, podrá ejercer cualquiera de los derechos mencionados, dirigiendo una petición en este sentido a la dirección electrónica <em>info@aeroalliancesas.com.</em> Recibida la solicitud en los términos dispuestos por AEROALLIANCE S.A.S, se le dará trámite al requerimiento según lo establecido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>(*) Datos Sensibles: Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>POLÍTICA DE PRIVACIDAD</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>La aceptación expresa de esta Política de Privacidad y del tratamiento de la información y los datos personales conforme a los términos de la misma, ocurre cuando el viajero, cliente o usuario titular de los mismos, proporciona los datos en los puntos de atención y venta, incluyendo&nbsp;<a href=\"http://www.avianca.com/co/es/call-center\">Call Center</a>, cuando adquiere o utiliza cualquiera de nuestros productos o servicios, cuando pulsa la función \"Cotizar\", cuando sigue navegando en nuestro sitio web&nbsp;www.aeroalliancesas.com; la prueba de cualquiera de esos hechos, será prueba inequívoca de la aceptación de esta Política de Privacidad y del tratamiento de los Datos Personales de los titulares de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yo titular de la información, en forma expresa y voluntaria Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales incorporados anteriormente tal y como lo dispone el Art. 15 de la Constitución Política Nacional, las Leyes estatutarias 1266 del 2008, la Ley estatutaria 1581 del 2012 y sus Decretos Reglamentarios: Decreto 1727 del 2009, Decreto 2952 del 2010, Decreto 1377 del 2013 y Decreto 886 del 2014; Los datos personales y/o sensibles suministrados, que sean sujetos a tratamiento, deberán ser utilizados por AEROALLIANCE S.A.S con fines históricos y estadísticos, que contribuyan a la comercialización de nuevos servicios aeronáuticos y turísticos relacionados con la prestación del servicio. AEROALLIANCE S.A.S me garantiza que podré ejercer mi derecho de acceso, rectificación y actualización relativo a este tratamiento, a través del sistema que AEROALLIANCE S.A.S establezca para tal fin. Así mismo, me comprometo a actualizar mis datos y eximo a AEROALLIANCE S.A.S, de cualquier responsabilidad derivada del incumplimiento o de la omisión de dicha obligación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Con la aceptación de la presente Política de Privacidad cada uno de nuestros viajeros, clientes o usuarios, en su calidad de titular de la información y de los datos personales recolectados autoriza el tratamiento de dichos datos para todas las finalidades establecidas en este documento y especialmente para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Usar la información y los datos personales suministrados para enviar a los correos electrónicos registrados por el viajero, cliente o usuario, el tiquete y/o el documento que confirme la transacción, así como cualquier información relacionada con el producto o servicio adquirido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Utilizar la información recibida para fines de mercadeo de nuestros productos y servicios, y de los productos y servicios de terceros con los que AEROALLIANCE S.A.S mantenga una relación de negocios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Compartir la información y los datos personales con representantes comerciales, operadores turísticos incluyendo hoteles, compañías de alquiler de vehículos, aseguradoras, entre otros, según sea requerido para el manejo de las reservaciones de planes de viajes y de otros servicios turísticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Suministrar la información y los datos personales a las autoridades de control y vigilancia, administrativas, de policía y judiciales, nacionales e internacionales, en virtud de un requerimiento legal o reglamentario y/o usar o revelar esta información y datos personales en defensa de los derechos y/o de la propiedad de AEROALLIANCE S.A.S, de sus clientes, de nuestro sitio&nbsp;web&nbsp;o de sus usuarios, para la detección o prevención de fraude, para la prevención, detección, aprehensión o persecución de actos criminales o cuando AEROALLIANCE S.A.S de buena fe considere que la entrega de la información y datos personales es en el mejor interés de la seguridad aérea.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Permitir el acceso a la información y datos personales a los auditores o terceros contratados para llevar a cabo procesos de auditoría interna o externa propios de la actividad comercial que desarrollamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Consultar y actualizar la información y los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S parte de la base que la información suministrada por los titulares, sus colaboradores, clientes y proveedores, tanto la propia como la de terceros es veraz, actualizada y cuenta con la autorización de los titulares. Así mismo se advierte que la información recibida y los datos personales contenidos en documentos proporcionados, tiene el propósito de ser utilizada con base en la normatividad sobre Habeas Data- Datos Personales (Art. 15 de la Constitución Política Nacional, la Ley Estatutaria No. 1266 del 2008; los Decretos Reglamentarios Decreto 1727 del 2009 y Decreto 2952 del 2010; la Ley Estatutaria No. 1581 del 2012 y sus Decretos reglamentarios 1377 del 2013 y 886 del 2014; y demás normas aplicables) para lo cual, toda persona que provea información de datos sensibles, será consultada sobre la aceptación o no del manejo de sus datos mediante la siguiente pregunta:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“El titular manifiesta que ha sido informado que </strong><strong>AEROALLIANCE S.A.S</strong><strong> hará tratamiento de sus datos personales con el único y exclusivo propósito de ofrecer los servicios de su actividad comercial y que tiene el derecho a acceder, modificar, rectificar, suprimir, solicitar la copia de su autorización y formular quejas, reclamos y consultas frente al tratamiento que haga </strong><strong>AEROALLIANCE S.A.S</strong><strong> de sus datos personales.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Acepta SI _____&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; NO _____”.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El acceso y consulta de los datos personales contenidos en los documentos remitidos, quedará de igual forma supeditado, y se deberá dar cumplimiento a lo previsto y dispuesto en las directrices sobre el manejo de datos personales expedida por AEROALLIANCE S.A.S la cual puede ser consultada en la parte superior donde se expone la información de Autorización de Tratamiento de Información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información contenida en este mensaje, así como cualquier archivo anexo, son confidenciales y de uso exclusivo del destinatario. Quien no lo sea, tiene prohibido hacer divulgación, copia o distribución del mensaje, o cualquier acción u omisión tomada en nombre del destinatario, bajo las leyes penales y civiles del país de origen de este correo. Si usted ha recibido este mensaje por error, por favor bórrelo y notifique inmediatamente al remitente.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"hasParallax\":true,\"dimRatio\":50,\"overlayColor\":\"black\",\"minHeight\":316,\"minHeightUnit\":\"px\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"right\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px;min-height:316px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim\"></span><div role=\"img\" class=\"wp-block-cover__image-background wp-image-7326 has-parallax\" style=\"background-position:50% 50%;background-image:url(http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg)\"></div><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Si tiene alguna Petición, Queja, Reclamo y/o Sugerencia</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Por favor háganoslo saber</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:wpforms/form-selector {\"clientId\":\"d54ebb26-db47-440d-b9e0-95b77cbd1cb2\",\"formId\":\"7309\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:false,\\u0022displayDesc\\u0022:false,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022labelSublabelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.55 )\\u0022,\\u0022labelErrorColor\\u0022:\\u0022#d63637\\u0022,\\u0022buttonSize\\u0022:\\u0022medium\\u0022,\\u0022buttonBorderRadius\\u0022:\\u00223px\\u0022,\\u0022buttonBackgroundColor\\u0022:\\u0022#066aab\\u0022,\\u0022buttonTextColor\\u0022:\\u0022#ffffff\\u0022}\"} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":339,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/contact.png\" alt=\"\" class=\"wp-image-339\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/aa/politicas-de-privacidad/\" target=\"_blank\" rel=\"noopener\" title=\"\">Ver Política de Tratamiento de Datos</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'Políticas de Privacidad', '', 'inherit', 'closed', 'closed', '', '7277-revision-v1', '', '', '2023-09-07 22:06:28', '2023-09-08 03:06:28', '', 7277, 'http://localhost/aa/?p=7773', 0, 'revision', '', 0);
INSERT INTO `aa_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(7774, 1, '2023-09-07 22:07:49', '2023-09-08 03:07:49', '<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\"><!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"dimRatio\":0,\"minHeight\":679,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:679px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-7326\" alt=\"\" src=\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Escribe el título…\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Tratamiento de Datos - Habeas Data</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:list {\"ordered\":true,\"type\":\"1\"} -->\n<ol type=\"1\"><!-- wp:list-item -->\n<li><strong>POLÍTICA DE PROTECCIÓN DE DATOS PERSONALES</strong></li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">Con este Manual Interno de Políticas y Procedimientos de Tratamiento de Datos Habeas Data, AEROALLIANCE S.A.S<em>,</em> pretende desarrollar el derecho constitucional que tienen todas las personas a conocer, actualizar y rectificar las informaciones que se hayan recogido sobre ellas en las bases de datos o archivos, y los demás derechos, libertades y garantías constitucionales a que se refiere el Artículo 15 de la Constitución Política; así como el derecho a la información consagrada en el Artículo 20 de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.1. <strong><u>Objetivo General</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El objetivo de la Política de Privacidad de AEROALLIANCE S.A.S es dar a conocer su oferta de servicios de acuerdo a las normas del derecho de Habeas Data, para realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que la sociedad llevará acabo de la información suministrada, será para hacer posible la prestación de nuestros servicios, y comunicar a los viajeros, clientes o usuarios, qué información y datos personales recolectamos, para qué finalidades, cómo los usamos, cuándo los compartimos y cómo los protegemos, así como los derechos que le asisten a los titulares de la información y los procedimientos para ejercerlos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) AEROALLIANCE S.A.S reconoce la importancia de la seguridad, privacidad y confidencialidad de la información y los datos personales de los viajeros, clientes o usuarios suministran a través de los diversos canales de comercialización de nuestros productos y servicios (incluyendo sitio&nbsp;web, oficinas de venta,&nbsp;y call centers), y está comprometido con la protección y tratamiento adecuado de los mismos, conforme al régimen legal de protección de datos personales aplicable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.2. <strong><u>Objetivos específicos</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Realizar oportunamente la actualización, rectificación o supresión de los datos en los términos dados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Actualizar la información reportada por los Responsables del Tratamiento dentro de los cinco (05) días hábiles, contados a partir de su recibo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tramitar las consultas y los reclamos formulados por los Titulares en los términos señalados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Adoptar un manual interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley, y en especial, para la atención de consultas y reclamos por parte de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Registrar en la base de datos la leyenda <em>“reclamo en trámite” </em>en la forma en que se regula la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Insertar en la base de datos la leyenda <em>“información en discusión judicial” </em>una vez notificado por parte de la autoridad competente sobre procesos judiciales relacionados con la calidad del dato personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Abstenerse de circular información que esté siendo controvertida por el Titular y cuyo bloqueo haya sido ordenado por la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Permitir el acceso a la información únicamente a las personas que pueden tener acceso a ella.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Informar a la Superintendencia de Industria y Comercio cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>2. <strong>VIGENCIA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El procedimiento de Manejo de Datos Personales, entrará en vigencia una vez haya sido admitido el registro por la Superintendencia de Industria y Comercio en forma permanente y será de libre consulta por los ciudadanos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>3. <strong>RESPONSABLE DEL MANEJO DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En AEROALLIANCE S.A.S, el responsable del Manejo de Datos del Personal, será el representante Legal y la persona que bajo su responsabilidad designe como Usuario Operativo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>AEROALLIANCE S.A.S no designa a ninguna persona natural o jurídica como encargado de Tratamiento de Datos.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El responsable del Manejo del Tratamiento de datos, será su Representante Legal, Gerente de AEROALLIANCE S.A.S y deberá cumplir los siguientes deberes, sin perjuicio de las demás disposiciones previstas en la Ley 1581 del 2012 y en otras que rijan su actividad, estos son:</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>a) Garantizar al Titular, en todo tiempo, el pleno y efectivo ejercicio del derecho de Hábeas Data.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar y conservar, en las condiciones previstas en la ley, copia de la respectiva autorización otorgada por el Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Informar debidamente al Titular sobre la finalidad de la recolección y los derechos que le asisten por la virtud de la autorización otorgada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Garantizar que la información que se suministre al Usuario Operativo sea veraz, completa, exacta, actualizada, comprobable y comprensible.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Actualizar la información, comunicando de forma oportuna al Usuario Operativo, todas las novedades respecto de los datos que previamente le haya suministrado y adoptar las demás medidas necesarias para que la información suministrada a éste se mantenga actualizada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Rectificar la información cuando sea incorrecta y comunicar lo pertinente al Usuario Operativo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Suministrar al Usuario Operativo, según el caso, únicamente datos cuyo Tratamiento esté previamente autorizado de conformidad con lo previsto en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Exigir al Usuario Operativo en todo momento, el respeto a las condiciones de seguridad y privacidad de la información del titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Tramitar las consultas y reclamos formulados en los términos señalados en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Adoptar un Manual Interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley y en especial, para la atención de consultas y reclamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>l) Informar al Usuario Operativo cuando determinada información se encuentra en discusión por parte del Titular, una vez se haya presentado la reclamación y no haya finalizado el trámite respectivo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>m) Informar a solicitud del Titular sobre el uso datos a sus datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>n) Informar a la autoridad de protección de datos cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>4. <strong>DEFINICIONES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.1. <strong><u>Autorización.</u></strong> Consentimiento previo, expreso e informado del Titular para llevar a cabo el Tratamiento de datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.2. <strong><u>Base de Datos.</u></strong> Conjunto organizado de datos personales que sea objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.3. <strong><u>Dato personal.</u></strong> Cualquier información vinculada o que pueda asociarse a una o varias personas naturales determinadas o determinables.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.4. <strong><u>Datos sensibles.</u></strong> Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.5. <strong><u>Encargado del tratamiento.</u></strong><strong> </strong>Persona natural o jurídica, pública o privada que por sí misma o en asocio con otros, decida sobre la base de datos y/o el Tratamiento de los datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.6. <strong><u>Titular.</u></strong> Persona natural cuyos datos personales sean objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.7. <strong><u>Tratamiento.</u></strong> Cualquier operación o conjunto de operaciones sobre datos personales, tales como la recolección, almacenamiento, uso, circulación o supresión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.8. <strong><u>Usuario Operativo.</u></strong> Persona natural designada por el responsable del Manejo del Tratamiento de datos para la operación de la información sin competencia para el tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>5. <strong>CATEGORÍA DE LOS DATOS TRATADOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La categoría de los datos tratados en AEROALLIANCE S.A.S son:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.1. <strong><u>Datos Privados.</u></strong><strong> </strong>El dato privado es el dato que por su naturaleza íntima o reservada sólo es relevante para el titular, (no controlados).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2. <strong><u>Datos Semi-Privados.</u></strong><strong> </strong>El dato semiprivado es aquel que no tiene naturaleza íntima, reservada, ni pública y cuyo conocimiento o divulgación puede interesar no sólo a su titular sino a cierto sector personas o a la sociedad en general, como el dato financiero y crediticio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Semi-Privados que trata AEROALLIANCE S.A.S en las bases de datos son los requeridos para comercializar los productos o servicios que ofrece esta sociedad.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3. <strong><u>Datos públicos.</u></strong><strong> </strong>Los datos serán públicos cuando la ley o la Constitución así lo establezcan, y cuando no sean de aquellos clasificados como semiprivados o privados. Son públicos, entre otros, los datos contenidos en documentos públicos, sentencias judiciales debidamente ejecutoriadas y los relativos al estado civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Públicos que trata AEROALLIANCE S.A.S serán los contenidos en documentos públicos de identidad, como nombre y apellido, tipo y número de identificación, fecha de nacimiento, direcciones postales y electrónicas (personales y/o laborales), Estado civil y/o parentesco en relación con personas menores de edad o discapacitados solicitantes de nuestros servicios, Nacionalidad y país de residencia, Teléfonos fijos y celulares de contacto (personales y/o laborales) e información necesaria para facilitar el viaje u otros servicios, incluyendo el nombre de acompañante(s) de viaje, contactos para casos de accidente o cualquier otra contingencia, preferencia en asientos, comidas especiales o requerimientos médicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4. <strong><u>Datos Sensibles.</u></strong><strong> </strong>Aquellos que afectan la intimidad del Titular o cuyo uso indebido pueden generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>AEROALLIANCE S.A.S para desarrollar el objeto social no tratara datos sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>6. <strong>BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El tratamiento que recibe esta base de datos por parte de AEROALLIANCE S.A.S. en su condición de responsable y encargado incluye la recolección, el almacenamiento, la custodia, la actualización, la circulación entre las diferentes áreas y el uso de los datos personales para cumplir con la finalidad de la empresa de prestar servicios de Turismo y servicios Técnicos Aeronáuticos. La información se consolida en los diferentes sistemas de información, y en archivos electrónicos. La información circula principalmente mediante los sistemas de información, correos electrónicos y la plataforma Sistema Integrado de Servicios Corporativos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información personal contenida en esta base de datos es resguardada en su mayoría en sistemas de información que son gestionados por roles con usuarios y contraseñas, de igual forma con accesos controlados al sistema. Es de uso exclusivo de AEROALLIANCE S.A.S, y puede ser suprimida, de acuerdo con lo regulado por la ley al respecto. Adicionalmente, se utiliza para darle los usos generales establecidos en el aparte 9 del presente Manual. No se usa para ninguna otra finalidad diferente a la establecida en este Manual.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.1. <strong><u>Base de Datos Personales Socios.</u></strong><strong> </strong>Las bases de datos de los socios de AEROALLIANCE S.A.S son de carácter público</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.2. <strong><u>Base de Datos Personales Colaboradores.</u></strong><strong> </strong>Datos personales del personal de empleados que prestan sus servicios en AEROALLIANCE S.A.S. Su finalidad es mantener actualizada la información para propósitos de pagos de nómina, Seguridad Social con entidades prestadoras de salud EPS, ARL y Caja de Compensación Familiar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.3. <strong><u>Base de Datos Personales de Clientes Externos.</u></strong><strong> </strong>AEROALLIANCE S.A.S utilizará su base de datos para los clientes externos para los siguientes casos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Para fines comerciales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Contabilización.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Cumplimiento de decisiones judiciales y disposiciones administrativas y legales, fiscales y regulatorias.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Cumplimiento de obligaciones contractuales, por lo cual la información podrá ser transferida a terceros, tales como entidades financieras, notarías, listas OFAC y de terrorismo, abogados, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Para realizar los procesos en que se encuentran vinculados los proveedores.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Cualquier otro uso que el proveedor autorice por escrito para el uso de su información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Transmisión de información y datos personales en procesos de auditorías.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>7. <strong>FORMA DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S establece que la base de datos será almacenada en dos formas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.1. <strong><u>Forma Física de la Base de Datos (Formatos en Documento y Medio Electrónico).</u></strong><strong> </strong>Base de datos en documentos físicos tales como folders o carpetas, formatos de entrevistas y hojas de vida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.2. <strong><u>Base de datos en archivos electrónicos</u></strong>. Bases de datos almacenada en medios electrónicos para lo cual usará un servidor en internet y/o computadora personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>8. <strong>RESPONSABILIDAD DEL MANEJO DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En AEROALLIANCE S.A.S, el responsable del tratamiento de Datos es el Representante Legal que aparece en el NIT, que por sí misma, decide sobre la base de datos y/o el tratamiento de los datos que puede hacer cualquier operación o conjunto de operaciones sobre los datos personales, como la recolección, almacenamiento, uso, circulación o supresión, entre otros.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>9. <strong>PROCEDIMIENTO CICLO DE VIDA DEL DATO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.1. <strong><u>Recolección.</u></strong><strong> </strong>Es el momento en que se recogen los datos. Puede ser del propio titular o, de un Tercero o de fuentes accesibles al público.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.2. <strong><u>Almacenamiento y/o Conservación.</u></strong><strong> </strong>Es el momento en que introducimos los datos recogidos en el Sistema Integrado de Servicios Corporativos y los utilizamos para una finalidad específica. Por ejemplo, elaborar cotizaciones, emisiones, facturas, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.3. <strong><u>Uso.</u></strong><strong> </strong>Es el momento en que AEROALLIANCE S.A.S comunica los datos, o el resultado del tratamiento a Terceros. Esta “cesión o comunicación de datos”, solamente se hará cuando el titular o su representante legal lo autorice expresamente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.4. <strong><u>Circulación y supresión del <em>Habeas Data.</em></u></strong><strong> </strong>Se establece como circulación y supresión del Habeas Data, cuando eliminamos definitivamente los datos porque ya no son necesarios o pertinentes para la finalidad para la cual fueron recabados en su momento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>10. <strong>AUTORIZACIÓN MANEJO DE DATOS PERSONALES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De acuerdo al artículo 5° del Decreto 1377 de 2013, en AEROALLIANCE S.A.S como Responsable del Tratamiento en todos los formatos que incluyen manejo de datos, se incluirá el término “<strong><em>aviso </em>de privacidad” </strong>el cual contiene el siguiente texto: “<em>Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales, quien permitirá conocer el uso, actualizar y rectificar las informaciones que ha recopilado en bases de datos o archivos, con el fin de garantizar mis derechos, libertades y garantías constitucionales.”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los datos personales que se encuentren en fuentes de acceso público, con independencia del medio por el cual se tenga acceso, pueden ser tratados por AEROALLIANCE S.A.S, siempre y cuando, por su naturaleza, sean Datos Públicos. Se entenderá que la autorización otorgada por el Titular a AEROALLIANCE S.A.S cumple con los requisitos exigidos en la legislación vigente aplicable, cuando ésta se manifieste:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Por escrito</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) De forma oral</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Mediante conductas inequívocas del Titular que permitan concluir de forma razonable que éste otorgó a la Institución la autorización respectiva.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) En ningún caso su silencio será asimilado por AEROALLIANCE S.A.S como una conducta inequívoca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S ha establecido canales para que el Titular de datos, pueda en todo momento solicitarle como Responsable del Tratamiento, la supresión de sus datos personales y/o revocar la autorización que nos ha otorgado para el Tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.1. <strong><u>Autorización del Titular para el Tratamiento de los Datos Sensibles.</u></strong><strong> </strong>En el tratamiento de datos personales sensibles, cuando dicho tratamiento sea posible conforme a lo establecido en el artículo 6° de la Ley 1581 de 2012, AEROALLIANCE S.A.S cumplirá con las siguientes obligaciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Informar al Titular que por tratarse de datos sensibles no está obligado a autorizar su Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Informar al Titular de forma explícita y previa, además de los requisitos generales de la autorización para la recolección de cualquier tipo de dato personal, cuáles de los datos que serán objeto de Tratamiento son sensibles y la finalidad de su Tratamiento, y además obtiene su consentimiento expreso. Ninguna de las actividades que realiza AEROALLIANCE S.A.S está ni estará condicionada a que usted como Titular suministre sus datos personales sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.2. <strong><u>Uso y Finalidad del Tratamiento de Datos Personales.</u></strong><strong> </strong>AEROALLIANCE S.A.S como entidad respetuosa de la privacidad de las personas reconoce que el Titular de los datos personales tiene derecho a contar con elementos adecuados que garanticen la misma, teniendo en todo caso para ello en cuenta sus responsabilidades, derechos y obligaciones. En virtud de la relación que se ha establecido o establezca entre el titular y AEROALLIANCE S.A.S es importante que el titular conozca que AEROALLIANCE S.A.S., recolecta, registra, almacena, usa sus datos personales, para su propio uso con los propósitos que fueron solicitados o por requerimientos de las entidades públicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales de los Titulares son utilizados por AEROALLIANCE S.A.S para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Ejecutar las actividades propias de AEROALLIANCE S.A.S para cumplir con su función de prestar Servicios de Venta de Productos Turísticos y Servicios Técnicos Aeronáuticos, lo cual se hará con base en la finalidad de la Base de Datos en la que reposan los Datos Personales de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Ofrecerle servicios y/o beneficios que buscan satisfacer las necesidades de los Titulares, o los productos y servicios AEROALLIANCE S.A.S, lo cual pueden hacerse por medios físicos o a través de correos electrónicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Enviar la información a entidades gubernamentales por exigencia legal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Registrar la información en las bases de datos de AEROALLIANCE S.A.S para el envío de información contractual, comercial y obligacional a que hubiere lugar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales serán utilizados por AEROALLIANCE S.A.S sólo para los propósitos aquí señalados, por lo tanto, AEROALLIANCE S.A.S, no venderá, licenciará, transmitirá o divulgará los Datos Personales, salvo que:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Titular autorice expresamente a hacerlo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Sea permitido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Para el manejo interno de los Datos, éstos podrán ser conocidos por el personal autorizado de AEROALLIANCE S.A.S. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S podrá subcontratar a terceros para el procesamiento de determinadas funciones o información. Cuando ello ocurra, dichos terceros estarán obligados a proteger los Datos Personales en los términos exigidos por la ley y en su condición de Encargados del Manejo de las Bases de Datos de AEROALLIANCE S.A.S. En el caso de transmisión de datos personales, AEROALLIANCE S.A.S ha suscrito o suscribirá el contrato de transmisión a que haya lugar en los términos del Decreto 1377 de 2013.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Igualmente, AEROALLIANCE S.A.S podrá transferir o transmitir (según corresponda), guardando las debidas medidas de seguridad, datos personales a otras entidades en Colombia o en el extranjero para la prestación de un mejor servicio, de conformidad con las autorizaciones que hayan sido otorgadas por los Titulares de los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>11. <strong>DERECHOS DE LOS TITULARES DE LOS DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La Ley 1581 de 2012, en su Artículo 8°, establece los siguientes derechos que a usted le asisten como Titular en relación con sus datos personales:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conocer, actualizar y rectificar sus datos personales frente a los Responsables del Tratamiento o Encargados del Tratamiento, este derecho se podrá ejercer, entre otros frente a datos parciales, inexactos, incompletos, fraccionados, que induzcan a error, o aquellos cuyo Tratamiento esté expresamente prohibido o no haya sido autorizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar prueba de la autorización otorgada al Responsable del Tratamiento salvo cuando expresamente se exceptúe como requisito para el Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Ser informado por el Responsable del Tratamiento o el Encargado del Tratamiento, previa solicitud, respecto del uso que les ha dado a sus datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Presentar ante la Superintendencia de Industria y Comercio quejas por infracciones a lo dispuesto en la Ley 1581 de 2012 y en las demás normas que la modifiquen, adicionen o complementen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Revocar la autorización y/o solicitar la supresión del dato cuando en el Tratamiento no se respeten los principios, derechos y garantías constitucionales y legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>12. <strong>CASOS QUE NO SON NECESARIOS DE ACTUALIZACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización del Titular no será necesaria cuando se trate de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Información requerida por una entidad pública o administrativa en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Datos de naturaleza pública.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Casos de urgencia médica o sanitaria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tratamiento de información autorizado por la Ley para fines históricos, estadísticos o científicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Datos relacionados con el Registro Civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Quien acceda a los datos personales sin que medie autorización previa, deberá en todo caso cumplir con las disposiciones contenidas en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>13. <strong>DEBER DE INFORMAR AL TITULAR</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El Responsable del Tratamiento en el momento de solicitar al Titular la autorización, deberá informarle de manera clara y expresa lo siguiente:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Tratamiento al cual serán sometidos sus datos personales y la finalidad del mismo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) El carácter facultativo de la respuesta a las preguntas que le sean hechas, cuando éstas versen sobre datos sensibles o sobre los datos de los niños, niñas y adolescentes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Los derechos que le asisten como Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) La identificación, dirección física o electrónica y teléfono del responsable del Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>14. <strong>PERSONAS A LAS QUE SE LES PUEDE SUMINISTRAR LA INFORMACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información que reúna las condiciones establecidas en la Ley 1581 de 2012, podrá suministrarse a las siguientes personas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) A los Titulares, sus causahabientes o sus representantes legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) A las entidades públicas o administrativas en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) A los terceros autorizados por el Titular o por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>15. <strong>PROCEDIMIENTOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.1. <u style=\"font-weight: bold;\">Consultas.</u><strong> </strong>Se podrá consultar la información personal del Titular que repose en las bases de datos de AEROALLIANCE S.A.S. quien se encargará de suministrar toda la información contenida en el registro individual o que esté vinculada con la identificación del solicitante.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La consulta una vez recibida por AEROALLIANCE S.A.S, será atendida en un término máximo de&nbsp;diez (10) días hábiles&nbsp;contados a partir de la fecha de recibo de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuando no fuere posible atender la consulta dentro de dicho término, se informará al interesado, expresando los motivos de la demora y señalando la nueva fecha en que se atenderá tal consulta, la cual en ningún caso podrá superar los&nbsp;cinco (5) días hábiles siguientes&nbsp;al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.2. <strong><u>Reclamos.</u></strong><strong> </strong>Cuando se considere que la información contenida en una base de datos de AEROALLIANCE S.A.S debe ser objeto de corrección, actualización o supresión, o cuando se advierta el presunto incumplimiento de cualquiera de los deberes contenidos en la Ley de Habeas Data, se podrán presentar reclamación ante AEROALLIANCE S.A.S, la cual será tramitada bajo las siguientes condiciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El reclamo se formulará mediante comunicación escrita dirigida a AEROALLIANCE S.A.S, con la identificación del Titular, la descripción de los hechos que dan lugar al reclamo, la dirección, y acompañando los documentos que se quiera hacer valer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Si el reclamo resulta incompleto, se requerirá al interesado dentro de los cinco&nbsp;(5)&nbsp;díassiguientes a la recepción del reclamo para que subsane las fallas.Transcurridos dos&nbsp;(2) meses&nbsp;desde la fecha del requerimiento, sin que el solicitante presente la información requerida, se entenderá que ha desistido del reclamo. En caso que AEROALLIANCE S.A.S reciba un reclamo del cual no sea competente para resolverlo, AEROALLIANCE S.A.S dará traslado a quien efectivamente corresponda en un término máximo de&nbsp;dos (2) días hábiles&nbsp;e informará al Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Una vez recibido el reclamo completo, AEROALLIANCE S.A.S incluirá en la respectiva base de datos una leyenda que diga&nbsp;\"reclamo en trámite\"&nbsp;y el motivo del mismo, en un término no mayor a&nbsp;dos (2) días hábiles. AEROALLIANCE S.A.S conservará dicha leyenda en el dato objeto de discusión hasta que el reclamo sea decidido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) El término máximo para atender el reclamo será de&nbsp;quince (15) días hábiles&nbsp;contados a partir del día siguiente a la fecha de su recibo. Cuando no fuere posible atender el reclamo dentro de dicho término, AEROALLIANCE S.A.S informará al Titular los motivos de la demora y la nueva fecha en que se atenderá su reclamo, la cual en ningún caso podrá superar los&nbsp;ocho (8) días hábiles&nbsp;siguientes al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textTransform\":\"none\"}}} -->\n<h1 class=\"wp-block-heading\" style=\"text-transform:none\"><strong>Autorización de Tratamiento de Información</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p><strong>HABEAS DATA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización suministrada en el presente formulario faculta a AEROALLIANCE S.A.S para que recopile, almacene, use y suprima los datos personales aquí suministrados, especialmente, aquellos que son definidos como Datos Sensibles (*).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S, como agencia de viajes y demás servicios aeronáuticos, con el propósito de cumplir el ejercicio del derecho de Habeas Data, requiere realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que AEROALLIANCE S.A.S llevará a cabo de la información suministrada, será netamente, administrativo y bajo ninguna circunstancia se realizará Tratamiento de Datos Personales con fines de comercialización o circulación en beneficio de la sociedad. En todo caso aplicarán las excepciones de ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En virtud del Artículo 8 de la Ley 1581 de 2013, el titular de la información personal que es recopilada, tiene los siguientes derechos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer, actualizar, rectificar y suprimir los datos suministrados.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer los usos que se han hecho de la información suministrada, cuando así lo solicite el titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Revocar la autorización y/o solicitar la supresión del dato suministrado cuando en el Tratamiento realizado no se respeten los principios, derechos y garantías constitucionales y legales a favor del titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El titular de la información suministrada, podrá ejercer cualquiera de los derechos mencionados, dirigiendo una petición en este sentido a la dirección electrónica <em>info@aeroalliancesas.com.</em> Recibida la solicitud en los términos dispuestos por AEROALLIANCE S.A.S, se le dará trámite al requerimiento según lo establecido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>(*) Datos Sensibles: Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>POLÍTICA DE PRIVACIDAD</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>La aceptación expresa de esta Política de Privacidad y del tratamiento de la información y los datos personales conforme a los términos de la misma, ocurre cuando el viajero, cliente o usuario titular de los mismos, proporciona los datos en los puntos de atención y venta, incluyendo&nbsp;<a href=\"http://www.avianca.com/co/es/call-center\">Call Center</a>, cuando adquiere o utiliza cualquiera de nuestros productos o servicios, cuando pulsa la función \"Cotizar\", cuando sigue navegando en nuestro sitio web&nbsp;www.aeroalliancesas.com; la prueba de cualquiera de esos hechos, será prueba inequívoca de la aceptación de esta Política de Privacidad y del tratamiento de los Datos Personales de los titulares de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yo titular de la información, en forma expresa y voluntaria Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales incorporados anteriormente tal y como lo dispone el Art. 15 de la Constitución Política Nacional, las Leyes estatutarias 1266 del 2008, la Ley estatutaria 1581 del 2012 y sus Decretos Reglamentarios: Decreto 1727 del 2009, Decreto 2952 del 2010, Decreto 1377 del 2013 y Decreto 886 del 2014; Los datos personales y/o sensibles suministrados, que sean sujetos a tratamiento, deberán ser utilizados por AEROALLIANCE S.A.S con fines históricos y estadísticos, que contribuyan a la comercialización de nuevos servicios aeronáuticos y turísticos relacionados con la prestación del servicio. AEROALLIANCE S.A.S me garantiza que podré ejercer mi derecho de acceso, rectificación y actualización relativo a este tratamiento, a través del sistema que AEROALLIANCE S.A.S establezca para tal fin. Así mismo, me comprometo a actualizar mis datos y eximo a AEROALLIANCE S.A.S, de cualquier responsabilidad derivada del incumplimiento o de la omisión de dicha obligación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Con la aceptación de la presente Política de Privacidad cada uno de nuestros viajeros, clientes o usuarios, en su calidad de titular de la información y de los datos personales recolectados autoriza el tratamiento de dichos datos para todas las finalidades establecidas en este documento y especialmente para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Usar la información y los datos personales suministrados para enviar a los correos electrónicos registrados por el viajero, cliente o usuario, el tiquete y/o el documento que confirme la transacción, así como cualquier información relacionada con el producto o servicio adquirido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Utilizar la información recibida para fines de mercadeo de nuestros productos y servicios, y de los productos y servicios de terceros con los que AEROALLIANCE S.A.S mantenga una relación de negocios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Compartir la información y los datos personales con representantes comerciales, operadores turísticos incluyendo hoteles, compañías de alquiler de vehículos, aseguradoras, entre otros, según sea requerido para el manejo de las reservaciones de planes de viajes y de otros servicios turísticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Suministrar la información y los datos personales a las autoridades de control y vigilancia, administrativas, de policía y judiciales, nacionales e internacionales, en virtud de un requerimiento legal o reglamentario y/o usar o revelar esta información y datos personales en defensa de los derechos y/o de la propiedad de AEROALLIANCE S.A.S, de sus clientes, de nuestro sitio&nbsp;web&nbsp;o de sus usuarios, para la detección o prevención de fraude, para la prevención, detección, aprehensión o persecución de actos criminales o cuando AEROALLIANCE S.A.S de buena fe considere que la entrega de la información y datos personales es en el mejor interés de la seguridad aérea.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Permitir el acceso a la información y datos personales a los auditores o terceros contratados para llevar a cabo procesos de auditoría interna o externa propios de la actividad comercial que desarrollamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Consultar y actualizar la información y los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S parte de la base que la información suministrada por los titulares, sus colaboradores, clientes y proveedores, tanto la propia como la de terceros es veraz, actualizada y cuenta con la autorización de los titulares. Así mismo se advierte que la información recibida y los datos personales contenidos en documentos proporcionados, tiene el propósito de ser utilizada con base en la normatividad sobre Habeas Data- Datos Personales (Art. 15 de la Constitución Política Nacional, la Ley Estatutaria No. 1266 del 2008; los Decretos Reglamentarios Decreto 1727 del 2009 y Decreto 2952 del 2010; la Ley Estatutaria No. 1581 del 2012 y sus Decretos reglamentarios 1377 del 2013 y 886 del 2014; y demás normas aplicables) para lo cual, toda persona que provea información de datos sensibles, será consultada sobre la aceptación o no del manejo de sus datos mediante la siguiente pregunta:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“El titular manifiesta que ha sido informado que </strong><strong>AEROALLIANCE S.A.S</strong><strong> hará tratamiento de sus datos personales con el único y exclusivo propósito de ofrecer los servicios de su actividad comercial y que tiene el derecho a acceder, modificar, rectificar, suprimir, solicitar la copia de su autorización y formular quejas, reclamos y consultas frente al tratamiento que haga </strong><strong>AEROALLIANCE S.A.S</strong><strong> de sus datos personales.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Acepta SI _____&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; NO _____”.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El acceso y consulta de los datos personales contenidos en los documentos remitidos, quedará de igual forma supeditado, y se deberá dar cumplimiento a lo previsto y dispuesto en las directrices sobre el manejo de datos personales expedida por AEROALLIANCE S.A.S la cual puede ser consultada en la parte superior donde se expone la información de Autorización de Tratamiento de Información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información contenida en este mensaje, así como cualquier archivo anexo, son confidenciales y de uso exclusivo del destinatario. Quien no lo sea, tiene prohibido hacer divulgación, copia o distribución del mensaje, o cualquier acción u omisión tomada en nombre del destinatario, bajo las leyes penales y civiles del país de origen de este correo. Si usted ha recibido este mensaje por error, por favor bórrelo y notifique inmediatamente al remitente.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"hasParallax\":true,\"dimRatio\":50,\"overlayColor\":\"black\",\"minHeight\":316,\"minHeightUnit\":\"px\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"right\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px;min-height:316px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim\"></span><div role=\"img\" class=\"wp-block-cover__image-background wp-image-7326 has-parallax\" style=\"background-position:50% 50%;background-image:url(http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg)\"></div><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Si tiene alguna Petición, Queja, Reclamo y/o Sugerencia</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Por favor háganoslo saber</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:wpforms/form-selector {\"clientId\":\"d54ebb26-db47-440d-b9e0-95b77cbd1cb2\",\"formId\":\"7309\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:false,\\u0022displayDesc\\u0022:false,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022labelSublabelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.55 )\\u0022,\\u0022labelErrorColor\\u0022:\\u0022#d63637\\u0022,\\u0022buttonSize\\u0022:\\u0022medium\\u0022,\\u0022buttonBorderRadius\\u0022:\\u00223px\\u0022,\\u0022buttonBackgroundColor\\u0022:\\u0022#066aab\\u0022,\\u0022buttonTextColor\\u0022:\\u0022#ffffff\\u0022}\"} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":339,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/contact.png\" alt=\"\" class=\"wp-image-339\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/aa/politicas-de-privacidad/\" target=\"_blank\" rel=\"noopener\" title=\"\">Ver Política de Tratamiento de Datos</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'Políticas de Privacidad', '', 'inherit', 'closed', 'closed', '', '7277-revision-v1', '', '', '2023-09-07 22:07:49', '2023-09-08 03:07:49', '', 7277, 'http://localhost/aa/?p=7774', 0, 'revision', '', 0);
INSERT INTO `aa_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(7775, 1, '2023-09-07 22:08:35', '2023-09-08 03:08:35', '<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\"><!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"dimRatio\":0,\"minHeight\":679,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:679px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-7326\" alt=\"\" src=\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Escribe el título…\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Tratamiento de Datos - Habeas Data</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:list {\"ordered\":true,\"type\":\"1\"} -->\n<ol type=\"1\"><!-- wp:list-item {\"fontSize\":\"medium\"} -->\n<li class=\"has-medium-font-size\"><strong>POLÍTICA DE PROTECCIÓN DE DATOS PERSONALES</strong></li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">Con este Manual Interno de Políticas y Procedimientos de Tratamiento de Datos Habeas Data, AEROALLIANCE S.A.S<em>,</em> pretende desarrollar el derecho constitucional que tienen todas las personas a conocer, actualizar y rectificar las informaciones que se hayan recogido sobre ellas en las bases de datos o archivos, y los demás derechos, libertades y garantías constitucionales a que se refiere el Artículo 15 de la Constitución Política; así como el derecho a la información consagrada en el Artículo 20 de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.1. <strong><u>Objetivo General</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El objetivo de la Política de Privacidad de AEROALLIANCE S.A.S es dar a conocer su oferta de servicios de acuerdo a las normas del derecho de Habeas Data, para realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que la sociedad llevará acabo de la información suministrada, será para hacer posible la prestación de nuestros servicios, y comunicar a los viajeros, clientes o usuarios, qué información y datos personales recolectamos, para qué finalidades, cómo los usamos, cuándo los compartimos y cómo los protegemos, así como los derechos que le asisten a los titulares de la información y los procedimientos para ejercerlos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) AEROALLIANCE S.A.S reconoce la importancia de la seguridad, privacidad y confidencialidad de la información y los datos personales de los viajeros, clientes o usuarios suministran a través de los diversos canales de comercialización de nuestros productos y servicios (incluyendo sitio&nbsp;web, oficinas de venta,&nbsp;y call centers), y está comprometido con la protección y tratamiento adecuado de los mismos, conforme al régimen legal de protección de datos personales aplicable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.2. <strong><u>Objetivos específicos</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Realizar oportunamente la actualización, rectificación o supresión de los datos en los términos dados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Actualizar la información reportada por los Responsables del Tratamiento dentro de los cinco (05) días hábiles, contados a partir de su recibo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tramitar las consultas y los reclamos formulados por los Titulares en los términos señalados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Adoptar un manual interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley, y en especial, para la atención de consultas y reclamos por parte de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Registrar en la base de datos la leyenda <em>“reclamo en trámite” </em>en la forma en que se regula la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Insertar en la base de datos la leyenda <em>“información en discusión judicial” </em>una vez notificado por parte de la autoridad competente sobre procesos judiciales relacionados con la calidad del dato personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Abstenerse de circular información que esté siendo controvertida por el Titular y cuyo bloqueo haya sido ordenado por la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Permitir el acceso a la información únicamente a las personas que pueden tener acceso a ella.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Informar a la Superintendencia de Industria y Comercio cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>2. <strong>VIGENCIA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El procedimiento de Manejo de Datos Personales, entrará en vigencia una vez haya sido admitido el registro por la Superintendencia de Industria y Comercio en forma permanente y será de libre consulta por los ciudadanos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>3. <strong>RESPONSABLE DEL MANEJO DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En AEROALLIANCE S.A.S, el responsable del Manejo de Datos del Personal, será el representante Legal y la persona que bajo su responsabilidad designe como Usuario Operativo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>AEROALLIANCE S.A.S no designa a ninguna persona natural o jurídica como encargado de Tratamiento de Datos.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El responsable del Manejo del Tratamiento de datos, será su Representante Legal, Gerente de AEROALLIANCE S.A.S y deberá cumplir los siguientes deberes, sin perjuicio de las demás disposiciones previstas en la Ley 1581 del 2012 y en otras que rijan su actividad, estos son:</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>a) Garantizar al Titular, en todo tiempo, el pleno y efectivo ejercicio del derecho de Hábeas Data.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar y conservar, en las condiciones previstas en la ley, copia de la respectiva autorización otorgada por el Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Informar debidamente al Titular sobre la finalidad de la recolección y los derechos que le asisten por la virtud de la autorización otorgada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Garantizar que la información que se suministre al Usuario Operativo sea veraz, completa, exacta, actualizada, comprobable y comprensible.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Actualizar la información, comunicando de forma oportuna al Usuario Operativo, todas las novedades respecto de los datos que previamente le haya suministrado y adoptar las demás medidas necesarias para que la información suministrada a éste se mantenga actualizada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Rectificar la información cuando sea incorrecta y comunicar lo pertinente al Usuario Operativo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Suministrar al Usuario Operativo, según el caso, únicamente datos cuyo Tratamiento esté previamente autorizado de conformidad con lo previsto en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Exigir al Usuario Operativo en todo momento, el respeto a las condiciones de seguridad y privacidad de la información del titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Tramitar las consultas y reclamos formulados en los términos señalados en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Adoptar un Manual Interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley y en especial, para la atención de consultas y reclamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>l) Informar al Usuario Operativo cuando determinada información se encuentra en discusión por parte del Titular, una vez se haya presentado la reclamación y no haya finalizado el trámite respectivo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>m) Informar a solicitud del Titular sobre el uso datos a sus datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>n) Informar a la autoridad de protección de datos cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>4. <strong>DEFINICIONES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.1. <strong><u>Autorización.</u></strong> Consentimiento previo, expreso e informado del Titular para llevar a cabo el Tratamiento de datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.2. <strong><u>Base de Datos.</u></strong> Conjunto organizado de datos personales que sea objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.3. <strong><u>Dato personal.</u></strong> Cualquier información vinculada o que pueda asociarse a una o varias personas naturales determinadas o determinables.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.4. <strong><u>Datos sensibles.</u></strong> Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.5. <strong><u>Encargado del tratamiento.</u></strong><strong> </strong>Persona natural o jurídica, pública o privada que por sí misma o en asocio con otros, decida sobre la base de datos y/o el Tratamiento de los datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.6. <strong><u>Titular.</u></strong> Persona natural cuyos datos personales sean objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.7. <strong><u>Tratamiento.</u></strong> Cualquier operación o conjunto de operaciones sobre datos personales, tales como la recolección, almacenamiento, uso, circulación o supresión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.8. <strong><u>Usuario Operativo.</u></strong> Persona natural designada por el responsable del Manejo del Tratamiento de datos para la operación de la información sin competencia para el tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>5. <strong>CATEGORÍA DE LOS DATOS TRATADOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La categoría de los datos tratados en AEROALLIANCE S.A.S son:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.1. <strong><u>Datos Privados.</u></strong><strong> </strong>El dato privado es el dato que por su naturaleza íntima o reservada sólo es relevante para el titular, (no controlados).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2. <strong><u>Datos Semi-Privados.</u></strong><strong> </strong>El dato semiprivado es aquel que no tiene naturaleza íntima, reservada, ni pública y cuyo conocimiento o divulgación puede interesar no sólo a su titular sino a cierto sector personas o a la sociedad en general, como el dato financiero y crediticio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Semi-Privados que trata AEROALLIANCE S.A.S en las bases de datos son los requeridos para comercializar los productos o servicios que ofrece esta sociedad.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3. <strong><u>Datos públicos.</u></strong><strong> </strong>Los datos serán públicos cuando la ley o la Constitución así lo establezcan, y cuando no sean de aquellos clasificados como semiprivados o privados. Son públicos, entre otros, los datos contenidos en documentos públicos, sentencias judiciales debidamente ejecutoriadas y los relativos al estado civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Públicos que trata AEROALLIANCE S.A.S serán los contenidos en documentos públicos de identidad, como nombre y apellido, tipo y número de identificación, fecha de nacimiento, direcciones postales y electrónicas (personales y/o laborales), Estado civil y/o parentesco en relación con personas menores de edad o discapacitados solicitantes de nuestros servicios, Nacionalidad y país de residencia, Teléfonos fijos y celulares de contacto (personales y/o laborales) e información necesaria para facilitar el viaje u otros servicios, incluyendo el nombre de acompañante(s) de viaje, contactos para casos de accidente o cualquier otra contingencia, preferencia en asientos, comidas especiales o requerimientos médicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4. <strong><u>Datos Sensibles.</u></strong><strong> </strong>Aquellos que afectan la intimidad del Titular o cuyo uso indebido pueden generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>AEROALLIANCE S.A.S para desarrollar el objeto social no tratara datos sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>6. <strong>BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El tratamiento que recibe esta base de datos por parte de AEROALLIANCE S.A.S. en su condición de responsable y encargado incluye la recolección, el almacenamiento, la custodia, la actualización, la circulación entre las diferentes áreas y el uso de los datos personales para cumplir con la finalidad de la empresa de prestar servicios de Turismo y servicios Técnicos Aeronáuticos. La información se consolida en los diferentes sistemas de información, y en archivos electrónicos. La información circula principalmente mediante los sistemas de información, correos electrónicos y la plataforma Sistema Integrado de Servicios Corporativos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información personal contenida en esta base de datos es resguardada en su mayoría en sistemas de información que son gestionados por roles con usuarios y contraseñas, de igual forma con accesos controlados al sistema. Es de uso exclusivo de AEROALLIANCE S.A.S, y puede ser suprimida, de acuerdo con lo regulado por la ley al respecto. Adicionalmente, se utiliza para darle los usos generales establecidos en el aparte 9 del presente Manual. No se usa para ninguna otra finalidad diferente a la establecida en este Manual.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.1. <strong><u>Base de Datos Personales Socios.</u></strong><strong> </strong>Las bases de datos de los socios de AEROALLIANCE S.A.S son de carácter público</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.2. <strong><u>Base de Datos Personales Colaboradores.</u></strong><strong> </strong>Datos personales del personal de empleados que prestan sus servicios en AEROALLIANCE S.A.S. Su finalidad es mantener actualizada la información para propósitos de pagos de nómina, Seguridad Social con entidades prestadoras de salud EPS, ARL y Caja de Compensación Familiar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.3. <strong><u>Base de Datos Personales de Clientes Externos.</u></strong><strong> </strong>AEROALLIANCE S.A.S utilizará su base de datos para los clientes externos para los siguientes casos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Para fines comerciales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Contabilización.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Cumplimiento de decisiones judiciales y disposiciones administrativas y legales, fiscales y regulatorias.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Cumplimiento de obligaciones contractuales, por lo cual la información podrá ser transferida a terceros, tales como entidades financieras, notarías, listas OFAC y de terrorismo, abogados, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Para realizar los procesos en que se encuentran vinculados los proveedores.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Cualquier otro uso que el proveedor autorice por escrito para el uso de su información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Transmisión de información y datos personales en procesos de auditorías.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>7. <strong>FORMA DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S establece que la base de datos será almacenada en dos formas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.1. <strong><u>Forma Física de la Base de Datos (Formatos en Documento y Medio Electrónico).</u></strong><strong> </strong>Base de datos en documentos físicos tales como folders o carpetas, formatos de entrevistas y hojas de vida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.2. <strong><u>Base de datos en archivos electrónicos</u></strong>. Bases de datos almacenada en medios electrónicos para lo cual usará un servidor en internet y/o computadora personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>8. <strong>RESPONSABILIDAD DEL MANEJO DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En AEROALLIANCE S.A.S, el responsable del tratamiento de Datos es el Representante Legal que aparece en el NIT, que por sí misma, decide sobre la base de datos y/o el tratamiento de los datos que puede hacer cualquier operación o conjunto de operaciones sobre los datos personales, como la recolección, almacenamiento, uso, circulación o supresión, entre otros.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>9. <strong>PROCEDIMIENTO CICLO DE VIDA DEL DATO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.1. <strong><u>Recolección.</u></strong><strong> </strong>Es el momento en que se recogen los datos. Puede ser del propio titular o, de un Tercero o de fuentes accesibles al público.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.2. <strong><u>Almacenamiento y/o Conservación.</u></strong><strong> </strong>Es el momento en que introducimos los datos recogidos en el Sistema Integrado de Servicios Corporativos y los utilizamos para una finalidad específica. Por ejemplo, elaborar cotizaciones, emisiones, facturas, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.3. <strong><u>Uso.</u></strong><strong> </strong>Es el momento en que AEROALLIANCE S.A.S comunica los datos, o el resultado del tratamiento a Terceros. Esta “cesión o comunicación de datos”, solamente se hará cuando el titular o su representante legal lo autorice expresamente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.4. <strong><u>Circulación y supresión del <em>Habeas Data.</em></u></strong><strong> </strong>Se establece como circulación y supresión del Habeas Data, cuando eliminamos definitivamente los datos porque ya no son necesarios o pertinentes para la finalidad para la cual fueron recabados en su momento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>10. <strong>AUTORIZACIÓN MANEJO DE DATOS PERSONALES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De acuerdo al artículo 5° del Decreto 1377 de 2013, en AEROALLIANCE S.A.S como Responsable del Tratamiento en todos los formatos que incluyen manejo de datos, se incluirá el término “<strong><em>aviso </em>de privacidad” </strong>el cual contiene el siguiente texto: “<em>Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales, quien permitirá conocer el uso, actualizar y rectificar las informaciones que ha recopilado en bases de datos o archivos, con el fin de garantizar mis derechos, libertades y garantías constitucionales.”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los datos personales que se encuentren en fuentes de acceso público, con independencia del medio por el cual se tenga acceso, pueden ser tratados por AEROALLIANCE S.A.S, siempre y cuando, por su naturaleza, sean Datos Públicos. Se entenderá que la autorización otorgada por el Titular a AEROALLIANCE S.A.S cumple con los requisitos exigidos en la legislación vigente aplicable, cuando ésta se manifieste:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Por escrito</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) De forma oral</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Mediante conductas inequívocas del Titular que permitan concluir de forma razonable que éste otorgó a la Institución la autorización respectiva.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) En ningún caso su silencio será asimilado por AEROALLIANCE S.A.S como una conducta inequívoca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S ha establecido canales para que el Titular de datos, pueda en todo momento solicitarle como Responsable del Tratamiento, la supresión de sus datos personales y/o revocar la autorización que nos ha otorgado para el Tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.1. <strong><u>Autorización del Titular para el Tratamiento de los Datos Sensibles.</u></strong><strong> </strong>En el tratamiento de datos personales sensibles, cuando dicho tratamiento sea posible conforme a lo establecido en el artículo 6° de la Ley 1581 de 2012, AEROALLIANCE S.A.S cumplirá con las siguientes obligaciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Informar al Titular que por tratarse de datos sensibles no está obligado a autorizar su Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Informar al Titular de forma explícita y previa, además de los requisitos generales de la autorización para la recolección de cualquier tipo de dato personal, cuáles de los datos que serán objeto de Tratamiento son sensibles y la finalidad de su Tratamiento, y además obtiene su consentimiento expreso. Ninguna de las actividades que realiza AEROALLIANCE S.A.S está ni estará condicionada a que usted como Titular suministre sus datos personales sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.2. <strong><u>Uso y Finalidad del Tratamiento de Datos Personales.</u></strong><strong> </strong>AEROALLIANCE S.A.S como entidad respetuosa de la privacidad de las personas reconoce que el Titular de los datos personales tiene derecho a contar con elementos adecuados que garanticen la misma, teniendo en todo caso para ello en cuenta sus responsabilidades, derechos y obligaciones. En virtud de la relación que se ha establecido o establezca entre el titular y AEROALLIANCE S.A.S es importante que el titular conozca que AEROALLIANCE S.A.S., recolecta, registra, almacena, usa sus datos personales, para su propio uso con los propósitos que fueron solicitados o por requerimientos de las entidades públicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales de los Titulares son utilizados por AEROALLIANCE S.A.S para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Ejecutar las actividades propias de AEROALLIANCE S.A.S para cumplir con su función de prestar Servicios de Venta de Productos Turísticos y Servicios Técnicos Aeronáuticos, lo cual se hará con base en la finalidad de la Base de Datos en la que reposan los Datos Personales de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Ofrecerle servicios y/o beneficios que buscan satisfacer las necesidades de los Titulares, o los productos y servicios AEROALLIANCE S.A.S, lo cual pueden hacerse por medios físicos o a través de correos electrónicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Enviar la información a entidades gubernamentales por exigencia legal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Registrar la información en las bases de datos de AEROALLIANCE S.A.S para el envío de información contractual, comercial y obligacional a que hubiere lugar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales serán utilizados por AEROALLIANCE S.A.S sólo para los propósitos aquí señalados, por lo tanto, AEROALLIANCE S.A.S, no venderá, licenciará, transmitirá o divulgará los Datos Personales, salvo que:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Titular autorice expresamente a hacerlo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Sea permitido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Para el manejo interno de los Datos, éstos podrán ser conocidos por el personal autorizado de AEROALLIANCE S.A.S. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S podrá subcontratar a terceros para el procesamiento de determinadas funciones o información. Cuando ello ocurra, dichos terceros estarán obligados a proteger los Datos Personales en los términos exigidos por la ley y en su condición de Encargados del Manejo de las Bases de Datos de AEROALLIANCE S.A.S. En el caso de transmisión de datos personales, AEROALLIANCE S.A.S ha suscrito o suscribirá el contrato de transmisión a que haya lugar en los términos del Decreto 1377 de 2013.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Igualmente, AEROALLIANCE S.A.S podrá transferir o transmitir (según corresponda), guardando las debidas medidas de seguridad, datos personales a otras entidades en Colombia o en el extranjero para la prestación de un mejor servicio, de conformidad con las autorizaciones que hayan sido otorgadas por los Titulares de los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>11. <strong>DERECHOS DE LOS TITULARES DE LOS DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La Ley 1581 de 2012, en su Artículo 8°, establece los siguientes derechos que a usted le asisten como Titular en relación con sus datos personales:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conocer, actualizar y rectificar sus datos personales frente a los Responsables del Tratamiento o Encargados del Tratamiento, este derecho se podrá ejercer, entre otros frente a datos parciales, inexactos, incompletos, fraccionados, que induzcan a error, o aquellos cuyo Tratamiento esté expresamente prohibido o no haya sido autorizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar prueba de la autorización otorgada al Responsable del Tratamiento salvo cuando expresamente se exceptúe como requisito para el Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Ser informado por el Responsable del Tratamiento o el Encargado del Tratamiento, previa solicitud, respecto del uso que les ha dado a sus datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Presentar ante la Superintendencia de Industria y Comercio quejas por infracciones a lo dispuesto en la Ley 1581 de 2012 y en las demás normas que la modifiquen, adicionen o complementen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Revocar la autorización y/o solicitar la supresión del dato cuando en el Tratamiento no se respeten los principios, derechos y garantías constitucionales y legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>12. <strong>CASOS QUE NO SON NECESARIOS DE ACTUALIZACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización del Titular no será necesaria cuando se trate de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Información requerida por una entidad pública o administrativa en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Datos de naturaleza pública.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Casos de urgencia médica o sanitaria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tratamiento de información autorizado por la Ley para fines históricos, estadísticos o científicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Datos relacionados con el Registro Civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Quien acceda a los datos personales sin que medie autorización previa, deberá en todo caso cumplir con las disposiciones contenidas en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>13. <strong>DEBER DE INFORMAR AL TITULAR</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El Responsable del Tratamiento en el momento de solicitar al Titular la autorización, deberá informarle de manera clara y expresa lo siguiente:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Tratamiento al cual serán sometidos sus datos personales y la finalidad del mismo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) El carácter facultativo de la respuesta a las preguntas que le sean hechas, cuando éstas versen sobre datos sensibles o sobre los datos de los niños, niñas y adolescentes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Los derechos que le asisten como Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) La identificación, dirección física o electrónica y teléfono del responsable del Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>14. <strong>PERSONAS A LAS QUE SE LES PUEDE SUMINISTRAR LA INFORMACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información que reúna las condiciones establecidas en la Ley 1581 de 2012, podrá suministrarse a las siguientes personas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) A los Titulares, sus causahabientes o sus representantes legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) A las entidades públicas o administrativas en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) A los terceros autorizados por el Titular o por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>15. <strong>PROCEDIMIENTOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.1. <u style=\"font-weight: bold;\">Consultas.</u><strong> </strong>Se podrá consultar la información personal del Titular que repose en las bases de datos de AEROALLIANCE S.A.S. quien se encargará de suministrar toda la información contenida en el registro individual o que esté vinculada con la identificación del solicitante.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La consulta una vez recibida por AEROALLIANCE S.A.S, será atendida en un término máximo de&nbsp;diez (10) días hábiles&nbsp;contados a partir de la fecha de recibo de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuando no fuere posible atender la consulta dentro de dicho término, se informará al interesado, expresando los motivos de la demora y señalando la nueva fecha en que se atenderá tal consulta, la cual en ningún caso podrá superar los&nbsp;cinco (5) días hábiles siguientes&nbsp;al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.2. <strong><u>Reclamos.</u></strong><strong> </strong>Cuando se considere que la información contenida en una base de datos de AEROALLIANCE S.A.S debe ser objeto de corrección, actualización o supresión, o cuando se advierta el presunto incumplimiento de cualquiera de los deberes contenidos en la Ley de Habeas Data, se podrán presentar reclamación ante AEROALLIANCE S.A.S, la cual será tramitada bajo las siguientes condiciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El reclamo se formulará mediante comunicación escrita dirigida a AEROALLIANCE S.A.S, con la identificación del Titular, la descripción de los hechos que dan lugar al reclamo, la dirección, y acompañando los documentos que se quiera hacer valer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Si el reclamo resulta incompleto, se requerirá al interesado dentro de los cinco&nbsp;(5)&nbsp;díassiguientes a la recepción del reclamo para que subsane las fallas.Transcurridos dos&nbsp;(2) meses&nbsp;desde la fecha del requerimiento, sin que el solicitante presente la información requerida, se entenderá que ha desistido del reclamo. En caso que AEROALLIANCE S.A.S reciba un reclamo del cual no sea competente para resolverlo, AEROALLIANCE S.A.S dará traslado a quien efectivamente corresponda en un término máximo de&nbsp;dos (2) días hábiles&nbsp;e informará al Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Una vez recibido el reclamo completo, AEROALLIANCE S.A.S incluirá en la respectiva base de datos una leyenda que diga&nbsp;\"reclamo en trámite\"&nbsp;y el motivo del mismo, en un término no mayor a&nbsp;dos (2) días hábiles. AEROALLIANCE S.A.S conservará dicha leyenda en el dato objeto de discusión hasta que el reclamo sea decidido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) El término máximo para atender el reclamo será de&nbsp;quince (15) días hábiles&nbsp;contados a partir del día siguiente a la fecha de su recibo. Cuando no fuere posible atender el reclamo dentro de dicho término, AEROALLIANCE S.A.S informará al Titular los motivos de la demora y la nueva fecha en que se atenderá su reclamo, la cual en ningún caso podrá superar los&nbsp;ocho (8) días hábiles&nbsp;siguientes al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textTransform\":\"none\"}}} -->\n<h1 class=\"wp-block-heading\" style=\"text-transform:none\"><strong>Autorización de Tratamiento de Información</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p><strong>HABEAS DATA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización suministrada en el presente formulario faculta a AEROALLIANCE S.A.S para que recopile, almacene, use y suprima los datos personales aquí suministrados, especialmente, aquellos que son definidos como Datos Sensibles (*).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S, como agencia de viajes y demás servicios aeronáuticos, con el propósito de cumplir el ejercicio del derecho de Habeas Data, requiere realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que AEROALLIANCE S.A.S llevará a cabo de la información suministrada, será netamente, administrativo y bajo ninguna circunstancia se realizará Tratamiento de Datos Personales con fines de comercialización o circulación en beneficio de la sociedad. En todo caso aplicarán las excepciones de ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En virtud del Artículo 8 de la Ley 1581 de 2013, el titular de la información personal que es recopilada, tiene los siguientes derechos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer, actualizar, rectificar y suprimir los datos suministrados.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer los usos que se han hecho de la información suministrada, cuando así lo solicite el titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Revocar la autorización y/o solicitar la supresión del dato suministrado cuando en el Tratamiento realizado no se respeten los principios, derechos y garantías constitucionales y legales a favor del titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El titular de la información suministrada, podrá ejercer cualquiera de los derechos mencionados, dirigiendo una petición en este sentido a la dirección electrónica <em>info@aeroalliancesas.com.</em> Recibida la solicitud en los términos dispuestos por AEROALLIANCE S.A.S, se le dará trámite al requerimiento según lo establecido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>(*) Datos Sensibles: Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>POLÍTICA DE PRIVACIDAD</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>La aceptación expresa de esta Política de Privacidad y del tratamiento de la información y los datos personales conforme a los términos de la misma, ocurre cuando el viajero, cliente o usuario titular de los mismos, proporciona los datos en los puntos de atención y venta, incluyendo&nbsp;<a href=\"http://www.avianca.com/co/es/call-center\">Call Center</a>, cuando adquiere o utiliza cualquiera de nuestros productos o servicios, cuando pulsa la función \"Cotizar\", cuando sigue navegando en nuestro sitio web&nbsp;www.aeroalliancesas.com; la prueba de cualquiera de esos hechos, será prueba inequívoca de la aceptación de esta Política de Privacidad y del tratamiento de los Datos Personales de los titulares de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yo titular de la información, en forma expresa y voluntaria Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales incorporados anteriormente tal y como lo dispone el Art. 15 de la Constitución Política Nacional, las Leyes estatutarias 1266 del 2008, la Ley estatutaria 1581 del 2012 y sus Decretos Reglamentarios: Decreto 1727 del 2009, Decreto 2952 del 2010, Decreto 1377 del 2013 y Decreto 886 del 2014; Los datos personales y/o sensibles suministrados, que sean sujetos a tratamiento, deberán ser utilizados por AEROALLIANCE S.A.S con fines históricos y estadísticos, que contribuyan a la comercialización de nuevos servicios aeronáuticos y turísticos relacionados con la prestación del servicio. AEROALLIANCE S.A.S me garantiza que podré ejercer mi derecho de acceso, rectificación y actualización relativo a este tratamiento, a través del sistema que AEROALLIANCE S.A.S establezca para tal fin. Así mismo, me comprometo a actualizar mis datos y eximo a AEROALLIANCE S.A.S, de cualquier responsabilidad derivada del incumplimiento o de la omisión de dicha obligación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Con la aceptación de la presente Política de Privacidad cada uno de nuestros viajeros, clientes o usuarios, en su calidad de titular de la información y de los datos personales recolectados autoriza el tratamiento de dichos datos para todas las finalidades establecidas en este documento y especialmente para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Usar la información y los datos personales suministrados para enviar a los correos electrónicos registrados por el viajero, cliente o usuario, el tiquete y/o el documento que confirme la transacción, así como cualquier información relacionada con el producto o servicio adquirido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Utilizar la información recibida para fines de mercadeo de nuestros productos y servicios, y de los productos y servicios de terceros con los que AEROALLIANCE S.A.S mantenga una relación de negocios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Compartir la información y los datos personales con representantes comerciales, operadores turísticos incluyendo hoteles, compañías de alquiler de vehículos, aseguradoras, entre otros, según sea requerido para el manejo de las reservaciones de planes de viajes y de otros servicios turísticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Suministrar la información y los datos personales a las autoridades de control y vigilancia, administrativas, de policía y judiciales, nacionales e internacionales, en virtud de un requerimiento legal o reglamentario y/o usar o revelar esta información y datos personales en defensa de los derechos y/o de la propiedad de AEROALLIANCE S.A.S, de sus clientes, de nuestro sitio&nbsp;web&nbsp;o de sus usuarios, para la detección o prevención de fraude, para la prevención, detección, aprehensión o persecución de actos criminales o cuando AEROALLIANCE S.A.S de buena fe considere que la entrega de la información y datos personales es en el mejor interés de la seguridad aérea.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Permitir el acceso a la información y datos personales a los auditores o terceros contratados para llevar a cabo procesos de auditoría interna o externa propios de la actividad comercial que desarrollamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Consultar y actualizar la información y los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S parte de la base que la información suministrada por los titulares, sus colaboradores, clientes y proveedores, tanto la propia como la de terceros es veraz, actualizada y cuenta con la autorización de los titulares. Así mismo se advierte que la información recibida y los datos personales contenidos en documentos proporcionados, tiene el propósito de ser utilizada con base en la normatividad sobre Habeas Data- Datos Personales (Art. 15 de la Constitución Política Nacional, la Ley Estatutaria No. 1266 del 2008; los Decretos Reglamentarios Decreto 1727 del 2009 y Decreto 2952 del 2010; la Ley Estatutaria No. 1581 del 2012 y sus Decretos reglamentarios 1377 del 2013 y 886 del 2014; y demás normas aplicables) para lo cual, toda persona que provea información de datos sensibles, será consultada sobre la aceptación o no del manejo de sus datos mediante la siguiente pregunta:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“El titular manifiesta que ha sido informado que </strong><strong>AEROALLIANCE S.A.S</strong><strong> hará tratamiento de sus datos personales con el único y exclusivo propósito de ofrecer los servicios de su actividad comercial y que tiene el derecho a acceder, modificar, rectificar, suprimir, solicitar la copia de su autorización y formular quejas, reclamos y consultas frente al tratamiento que haga </strong><strong>AEROALLIANCE S.A.S</strong><strong> de sus datos personales.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Acepta SI _____&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; NO _____”.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El acceso y consulta de los datos personales contenidos en los documentos remitidos, quedará de igual forma supeditado, y se deberá dar cumplimiento a lo previsto y dispuesto en las directrices sobre el manejo de datos personales expedida por AEROALLIANCE S.A.S la cual puede ser consultada en la parte superior donde se expone la información de Autorización de Tratamiento de Información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información contenida en este mensaje, así como cualquier archivo anexo, son confidenciales y de uso exclusivo del destinatario. Quien no lo sea, tiene prohibido hacer divulgación, copia o distribución del mensaje, o cualquier acción u omisión tomada en nombre del destinatario, bajo las leyes penales y civiles del país de origen de este correo. Si usted ha recibido este mensaje por error, por favor bórrelo y notifique inmediatamente al remitente.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"hasParallax\":true,\"dimRatio\":50,\"overlayColor\":\"black\",\"minHeight\":316,\"minHeightUnit\":\"px\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"right\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px;min-height:316px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim\"></span><div role=\"img\" class=\"wp-block-cover__image-background wp-image-7326 has-parallax\" style=\"background-position:50% 50%;background-image:url(http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg)\"></div><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Si tiene alguna Petición, Queja, Reclamo y/o Sugerencia</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Por favor háganoslo saber</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:wpforms/form-selector {\"clientId\":\"d54ebb26-db47-440d-b9e0-95b77cbd1cb2\",\"formId\":\"7309\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:false,\\u0022displayDesc\\u0022:false,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022labelSublabelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.55 )\\u0022,\\u0022labelErrorColor\\u0022:\\u0022#d63637\\u0022,\\u0022buttonSize\\u0022:\\u0022medium\\u0022,\\u0022buttonBorderRadius\\u0022:\\u00223px\\u0022,\\u0022buttonBackgroundColor\\u0022:\\u0022#066aab\\u0022,\\u0022buttonTextColor\\u0022:\\u0022#ffffff\\u0022}\"} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":339,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/contact.png\" alt=\"\" class=\"wp-image-339\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/aa/politicas-de-privacidad/\" target=\"_blank\" rel=\"noopener\" title=\"\">Ver Política de Tratamiento de Datos</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'Políticas de Privacidad', '', 'inherit', 'closed', 'closed', '', '7277-revision-v1', '', '', '2023-09-07 22:08:35', '2023-09-08 03:08:35', '', 7277, 'http://localhost/aa/?p=7775', 0, 'revision', '', 0);
INSERT INTO `aa_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(7776, 1, '2023-09-07 22:08:59', '2023-09-08 03:08:59', '<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\"><!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"dimRatio\":0,\"minHeight\":679,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:679px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-7326\" alt=\"\" src=\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Escribe el título…\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Tratamiento de Datos - Habeas Data</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:list {\"ordered\":true,\"type\":\"1\"} -->\n<ol type=\"1\"><!-- wp:list-item -->\n<li><strong>POLÍTICA DE PROTECCIÓN DE DATOS PERSONALES</strong></li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">Con este Manual Interno de Políticas y Procedimientos de Tratamiento de Datos Habeas Data, AEROALLIANCE S.A.S<em>,</em> pretende desarrollar el derecho constitucional que tienen todas las personas a conocer, actualizar y rectificar las informaciones que se hayan recogido sobre ellas en las bases de datos o archivos, y los demás derechos, libertades y garantías constitucionales a que se refiere el Artículo 15 de la Constitución Política; así como el derecho a la información consagrada en el Artículo 20 de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.1. <strong><u>Objetivo General</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El objetivo de la Política de Privacidad de AEROALLIANCE S.A.S es dar a conocer su oferta de servicios de acuerdo a las normas del derecho de Habeas Data, para realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que la sociedad llevará acabo de la información suministrada, será para hacer posible la prestación de nuestros servicios, y comunicar a los viajeros, clientes o usuarios, qué información y datos personales recolectamos, para qué finalidades, cómo los usamos, cuándo los compartimos y cómo los protegemos, así como los derechos que le asisten a los titulares de la información y los procedimientos para ejercerlos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) AEROALLIANCE S.A.S reconoce la importancia de la seguridad, privacidad y confidencialidad de la información y los datos personales de los viajeros, clientes o usuarios suministran a través de los diversos canales de comercialización de nuestros productos y servicios (incluyendo sitio&nbsp;web, oficinas de venta,&nbsp;y call centers), y está comprometido con la protección y tratamiento adecuado de los mismos, conforme al régimen legal de protección de datos personales aplicable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.2. <strong><u>Objetivos específicos</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Realizar oportunamente la actualización, rectificación o supresión de los datos en los términos dados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Actualizar la información reportada por los Responsables del Tratamiento dentro de los cinco (05) días hábiles, contados a partir de su recibo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tramitar las consultas y los reclamos formulados por los Titulares en los términos señalados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Adoptar un manual interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley, y en especial, para la atención de consultas y reclamos por parte de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Registrar en la base de datos la leyenda <em>“reclamo en trámite” </em>en la forma en que se regula la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Insertar en la base de datos la leyenda <em>“información en discusión judicial” </em>una vez notificado por parte de la autoridad competente sobre procesos judiciales relacionados con la calidad del dato personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Abstenerse de circular información que esté siendo controvertida por el Titular y cuyo bloqueo haya sido ordenado por la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Permitir el acceso a la información únicamente a las personas que pueden tener acceso a ella.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Informar a la Superintendencia de Industria y Comercio cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>2. <strong>VIGENCIA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El procedimiento de Manejo de Datos Personales, entrará en vigencia una vez haya sido admitido el registro por la Superintendencia de Industria y Comercio en forma permanente y será de libre consulta por los ciudadanos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>3. <strong>RESPONSABLE DEL MANEJO DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En AEROALLIANCE S.A.S, el responsable del Manejo de Datos del Personal, será el representante Legal y la persona que bajo su responsabilidad designe como Usuario Operativo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>AEROALLIANCE S.A.S no designa a ninguna persona natural o jurídica como encargado de Tratamiento de Datos.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El responsable del Manejo del Tratamiento de datos, será su Representante Legal, Gerente de AEROALLIANCE S.A.S y deberá cumplir los siguientes deberes, sin perjuicio de las demás disposiciones previstas en la Ley 1581 del 2012 y en otras que rijan su actividad, estos son:</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>a) Garantizar al Titular, en todo tiempo, el pleno y efectivo ejercicio del derecho de Hábeas Data.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar y conservar, en las condiciones previstas en la ley, copia de la respectiva autorización otorgada por el Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Informar debidamente al Titular sobre la finalidad de la recolección y los derechos que le asisten por la virtud de la autorización otorgada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Garantizar que la información que se suministre al Usuario Operativo sea veraz, completa, exacta, actualizada, comprobable y comprensible.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Actualizar la información, comunicando de forma oportuna al Usuario Operativo, todas las novedades respecto de los datos que previamente le haya suministrado y adoptar las demás medidas necesarias para que la información suministrada a éste se mantenga actualizada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Rectificar la información cuando sea incorrecta y comunicar lo pertinente al Usuario Operativo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Suministrar al Usuario Operativo, según el caso, únicamente datos cuyo Tratamiento esté previamente autorizado de conformidad con lo previsto en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Exigir al Usuario Operativo en todo momento, el respeto a las condiciones de seguridad y privacidad de la información del titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Tramitar las consultas y reclamos formulados en los términos señalados en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Adoptar un Manual Interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley y en especial, para la atención de consultas y reclamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>l) Informar al Usuario Operativo cuando determinada información se encuentra en discusión por parte del Titular, una vez se haya presentado la reclamación y no haya finalizado el trámite respectivo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>m) Informar a solicitud del Titular sobre el uso datos a sus datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>n) Informar a la autoridad de protección de datos cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>4. <strong>DEFINICIONES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.1. <strong><u>Autorización.</u></strong> Consentimiento previo, expreso e informado del Titular para llevar a cabo el Tratamiento de datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.2. <strong><u>Base de Datos.</u></strong> Conjunto organizado de datos personales que sea objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.3. <strong><u>Dato personal.</u></strong> Cualquier información vinculada o que pueda asociarse a una o varias personas naturales determinadas o determinables.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.4. <strong><u>Datos sensibles.</u></strong> Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.5. <strong><u>Encargado del tratamiento.</u></strong><strong> </strong>Persona natural o jurídica, pública o privada que por sí misma o en asocio con otros, decida sobre la base de datos y/o el Tratamiento de los datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.6. <strong><u>Titular.</u></strong> Persona natural cuyos datos personales sean objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.7. <strong><u>Tratamiento.</u></strong> Cualquier operación o conjunto de operaciones sobre datos personales, tales como la recolección, almacenamiento, uso, circulación o supresión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.8. <strong><u>Usuario Operativo.</u></strong> Persona natural designada por el responsable del Manejo del Tratamiento de datos para la operación de la información sin competencia para el tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>5. <strong>CATEGORÍA DE LOS DATOS TRATADOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La categoría de los datos tratados en AEROALLIANCE S.A.S son:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.1. <strong><u>Datos Privados.</u></strong><strong> </strong>El dato privado es el dato que por su naturaleza íntima o reservada sólo es relevante para el titular, (no controlados).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2. <strong><u>Datos Semi-Privados.</u></strong><strong> </strong>El dato semiprivado es aquel que no tiene naturaleza íntima, reservada, ni pública y cuyo conocimiento o divulgación puede interesar no sólo a su titular sino a cierto sector personas o a la sociedad en general, como el dato financiero y crediticio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Semi-Privados que trata AEROALLIANCE S.A.S en las bases de datos son los requeridos para comercializar los productos o servicios que ofrece esta sociedad.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3. <strong><u>Datos públicos.</u></strong><strong> </strong>Los datos serán públicos cuando la ley o la Constitución así lo establezcan, y cuando no sean de aquellos clasificados como semiprivados o privados. Son públicos, entre otros, los datos contenidos en documentos públicos, sentencias judiciales debidamente ejecutoriadas y los relativos al estado civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Públicos que trata AEROALLIANCE S.A.S serán los contenidos en documentos públicos de identidad, como nombre y apellido, tipo y número de identificación, fecha de nacimiento, direcciones postales y electrónicas (personales y/o laborales), Estado civil y/o parentesco en relación con personas menores de edad o discapacitados solicitantes de nuestros servicios, Nacionalidad y país de residencia, Teléfonos fijos y celulares de contacto (personales y/o laborales) e información necesaria para facilitar el viaje u otros servicios, incluyendo el nombre de acompañante(s) de viaje, contactos para casos de accidente o cualquier otra contingencia, preferencia en asientos, comidas especiales o requerimientos médicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4. <strong><u>Datos Sensibles.</u></strong><strong> </strong>Aquellos que afectan la intimidad del Titular o cuyo uso indebido pueden generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>AEROALLIANCE S.A.S para desarrollar el objeto social no tratara datos sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>6. <strong>BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El tratamiento que recibe esta base de datos por parte de AEROALLIANCE S.A.S. en su condición de responsable y encargado incluye la recolección, el almacenamiento, la custodia, la actualización, la circulación entre las diferentes áreas y el uso de los datos personales para cumplir con la finalidad de la empresa de prestar servicios de Turismo y servicios Técnicos Aeronáuticos. La información se consolida en los diferentes sistemas de información, y en archivos electrónicos. La información circula principalmente mediante los sistemas de información, correos electrónicos y la plataforma Sistema Integrado de Servicios Corporativos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información personal contenida en esta base de datos es resguardada en su mayoría en sistemas de información que son gestionados por roles con usuarios y contraseñas, de igual forma con accesos controlados al sistema. Es de uso exclusivo de AEROALLIANCE S.A.S, y puede ser suprimida, de acuerdo con lo regulado por la ley al respecto. Adicionalmente, se utiliza para darle los usos generales establecidos en el aparte 9 del presente Manual. No se usa para ninguna otra finalidad diferente a la establecida en este Manual.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.1. <strong><u>Base de Datos Personales Socios.</u></strong><strong> </strong>Las bases de datos de los socios de AEROALLIANCE S.A.S son de carácter público</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.2. <strong><u>Base de Datos Personales Colaboradores.</u></strong><strong> </strong>Datos personales del personal de empleados que prestan sus servicios en AEROALLIANCE S.A.S. Su finalidad es mantener actualizada la información para propósitos de pagos de nómina, Seguridad Social con entidades prestadoras de salud EPS, ARL y Caja de Compensación Familiar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.3. <strong><u>Base de Datos Personales de Clientes Externos.</u></strong><strong> </strong>AEROALLIANCE S.A.S utilizará su base de datos para los clientes externos para los siguientes casos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Para fines comerciales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Contabilización.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Cumplimiento de decisiones judiciales y disposiciones administrativas y legales, fiscales y regulatorias.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Cumplimiento de obligaciones contractuales, por lo cual la información podrá ser transferida a terceros, tales como entidades financieras, notarías, listas OFAC y de terrorismo, abogados, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Para realizar los procesos en que se encuentran vinculados los proveedores.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Cualquier otro uso que el proveedor autorice por escrito para el uso de su información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Transmisión de información y datos personales en procesos de auditorías.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>7. <strong>FORMA DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S establece que la base de datos será almacenada en dos formas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.1. <strong><u>Forma Física de la Base de Datos (Formatos en Documento y Medio Electrónico).</u></strong><strong> </strong>Base de datos en documentos físicos tales como folders o carpetas, formatos de entrevistas y hojas de vida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.2. <strong><u>Base de datos en archivos electrónicos</u></strong>. Bases de datos almacenada en medios electrónicos para lo cual usará un servidor en internet y/o computadora personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>8. <strong>RESPONSABILIDAD DEL MANEJO DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En AEROALLIANCE S.A.S, el responsable del tratamiento de Datos es el Representante Legal que aparece en el NIT, que por sí misma, decide sobre la base de datos y/o el tratamiento de los datos que puede hacer cualquier operación o conjunto de operaciones sobre los datos personales, como la recolección, almacenamiento, uso, circulación o supresión, entre otros.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>9. <strong>PROCEDIMIENTO CICLO DE VIDA DEL DATO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.1. <strong><u>Recolección.</u></strong><strong> </strong>Es el momento en que se recogen los datos. Puede ser del propio titular o, de un Tercero o de fuentes accesibles al público.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.2. <strong><u>Almacenamiento y/o Conservación.</u></strong><strong> </strong>Es el momento en que introducimos los datos recogidos en el Sistema Integrado de Servicios Corporativos y los utilizamos para una finalidad específica. Por ejemplo, elaborar cotizaciones, emisiones, facturas, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.3. <strong><u>Uso.</u></strong><strong> </strong>Es el momento en que AEROALLIANCE S.A.S comunica los datos, o el resultado del tratamiento a Terceros. Esta “cesión o comunicación de datos”, solamente se hará cuando el titular o su representante legal lo autorice expresamente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.4. <strong><u>Circulación y supresión del <em>Habeas Data.</em></u></strong><strong> </strong>Se establece como circulación y supresión del Habeas Data, cuando eliminamos definitivamente los datos porque ya no son necesarios o pertinentes para la finalidad para la cual fueron recabados en su momento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>10. <strong>AUTORIZACIÓN MANEJO DE DATOS PERSONALES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De acuerdo al artículo 5° del Decreto 1377 de 2013, en AEROALLIANCE S.A.S como Responsable del Tratamiento en todos los formatos que incluyen manejo de datos, se incluirá el término “<strong><em>aviso </em>de privacidad” </strong>el cual contiene el siguiente texto: “<em>Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales, quien permitirá conocer el uso, actualizar y rectificar las informaciones que ha recopilado en bases de datos o archivos, con el fin de garantizar mis derechos, libertades y garantías constitucionales.”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los datos personales que se encuentren en fuentes de acceso público, con independencia del medio por el cual se tenga acceso, pueden ser tratados por AEROALLIANCE S.A.S, siempre y cuando, por su naturaleza, sean Datos Públicos. Se entenderá que la autorización otorgada por el Titular a AEROALLIANCE S.A.S cumple con los requisitos exigidos en la legislación vigente aplicable, cuando ésta se manifieste:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Por escrito</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) De forma oral</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Mediante conductas inequívocas del Titular que permitan concluir de forma razonable que éste otorgó a la Institución la autorización respectiva.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) En ningún caso su silencio será asimilado por AEROALLIANCE S.A.S como una conducta inequívoca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S ha establecido canales para que el Titular de datos, pueda en todo momento solicitarle como Responsable del Tratamiento, la supresión de sus datos personales y/o revocar la autorización que nos ha otorgado para el Tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.1. <strong><u>Autorización del Titular para el Tratamiento de los Datos Sensibles.</u></strong><strong> </strong>En el tratamiento de datos personales sensibles, cuando dicho tratamiento sea posible conforme a lo establecido en el artículo 6° de la Ley 1581 de 2012, AEROALLIANCE S.A.S cumplirá con las siguientes obligaciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Informar al Titular que por tratarse de datos sensibles no está obligado a autorizar su Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Informar al Titular de forma explícita y previa, además de los requisitos generales de la autorización para la recolección de cualquier tipo de dato personal, cuáles de los datos que serán objeto de Tratamiento son sensibles y la finalidad de su Tratamiento, y además obtiene su consentimiento expreso. Ninguna de las actividades que realiza AEROALLIANCE S.A.S está ni estará condicionada a que usted como Titular suministre sus datos personales sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.2. <strong><u>Uso y Finalidad del Tratamiento de Datos Personales.</u></strong><strong> </strong>AEROALLIANCE S.A.S como entidad respetuosa de la privacidad de las personas reconoce que el Titular de los datos personales tiene derecho a contar con elementos adecuados que garanticen la misma, teniendo en todo caso para ello en cuenta sus responsabilidades, derechos y obligaciones. En virtud de la relación que se ha establecido o establezca entre el titular y AEROALLIANCE S.A.S es importante que el titular conozca que AEROALLIANCE S.A.S., recolecta, registra, almacena, usa sus datos personales, para su propio uso con los propósitos que fueron solicitados o por requerimientos de las entidades públicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales de los Titulares son utilizados por AEROALLIANCE S.A.S para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Ejecutar las actividades propias de AEROALLIANCE S.A.S para cumplir con su función de prestar Servicios de Venta de Productos Turísticos y Servicios Técnicos Aeronáuticos, lo cual se hará con base en la finalidad de la Base de Datos en la que reposan los Datos Personales de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Ofrecerle servicios y/o beneficios que buscan satisfacer las necesidades de los Titulares, o los productos y servicios AEROALLIANCE S.A.S, lo cual pueden hacerse por medios físicos o a través de correos electrónicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Enviar la información a entidades gubernamentales por exigencia legal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Registrar la información en las bases de datos de AEROALLIANCE S.A.S para el envío de información contractual, comercial y obligacional a que hubiere lugar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales serán utilizados por AEROALLIANCE S.A.S sólo para los propósitos aquí señalados, por lo tanto, AEROALLIANCE S.A.S, no venderá, licenciará, transmitirá o divulgará los Datos Personales, salvo que:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Titular autorice expresamente a hacerlo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Sea permitido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Para el manejo interno de los Datos, éstos podrán ser conocidos por el personal autorizado de AEROALLIANCE S.A.S. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S podrá subcontratar a terceros para el procesamiento de determinadas funciones o información. Cuando ello ocurra, dichos terceros estarán obligados a proteger los Datos Personales en los términos exigidos por la ley y en su condición de Encargados del Manejo de las Bases de Datos de AEROALLIANCE S.A.S. En el caso de transmisión de datos personales, AEROALLIANCE S.A.S ha suscrito o suscribirá el contrato de transmisión a que haya lugar en los términos del Decreto 1377 de 2013.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Igualmente, AEROALLIANCE S.A.S podrá transferir o transmitir (según corresponda), guardando las debidas medidas de seguridad, datos personales a otras entidades en Colombia o en el extranjero para la prestación de un mejor servicio, de conformidad con las autorizaciones que hayan sido otorgadas por los Titulares de los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>11. <strong>DERECHOS DE LOS TITULARES DE LOS DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La Ley 1581 de 2012, en su Artículo 8°, establece los siguientes derechos que a usted le asisten como Titular en relación con sus datos personales:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conocer, actualizar y rectificar sus datos personales frente a los Responsables del Tratamiento o Encargados del Tratamiento, este derecho se podrá ejercer, entre otros frente a datos parciales, inexactos, incompletos, fraccionados, que induzcan a error, o aquellos cuyo Tratamiento esté expresamente prohibido o no haya sido autorizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar prueba de la autorización otorgada al Responsable del Tratamiento salvo cuando expresamente se exceptúe como requisito para el Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Ser informado por el Responsable del Tratamiento o el Encargado del Tratamiento, previa solicitud, respecto del uso que les ha dado a sus datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Presentar ante la Superintendencia de Industria y Comercio quejas por infracciones a lo dispuesto en la Ley 1581 de 2012 y en las demás normas que la modifiquen, adicionen o complementen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Revocar la autorización y/o solicitar la supresión del dato cuando en el Tratamiento no se respeten los principios, derechos y garantías constitucionales y legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>12. <strong>CASOS QUE NO SON NECESARIOS DE ACTUALIZACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización del Titular no será necesaria cuando se trate de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Información requerida por una entidad pública o administrativa en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Datos de naturaleza pública.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Casos de urgencia médica o sanitaria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tratamiento de información autorizado por la Ley para fines históricos, estadísticos o científicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Datos relacionados con el Registro Civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Quien acceda a los datos personales sin que medie autorización previa, deberá en todo caso cumplir con las disposiciones contenidas en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>13. <strong>DEBER DE INFORMAR AL TITULAR</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El Responsable del Tratamiento en el momento de solicitar al Titular la autorización, deberá informarle de manera clara y expresa lo siguiente:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Tratamiento al cual serán sometidos sus datos personales y la finalidad del mismo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) El carácter facultativo de la respuesta a las preguntas que le sean hechas, cuando éstas versen sobre datos sensibles o sobre los datos de los niños, niñas y adolescentes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Los derechos que le asisten como Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) La identificación, dirección física o electrónica y teléfono del responsable del Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>14. <strong>PERSONAS A LAS QUE SE LES PUEDE SUMINISTRAR LA INFORMACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información que reúna las condiciones establecidas en la Ley 1581 de 2012, podrá suministrarse a las siguientes personas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) A los Titulares, sus causahabientes o sus representantes legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) A las entidades públicas o administrativas en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) A los terceros autorizados por el Titular o por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>15. <strong>PROCEDIMIENTOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.1. <u style=\"font-weight: bold;\">Consultas.</u><strong> </strong>Se podrá consultar la información personal del Titular que repose en las bases de datos de AEROALLIANCE S.A.S. quien se encargará de suministrar toda la información contenida en el registro individual o que esté vinculada con la identificación del solicitante.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La consulta una vez recibida por AEROALLIANCE S.A.S, será atendida en un término máximo de&nbsp;diez (10) días hábiles&nbsp;contados a partir de la fecha de recibo de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuando no fuere posible atender la consulta dentro de dicho término, se informará al interesado, expresando los motivos de la demora y señalando la nueva fecha en que se atenderá tal consulta, la cual en ningún caso podrá superar los&nbsp;cinco (5) días hábiles siguientes&nbsp;al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.2. <strong><u>Reclamos.</u></strong><strong> </strong>Cuando se considere que la información contenida en una base de datos de AEROALLIANCE S.A.S debe ser objeto de corrección, actualización o supresión, o cuando se advierta el presunto incumplimiento de cualquiera de los deberes contenidos en la Ley de Habeas Data, se podrán presentar reclamación ante AEROALLIANCE S.A.S, la cual será tramitada bajo las siguientes condiciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El reclamo se formulará mediante comunicación escrita dirigida a AEROALLIANCE S.A.S, con la identificación del Titular, la descripción de los hechos que dan lugar al reclamo, la dirección, y acompañando los documentos que se quiera hacer valer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Si el reclamo resulta incompleto, se requerirá al interesado dentro de los cinco&nbsp;(5)&nbsp;díassiguientes a la recepción del reclamo para que subsane las fallas.Transcurridos dos&nbsp;(2) meses&nbsp;desde la fecha del requerimiento, sin que el solicitante presente la información requerida, se entenderá que ha desistido del reclamo. En caso que AEROALLIANCE S.A.S reciba un reclamo del cual no sea competente para resolverlo, AEROALLIANCE S.A.S dará traslado a quien efectivamente corresponda en un término máximo de&nbsp;dos (2) días hábiles&nbsp;e informará al Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Una vez recibido el reclamo completo, AEROALLIANCE S.A.S incluirá en la respectiva base de datos una leyenda que diga&nbsp;\"reclamo en trámite\"&nbsp;y el motivo del mismo, en un término no mayor a&nbsp;dos (2) días hábiles. AEROALLIANCE S.A.S conservará dicha leyenda en el dato objeto de discusión hasta que el reclamo sea decidido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) El término máximo para atender el reclamo será de&nbsp;quince (15) días hábiles&nbsp;contados a partir del día siguiente a la fecha de su recibo. Cuando no fuere posible atender el reclamo dentro de dicho término, AEROALLIANCE S.A.S informará al Titular los motivos de la demora y la nueva fecha en que se atenderá su reclamo, la cual en ningún caso podrá superar los&nbsp;ocho (8) días hábiles&nbsp;siguientes al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textTransform\":\"none\"}}} -->\n<h1 class=\"wp-block-heading\" style=\"text-transform:none\"><strong>Autorización de Tratamiento de Información</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p><strong>HABEAS DATA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización suministrada en el presente formulario faculta a AEROALLIANCE S.A.S para que recopile, almacene, use y suprima los datos personales aquí suministrados, especialmente, aquellos que son definidos como Datos Sensibles (*).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S, como agencia de viajes y demás servicios aeronáuticos, con el propósito de cumplir el ejercicio del derecho de Habeas Data, requiere realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que AEROALLIANCE S.A.S llevará a cabo de la información suministrada, será netamente, administrativo y bajo ninguna circunstancia se realizará Tratamiento de Datos Personales con fines de comercialización o circulación en beneficio de la sociedad. En todo caso aplicarán las excepciones de ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En virtud del Artículo 8 de la Ley 1581 de 2013, el titular de la información personal que es recopilada, tiene los siguientes derechos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer, actualizar, rectificar y suprimir los datos suministrados.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer los usos que se han hecho de la información suministrada, cuando así lo solicite el titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Revocar la autorización y/o solicitar la supresión del dato suministrado cuando en el Tratamiento realizado no se respeten los principios, derechos y garantías constitucionales y legales a favor del titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El titular de la información suministrada, podrá ejercer cualquiera de los derechos mencionados, dirigiendo una petición en este sentido a la dirección electrónica <em>info@aeroalliancesas.com.</em> Recibida la solicitud en los términos dispuestos por AEROALLIANCE S.A.S, se le dará trámite al requerimiento según lo establecido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>(*) Datos Sensibles: Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>POLÍTICA DE PRIVACIDAD</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>La aceptación expresa de esta Política de Privacidad y del tratamiento de la información y los datos personales conforme a los términos de la misma, ocurre cuando el viajero, cliente o usuario titular de los mismos, proporciona los datos en los puntos de atención y venta, incluyendo&nbsp;<a href=\"http://www.avianca.com/co/es/call-center\">Call Center</a>, cuando adquiere o utiliza cualquiera de nuestros productos o servicios, cuando pulsa la función \"Cotizar\", cuando sigue navegando en nuestro sitio web&nbsp;www.aeroalliancesas.com; la prueba de cualquiera de esos hechos, será prueba inequívoca de la aceptación de esta Política de Privacidad y del tratamiento de los Datos Personales de los titulares de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yo titular de la información, en forma expresa y voluntaria Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales incorporados anteriormente tal y como lo dispone el Art. 15 de la Constitución Política Nacional, las Leyes estatutarias 1266 del 2008, la Ley estatutaria 1581 del 2012 y sus Decretos Reglamentarios: Decreto 1727 del 2009, Decreto 2952 del 2010, Decreto 1377 del 2013 y Decreto 886 del 2014; Los datos personales y/o sensibles suministrados, que sean sujetos a tratamiento, deberán ser utilizados por AEROALLIANCE S.A.S con fines históricos y estadísticos, que contribuyan a la comercialización de nuevos servicios aeronáuticos y turísticos relacionados con la prestación del servicio. AEROALLIANCE S.A.S me garantiza que podré ejercer mi derecho de acceso, rectificación y actualización relativo a este tratamiento, a través del sistema que AEROALLIANCE S.A.S establezca para tal fin. Así mismo, me comprometo a actualizar mis datos y eximo a AEROALLIANCE S.A.S, de cualquier responsabilidad derivada del incumplimiento o de la omisión de dicha obligación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Con la aceptación de la presente Política de Privacidad cada uno de nuestros viajeros, clientes o usuarios, en su calidad de titular de la información y de los datos personales recolectados autoriza el tratamiento de dichos datos para todas las finalidades establecidas en este documento y especialmente para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Usar la información y los datos personales suministrados para enviar a los correos electrónicos registrados por el viajero, cliente o usuario, el tiquete y/o el documento que confirme la transacción, así como cualquier información relacionada con el producto o servicio adquirido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Utilizar la información recibida para fines de mercadeo de nuestros productos y servicios, y de los productos y servicios de terceros con los que AEROALLIANCE S.A.S mantenga una relación de negocios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Compartir la información y los datos personales con representantes comerciales, operadores turísticos incluyendo hoteles, compañías de alquiler de vehículos, aseguradoras, entre otros, según sea requerido para el manejo de las reservaciones de planes de viajes y de otros servicios turísticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Suministrar la información y los datos personales a las autoridades de control y vigilancia, administrativas, de policía y judiciales, nacionales e internacionales, en virtud de un requerimiento legal o reglamentario y/o usar o revelar esta información y datos personales en defensa de los derechos y/o de la propiedad de AEROALLIANCE S.A.S, de sus clientes, de nuestro sitio&nbsp;web&nbsp;o de sus usuarios, para la detección o prevención de fraude, para la prevención, detección, aprehensión o persecución de actos criminales o cuando AEROALLIANCE S.A.S de buena fe considere que la entrega de la información y datos personales es en el mejor interés de la seguridad aérea.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Permitir el acceso a la información y datos personales a los auditores o terceros contratados para llevar a cabo procesos de auditoría interna o externa propios de la actividad comercial que desarrollamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Consultar y actualizar la información y los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S parte de la base que la información suministrada por los titulares, sus colaboradores, clientes y proveedores, tanto la propia como la de terceros es veraz, actualizada y cuenta con la autorización de los titulares. Así mismo se advierte que la información recibida y los datos personales contenidos en documentos proporcionados, tiene el propósito de ser utilizada con base en la normatividad sobre Habeas Data- Datos Personales (Art. 15 de la Constitución Política Nacional, la Ley Estatutaria No. 1266 del 2008; los Decretos Reglamentarios Decreto 1727 del 2009 y Decreto 2952 del 2010; la Ley Estatutaria No. 1581 del 2012 y sus Decretos reglamentarios 1377 del 2013 y 886 del 2014; y demás normas aplicables) para lo cual, toda persona que provea información de datos sensibles, será consultada sobre la aceptación o no del manejo de sus datos mediante la siguiente pregunta:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“El titular manifiesta que ha sido informado que </strong><strong>AEROALLIANCE S.A.S</strong><strong> hará tratamiento de sus datos personales con el único y exclusivo propósito de ofrecer los servicios de su actividad comercial y que tiene el derecho a acceder, modificar, rectificar, suprimir, solicitar la copia de su autorización y formular quejas, reclamos y consultas frente al tratamiento que haga </strong><strong>AEROALLIANCE S.A.S</strong><strong> de sus datos personales.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Acepta SI _____&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; NO _____”.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El acceso y consulta de los datos personales contenidos en los documentos remitidos, quedará de igual forma supeditado, y se deberá dar cumplimiento a lo previsto y dispuesto en las directrices sobre el manejo de datos personales expedida por AEROALLIANCE S.A.S la cual puede ser consultada en la parte superior donde se expone la información de Autorización de Tratamiento de Información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información contenida en este mensaje, así como cualquier archivo anexo, son confidenciales y de uso exclusivo del destinatario. Quien no lo sea, tiene prohibido hacer divulgación, copia o distribución del mensaje, o cualquier acción u omisión tomada en nombre del destinatario, bajo las leyes penales y civiles del país de origen de este correo. Si usted ha recibido este mensaje por error, por favor bórrelo y notifique inmediatamente al remitente.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"hasParallax\":true,\"dimRatio\":50,\"overlayColor\":\"black\",\"minHeight\":316,\"minHeightUnit\":\"px\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"right\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px;min-height:316px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim\"></span><div role=\"img\" class=\"wp-block-cover__image-background wp-image-7326 has-parallax\" style=\"background-position:50% 50%;background-image:url(http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg)\"></div><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Si tiene alguna Petición, Queja, Reclamo y/o Sugerencia</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Por favor háganoslo saber</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:wpforms/form-selector {\"clientId\":\"d54ebb26-db47-440d-b9e0-95b77cbd1cb2\",\"formId\":\"7309\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:false,\\u0022displayDesc\\u0022:false,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022labelSublabelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.55 )\\u0022,\\u0022labelErrorColor\\u0022:\\u0022#d63637\\u0022,\\u0022buttonSize\\u0022:\\u0022medium\\u0022,\\u0022buttonBorderRadius\\u0022:\\u00223px\\u0022,\\u0022buttonBackgroundColor\\u0022:\\u0022#066aab\\u0022,\\u0022buttonTextColor\\u0022:\\u0022#ffffff\\u0022}\"} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":339,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/contact.png\" alt=\"\" class=\"wp-image-339\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/aa/politicas-de-privacidad/\" target=\"_blank\" rel=\"noopener\" title=\"\">Ver Política de Tratamiento de Datos</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'Políticas de Privacidad', '', 'inherit', 'closed', 'closed', '', '7277-revision-v1', '', '', '2023-09-07 22:08:59', '2023-09-08 03:08:59', '', 7277, 'http://localhost/aa/?p=7776', 0, 'revision', '', 0);
INSERT INTO `aa_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(7777, 1, '2023-09-07 22:09:32', '2023-09-08 03:09:32', '<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\",\"textColor\":\"black\"} -->\n<div class=\"wp-block-group alignfull has-black-color has-white-background-color has-text-color has-background\"><!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"dimRatio\":0,\"minHeight\":679,\"minHeightUnit\":\"px\",\"contentPosition\":\"center center\",\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:679px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><img class=\"wp-block-cover__image-background wp-image-7326\" alt=\"\" src=\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Escribe el título…\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Tratamiento de Datos - Habeas Data</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:list {\"ordered\":true,\"type\":\"1\"} -->\n<ol type=\"1\"><!-- wp:list-item -->\n<li><strong>POLÍTICA DE PROTECCIÓN DE DATOS PERSONALES</strong></li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">Con este Manual Interno de Políticas y Procedimientos de Tratamiento de Datos Habeas Data, AEROALLIANCE S.A.S<em>,</em> pretende desarrollar el derecho constitucional que tienen todas las personas a conocer, actualizar y rectificar las informaciones que se hayan recogido sobre ellas en las bases de datos o archivos, y los demás derechos, libertades y garantías constitucionales a que se refiere el Artículo 15 de la Constitución Política; así como el derecho a la información consagrada en el Artículo 20 de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"textColor\":\"black\"} -->\n<p class=\"has-black-color has-text-color\">1.1. <strong><u>Objetivo General</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El objetivo de la Política de Privacidad de AEROALLIANCE S.A.S es dar a conocer su oferta de servicios de acuerdo a las normas del derecho de Habeas Data, para realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que la sociedad llevará acabo de la información suministrada, será para hacer posible la prestación de nuestros servicios, y comunicar a los viajeros, clientes o usuarios, qué información y datos personales recolectamos, para qué finalidades, cómo los usamos, cuándo los compartimos y cómo los protegemos, así como los derechos que le asisten a los titulares de la información y los procedimientos para ejercerlos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) AEROALLIANCE S.A.S reconoce la importancia de la seguridad, privacidad y confidencialidad de la información y los datos personales de los viajeros, clientes o usuarios suministran a través de los diversos canales de comercialización de nuestros productos y servicios (incluyendo sitio&nbsp;web, oficinas de venta,&nbsp;y call centers), y está comprometido con la protección y tratamiento adecuado de los mismos, conforme al régimen legal de protección de datos personales aplicable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>1.2. <strong><u>Objetivos específicos</u></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Realizar oportunamente la actualización, rectificación o supresión de los datos en los términos dados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Actualizar la información reportada por los Responsables del Tratamiento dentro de los cinco (05) días hábiles, contados a partir de su recibo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tramitar las consultas y los reclamos formulados por los Titulares en los términos señalados por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Adoptar un manual interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley, y en especial, para la atención de consultas y reclamos por parte de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Registrar en la base de datos la leyenda <em>“reclamo en trámite” </em>en la forma en que se regula la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Insertar en la base de datos la leyenda <em>“información en discusión judicial” </em>una vez notificado por parte de la autoridad competente sobre procesos judiciales relacionados con la calidad del dato personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Abstenerse de circular información que esté siendo controvertida por el Titular y cuyo bloqueo haya sido ordenado por la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Permitir el acceso a la información únicamente a las personas que pueden tener acceso a ella.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Informar a la Superintendencia de Industria y Comercio cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>2. <strong>VIGENCIA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El procedimiento de Manejo de Datos Personales, entrará en vigencia una vez haya sido admitido el registro por la Superintendencia de Industria y Comercio en forma permanente y será de libre consulta por los ciudadanos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>3. <strong>RESPONSABLE DEL MANEJO DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>En AEROALLIANCE S.A.S, el responsable del Manejo de Datos del Personal, será el representante Legal y la persona que bajo su responsabilidad designe como Usuario Operativo.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>AEROALLIANCE S.A.S no designa a ninguna persona natural o jurídica como encargado de Tratamiento de Datos.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>El responsable del Manejo del Tratamiento de datos, será su Representante Legal, Gerente de AEROALLIANCE S.A.S y deberá cumplir los siguientes deberes, sin perjuicio de las demás disposiciones previstas en la Ley 1581 del 2012 y en otras que rijan su actividad, estos son:</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>a) Garantizar al Titular, en todo tiempo, el pleno y efectivo ejercicio del derecho de Hábeas Data.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar y conservar, en las condiciones previstas en la ley, copia de la respectiva autorización otorgada por el Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Informar debidamente al Titular sobre la finalidad de la recolección y los derechos que le asisten por la virtud de la autorización otorgada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Conservar la información bajo las condiciones de seguridad necesarias para impedir su adulteración, pérdida, consulta, uso o acceso no autorizado o fraudulento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Garantizar que la información que se suministre al Usuario Operativo sea veraz, completa, exacta, actualizada, comprobable y comprensible.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Actualizar la información, comunicando de forma oportuna al Usuario Operativo, todas las novedades respecto de los datos que previamente le haya suministrado y adoptar las demás medidas necesarias para que la información suministrada a éste se mantenga actualizada.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Rectificar la información cuando sea incorrecta y comunicar lo pertinente al Usuario Operativo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>h) Suministrar al Usuario Operativo, según el caso, únicamente datos cuyo Tratamiento esté previamente autorizado de conformidad con lo previsto en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>i) Exigir al Usuario Operativo en todo momento, el respeto a las condiciones de seguridad y privacidad de la información del titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>j) Tramitar las consultas y reclamos formulados en los términos señalados en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>k) Adoptar un Manual Interno de políticas y procedimientos para garantizar el adecuado cumplimiento de la Ley y en especial, para la atención de consultas y reclamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>l) Informar al Usuario Operativo cuando determinada información se encuentra en discusión por parte del Titular, una vez se haya presentado la reclamación y no haya finalizado el trámite respectivo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>m) Informar a solicitud del Titular sobre el uso datos a sus datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>n) Informar a la autoridad de protección de datos cuando se presenten violaciones a los códigos de seguridad y existan riesgos en la administración de la información de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o) Cumplir las instrucciones y requerimientos que imparta la Superintendencia de Industria y Comercio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>4. <strong>DEFINICIONES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.1. <strong><u>Autorización.</u></strong> Consentimiento previo, expreso e informado del Titular para llevar a cabo el Tratamiento de datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.2. <strong><u>Base de Datos.</u></strong> Conjunto organizado de datos personales que sea objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.3. <strong><u>Dato personal.</u></strong> Cualquier información vinculada o que pueda asociarse a una o varias personas naturales determinadas o determinables.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.4. <strong><u>Datos sensibles.</u></strong> Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.5. <strong><u>Encargado del tratamiento.</u></strong><strong> </strong>Persona natural o jurídica, pública o privada que por sí misma o en asocio con otros, decida sobre la base de datos y/o el Tratamiento de los datos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.6. <strong><u>Titular.</u></strong> Persona natural cuyos datos personales sean objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.7. <strong><u>Tratamiento.</u></strong> Cualquier operación o conjunto de operaciones sobre datos personales, tales como la recolección, almacenamiento, uso, circulación o supresión.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>4.8. <strong><u>Usuario Operativo.</u></strong> Persona natural designada por el responsable del Manejo del Tratamiento de datos para la operación de la información sin competencia para el tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>5. <strong>CATEGORÍA DE LOS DATOS TRATADOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La categoría de los datos tratados en AEROALLIANCE S.A.S son:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.1. <strong><u>Datos Privados.</u></strong><strong> </strong>El dato privado es el dato que por su naturaleza íntima o reservada sólo es relevante para el titular, (no controlados).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2. <strong><u>Datos Semi-Privados.</u></strong><strong> </strong>El dato semiprivado es aquel que no tiene naturaleza íntima, reservada, ni pública y cuyo conocimiento o divulgación puede interesar no sólo a su titular sino a cierto sector personas o a la sociedad en general, como el dato financiero y crediticio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.2.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Semi-Privados que trata AEROALLIANCE S.A.S en las bases de datos son los requeridos para comercializar los productos o servicios que ofrece esta sociedad.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3. <strong><u>Datos públicos.</u></strong><strong> </strong>Los datos serán públicos cuando la ley o la Constitución así lo establezcan, y cuando no sean de aquellos clasificados como semiprivados o privados. Son públicos, entre otros, los datos contenidos en documentos públicos, sentencias judiciales debidamente ejecutoriadas y los relativos al estado civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.3.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>Los Datos Públicos que trata AEROALLIANCE S.A.S serán los contenidos en documentos públicos de identidad, como nombre y apellido, tipo y número de identificación, fecha de nacimiento, direcciones postales y electrónicas (personales y/o laborales), Estado civil y/o parentesco en relación con personas menores de edad o discapacitados solicitantes de nuestros servicios, Nacionalidad y país de residencia, Teléfonos fijos y celulares de contacto (personales y/o laborales) e información necesaria para facilitar el viaje u otros servicios, incluyendo el nombre de acompañante(s) de viaje, contactos para casos de accidente o cualquier otra contingencia, preferencia en asientos, comidas especiales o requerimientos médicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4. <strong><u>Datos Sensibles.</u></strong><strong> </strong>Aquellos que afectan la intimidad del Titular o cuyo uso indebido pueden generar su discriminación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5.4.1. <strong><u>Finalidad del tratamiento.</u></strong><strong> </strong>AEROALLIANCE S.A.S para desarrollar el objeto social no tratara datos sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>6. <strong>BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El tratamiento que recibe esta base de datos por parte de AEROALLIANCE S.A.S. en su condición de responsable y encargado incluye la recolección, el almacenamiento, la custodia, la actualización, la circulación entre las diferentes áreas y el uso de los datos personales para cumplir con la finalidad de la empresa de prestar servicios de Turismo y servicios Técnicos Aeronáuticos. La información se consolida en los diferentes sistemas de información, y en archivos electrónicos. La información circula principalmente mediante los sistemas de información, correos electrónicos y la plataforma Sistema Integrado de Servicios Corporativos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información personal contenida en esta base de datos es resguardada en su mayoría en sistemas de información que son gestionados por roles con usuarios y contraseñas, de igual forma con accesos controlados al sistema. Es de uso exclusivo de AEROALLIANCE S.A.S, y puede ser suprimida, de acuerdo con lo regulado por la ley al respecto. Adicionalmente, se utiliza para darle los usos generales establecidos en el aparte 9 del presente Manual. No se usa para ninguna otra finalidad diferente a la establecida en este Manual.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.1. <strong><u>Base de Datos Personales Socios.</u></strong><strong> </strong>Las bases de datos de los socios de AEROALLIANCE S.A.S son de carácter público</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.2. <strong><u>Base de Datos Personales Colaboradores.</u></strong><strong> </strong>Datos personales del personal de empleados que prestan sus servicios en AEROALLIANCE S.A.S. Su finalidad es mantener actualizada la información para propósitos de pagos de nómina, Seguridad Social con entidades prestadoras de salud EPS, ARL y Caja de Compensación Familiar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>6.3. <strong><u>Base de Datos Personales de Clientes Externos.</u></strong><strong> </strong>AEROALLIANCE S.A.S utilizará su base de datos para los clientes externos para los siguientes casos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Para fines comerciales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Contabilización.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Cumplimiento de decisiones judiciales y disposiciones administrativas y legales, fiscales y regulatorias.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Cumplimiento de obligaciones contractuales, por lo cual la información podrá ser transferida a terceros, tales como entidades financieras, notarías, listas OFAC y de terrorismo, abogados, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Para realizar los procesos en que se encuentran vinculados los proveedores.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Cualquier otro uso que el proveedor autorice por escrito para el uso de su información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>g) Transmisión de información y datos personales en procesos de auditorías.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>7. <strong>FORMA DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S establece que la base de datos será almacenada en dos formas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.1. <strong><u>Forma Física de la Base de Datos (Formatos en Documento y Medio Electrónico).</u></strong><strong> </strong>Base de datos en documentos físicos tales como folders o carpetas, formatos de entrevistas y hojas de vida.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>7.2. <strong><u>Base de datos en archivos electrónicos</u></strong>. Bases de datos almacenada en medios electrónicos para lo cual usará un servidor en internet y/o computadora personal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>8. <strong>RESPONSABILIDAD DEL MANEJO DE LAS BASES DE DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En AEROALLIANCE S.A.S, el responsable del tratamiento de Datos es el Representante Legal que aparece en el NIT, que por sí misma, decide sobre la base de datos y/o el tratamiento de los datos que puede hacer cualquier operación o conjunto de operaciones sobre los datos personales, como la recolección, almacenamiento, uso, circulación o supresión, entre otros.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>9. <strong>PROCEDIMIENTO CICLO DE VIDA DEL DATO</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.1. <strong><u>Recolección.</u></strong><strong> </strong>Es el momento en que se recogen los datos. Puede ser del propio titular o, de un Tercero o de fuentes accesibles al público.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.2. <strong><u>Almacenamiento y/o Conservación.</u></strong><strong> </strong>Es el momento en que introducimos los datos recogidos en el Sistema Integrado de Servicios Corporativos y los utilizamos para una finalidad específica. Por ejemplo, elaborar cotizaciones, emisiones, facturas, etc.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.3. <strong><u>Uso.</u></strong><strong> </strong>Es el momento en que AEROALLIANCE S.A.S comunica los datos, o el resultado del tratamiento a Terceros. Esta “cesión o comunicación de datos”, solamente se hará cuando el titular o su representante legal lo autorice expresamente.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>9.4. <strong><u>Circulación y supresión del <em>Habeas Data.</em></u></strong><strong> </strong>Se establece como circulación y supresión del Habeas Data, cuando eliminamos definitivamente los datos porque ya no son necesarios o pertinentes para la finalidad para la cual fueron recabados en su momento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>10. <strong>AUTORIZACIÓN MANEJO DE DATOS PERSONALES</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>De acuerdo al artículo 5° del Decreto 1377 de 2013, en AEROALLIANCE S.A.S como Responsable del Tratamiento en todos los formatos que incluyen manejo de datos, se incluirá el término “<strong><em>aviso </em>de privacidad” </strong>el cual contiene el siguiente texto: “<em>Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales, quien permitirá conocer el uso, actualizar y rectificar las informaciones que ha recopilado en bases de datos o archivos, con el fin de garantizar mis derechos, libertades y garantías constitucionales.”</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los datos personales que se encuentren en fuentes de acceso público, con independencia del medio por el cual se tenga acceso, pueden ser tratados por AEROALLIANCE S.A.S, siempre y cuando, por su naturaleza, sean Datos Públicos. Se entenderá que la autorización otorgada por el Titular a AEROALLIANCE S.A.S cumple con los requisitos exigidos en la legislación vigente aplicable, cuando ésta se manifieste:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Por escrito</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) De forma oral</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Mediante conductas inequívocas del Titular que permitan concluir de forma razonable que éste otorgó a la Institución la autorización respectiva.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) En ningún caso su silencio será asimilado por AEROALLIANCE S.A.S como una conducta inequívoca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S ha establecido canales para que el Titular de datos, pueda en todo momento solicitarle como Responsable del Tratamiento, la supresión de sus datos personales y/o revocar la autorización que nos ha otorgado para el Tratamiento de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.1. <strong><u>Autorización del Titular para el Tratamiento de los Datos Sensibles.</u></strong><strong> </strong>En el tratamiento de datos personales sensibles, cuando dicho tratamiento sea posible conforme a lo establecido en el artículo 6° de la Ley 1581 de 2012, AEROALLIANCE S.A.S cumplirá con las siguientes obligaciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Informar al Titular que por tratarse de datos sensibles no está obligado a autorizar su Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Informar al Titular de forma explícita y previa, además de los requisitos generales de la autorización para la recolección de cualquier tipo de dato personal, cuáles de los datos que serán objeto de Tratamiento son sensibles y la finalidad de su Tratamiento, y además obtiene su consentimiento expreso. Ninguna de las actividades que realiza AEROALLIANCE S.A.S está ni estará condicionada a que usted como Titular suministre sus datos personales sensibles.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>10.2. <strong><u>Uso y Finalidad del Tratamiento de Datos Personales.</u></strong><strong> </strong>AEROALLIANCE S.A.S como entidad respetuosa de la privacidad de las personas reconoce que el Titular de los datos personales tiene derecho a contar con elementos adecuados que garanticen la misma, teniendo en todo caso para ello en cuenta sus responsabilidades, derechos y obligaciones. En virtud de la relación que se ha establecido o establezca entre el titular y AEROALLIANCE S.A.S es importante que el titular conozca que AEROALLIANCE S.A.S., recolecta, registra, almacena, usa sus datos personales, para su propio uso con los propósitos que fueron solicitados o por requerimientos de las entidades públicas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales de los Titulares son utilizados por AEROALLIANCE S.A.S para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Ejecutar las actividades propias de AEROALLIANCE S.A.S para cumplir con su función de prestar Servicios de Venta de Productos Turísticos y Servicios Técnicos Aeronáuticos, lo cual se hará con base en la finalidad de la Base de Datos en la que reposan los Datos Personales de los Titulares.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Ofrecerle servicios y/o beneficios que buscan satisfacer las necesidades de los Titulares, o los productos y servicios AEROALLIANCE S.A.S, lo cual pueden hacerse por medios físicos o a través de correos electrónicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Enviar la información a entidades gubernamentales por exigencia legal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Registrar la información en las bases de datos de AEROALLIANCE S.A.S para el envío de información contractual, comercial y obligacional a que hubiere lugar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Los Datos Personales serán utilizados por AEROALLIANCE S.A.S sólo para los propósitos aquí señalados, por lo tanto, AEROALLIANCE S.A.S, no venderá, licenciará, transmitirá o divulgará los Datos Personales, salvo que:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Titular autorice expresamente a hacerlo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Sea permitido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Para el manejo interno de los Datos, éstos podrán ser conocidos por el personal autorizado de AEROALLIANCE S.A.S. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S podrá subcontratar a terceros para el procesamiento de determinadas funciones o información. Cuando ello ocurra, dichos terceros estarán obligados a proteger los Datos Personales en los términos exigidos por la ley y en su condición de Encargados del Manejo de las Bases de Datos de AEROALLIANCE S.A.S. En el caso de transmisión de datos personales, AEROALLIANCE S.A.S ha suscrito o suscribirá el contrato de transmisión a que haya lugar en los términos del Decreto 1377 de 2013.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Igualmente, AEROALLIANCE S.A.S podrá transferir o transmitir (según corresponda), guardando las debidas medidas de seguridad, datos personales a otras entidades en Colombia o en el extranjero para la prestación de un mejor servicio, de conformidad con las autorizaciones que hayan sido otorgadas por los Titulares de los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>11. <strong>DERECHOS DE LOS TITULARES DE LOS DATOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La Ley 1581 de 2012, en su Artículo 8°, establece los siguientes derechos que a usted le asisten como Titular en relación con sus datos personales:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Conocer, actualizar y rectificar sus datos personales frente a los Responsables del Tratamiento o Encargados del Tratamiento, este derecho se podrá ejercer, entre otros frente a datos parciales, inexactos, incompletos, fraccionados, que induzcan a error, o aquellos cuyo Tratamiento esté expresamente prohibido o no haya sido autorizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Solicitar prueba de la autorización otorgada al Responsable del Tratamiento salvo cuando expresamente se exceptúe como requisito para el Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Ser informado por el Responsable del Tratamiento o el Encargado del Tratamiento, previa solicitud, respecto del uso que les ha dado a sus datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Presentar ante la Superintendencia de Industria y Comercio quejas por infracciones a lo dispuesto en la Ley 1581 de 2012 y en las demás normas que la modifiquen, adicionen o complementen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Revocar la autorización y/o solicitar la supresión del dato cuando en el Tratamiento no se respeten los principios, derechos y garantías constitucionales y legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>12. <strong>CASOS QUE NO SON NECESARIOS DE ACTUALIZACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización del Titular no será necesaria cuando se trate de:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Información requerida por una entidad pública o administrativa en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Datos de naturaleza pública.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Casos de urgencia médica o sanitaria.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Tratamiento de información autorizado por la Ley para fines históricos, estadísticos o científicos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Datos relacionados con el Registro Civil de las personas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Quien acceda a los datos personales sin que medie autorización previa, deberá en todo caso cumplir con las disposiciones contenidas en la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>13. <strong>DEBER DE INFORMAR AL TITULAR</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El Responsable del Tratamiento en el momento de solicitar al Titular la autorización, deberá informarle de manera clara y expresa lo siguiente:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El Tratamiento al cual serán sometidos sus datos personales y la finalidad del mismo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) El carácter facultativo de la respuesta a las preguntas que le sean hechas, cuando éstas versen sobre datos sensibles o sobre los datos de los niños, niñas y adolescentes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Los derechos que le asisten como Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) La identificación, dirección física o electrónica y teléfono del responsable del Tratamiento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>14. <strong>PERSONAS A LAS QUE SE LES PUEDE SUMINISTRAR LA INFORMACIÓN</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información que reúna las condiciones establecidas en la Ley 1581 de 2012, podrá suministrarse a las siguientes personas:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) A los Titulares, sus causahabientes o sus representantes legales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) A las entidades públicas o administrativas en ejercicio de sus funciones legales o por orden judicial.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) A los terceros autorizados por el Titular o por la Ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>15. <strong>PROCEDIMIENTOS</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.1. <u style=\"font-weight: bold;\">Consultas.</u><strong> </strong>Se podrá consultar la información personal del Titular que repose en las bases de datos de AEROALLIANCE S.A.S. quien se encargará de suministrar toda la información contenida en el registro individual o que esté vinculada con la identificación del solicitante.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La consulta una vez recibida por AEROALLIANCE S.A.S, será atendida en un término máximo de&nbsp;diez (10) días hábiles&nbsp;contados a partir de la fecha de recibo de la misma.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuando no fuere posible atender la consulta dentro de dicho término, se informará al interesado, expresando los motivos de la demora y señalando la nueva fecha en que se atenderá tal consulta, la cual en ningún caso podrá superar los&nbsp;cinco (5) días hábiles siguientes&nbsp;al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>15.2. <strong><u>Reclamos.</u></strong><strong> </strong>Cuando se considere que la información contenida en una base de datos de AEROALLIANCE S.A.S debe ser objeto de corrección, actualización o supresión, o cuando se advierta el presunto incumplimiento de cualquiera de los deberes contenidos en la Ley de Habeas Data, se podrán presentar reclamación ante AEROALLIANCE S.A.S, la cual será tramitada bajo las siguientes condiciones:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) El reclamo se formulará mediante comunicación escrita dirigida a AEROALLIANCE S.A.S, con la identificación del Titular, la descripción de los hechos que dan lugar al reclamo, la dirección, y acompañando los documentos que se quiera hacer valer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Si el reclamo resulta incompleto, se requerirá al interesado dentro de los cinco&nbsp;(5)&nbsp;díassiguientes a la recepción del reclamo para que subsane las fallas.Transcurridos dos&nbsp;(2) meses&nbsp;desde la fecha del requerimiento, sin que el solicitante presente la información requerida, se entenderá que ha desistido del reclamo. En caso que AEROALLIANCE S.A.S reciba un reclamo del cual no sea competente para resolverlo, AEROALLIANCE S.A.S dará traslado a quien efectivamente corresponda en un término máximo de&nbsp;dos (2) días hábiles&nbsp;e informará al Titular.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Una vez recibido el reclamo completo, AEROALLIANCE S.A.S incluirá en la respectiva base de datos una leyenda que diga&nbsp;\"reclamo en trámite\"&nbsp;y el motivo del mismo, en un término no mayor a&nbsp;dos (2) días hábiles. AEROALLIANCE S.A.S conservará dicha leyenda en el dato objeto de discusión hasta que el reclamo sea decidido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) El término máximo para atender el reclamo será de&nbsp;quince (15) días hábiles&nbsp;contados a partir del día siguiente a la fecha de su recibo. Cuando no fuere posible atender el reclamo dentro de dicho término, AEROALLIANCE S.A.S informará al Titular los motivos de la demora y la nueva fecha en que se atenderá su reclamo, la cual en ningún caso podrá superar los&nbsp;ocho (8) días hábiles&nbsp;siguientes al vencimiento del primer término.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#e5e9ec\"}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#e5e9ec\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textTransform\":\"none\"}}} -->\n<h1 class=\"wp-block-heading\" style=\"text-transform:none\"><strong>Autorización de Tratamiento de Información</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p><strong>HABEAS DATA</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La autorización suministrada en el presente formulario faculta a AEROALLIANCE S.A.S para que recopile, almacene, use y suprima los datos personales aquí suministrados, especialmente, aquellos que son definidos como Datos Sensibles (*).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S, como agencia de viajes y demás servicios aeronáuticos, con el propósito de cumplir el ejercicio del derecho de Habeas Data, requiere realizar el “Tratamiento de Datos” antes señalado, de forma tal que la finalidad y uso que AEROALLIANCE S.A.S llevará a cabo de la información suministrada, será netamente, administrativo y bajo ninguna circunstancia se realizará Tratamiento de Datos Personales con fines de comercialización o circulación en beneficio de la sociedad. En todo caso aplicarán las excepciones de ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>En virtud del Artículo 8 de la Ley 1581 de 2013, el titular de la información personal que es recopilada, tiene los siguientes derechos:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer, actualizar, rectificar y suprimir los datos suministrados.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Conocer los usos que se han hecho de la información suministrada, cuando así lo solicite el titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Revocar la autorización y/o solicitar la supresión del dato suministrado cuando en el Tratamiento realizado no se respeten los principios, derechos y garantías constitucionales y legales a favor del titular.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Acceder en forma gratuita a sus datos personales que hayan sido objeto de Tratamiento.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>El titular de la información suministrada, podrá ejercer cualquiera de los derechos mencionados, dirigiendo una petición en este sentido a la dirección electrónica <em>info@aeroalliancesas.com.</em> Recibida la solicitud en los términos dispuestos por AEROALLIANCE S.A.S, se le dará trámite al requerimiento según lo establecido por la ley.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>(*) Datos Sensibles: Aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar su discriminación.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>POLÍTICA DE PRIVACIDAD</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>La aceptación expresa de esta Política de Privacidad y del tratamiento de la información y los datos personales conforme a los términos de la misma, ocurre cuando el viajero, cliente o usuario titular de los mismos, proporciona los datos en los puntos de atención y venta, incluyendo&nbsp;<a href=\"http://www.avianca.com/co/es/call-center\">Call Center</a>, cuando adquiere o utiliza cualquiera de nuestros productos o servicios, cuando pulsa la función \"Cotizar\", cuando sigue navegando en nuestro sitio web&nbsp;www.aeroalliancesas.com; la prueba de cualquiera de esos hechos, será prueba inequívoca de la aceptación de esta Política de Privacidad y del tratamiento de los Datos Personales de los titulares de los mismos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Yo titular de la información, en forma expresa y voluntaria Autorizo a AEROALLIANCE S.A.S el tratamiento de mis datos personales incorporados anteriormente tal y como lo dispone el Art. 15 de la Constitución Política Nacional, las Leyes estatutarias 1266 del 2008, la Ley estatutaria 1581 del 2012 y sus Decretos Reglamentarios: Decreto 1727 del 2009, Decreto 2952 del 2010, Decreto 1377 del 2013 y Decreto 886 del 2014; Los datos personales y/o sensibles suministrados, que sean sujetos a tratamiento, deberán ser utilizados por AEROALLIANCE S.A.S con fines históricos y estadísticos, que contribuyan a la comercialización de nuevos servicios aeronáuticos y turísticos relacionados con la prestación del servicio. AEROALLIANCE S.A.S me garantiza que podré ejercer mi derecho de acceso, rectificación y actualización relativo a este tratamiento, a través del sistema que AEROALLIANCE S.A.S establezca para tal fin. Así mismo, me comprometo a actualizar mis datos y eximo a AEROALLIANCE S.A.S, de cualquier responsabilidad derivada del incumplimiento o de la omisión de dicha obligación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Con la aceptación de la presente Política de Privacidad cada uno de nuestros viajeros, clientes o usuarios, en su calidad de titular de la información y de los datos personales recolectados autoriza el tratamiento de dichos datos para todas las finalidades establecidas en este documento y especialmente para:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>a) Usar la información y los datos personales suministrados para enviar a los correos electrónicos registrados por el viajero, cliente o usuario, el tiquete y/o el documento que confirme la transacción, así como cualquier información relacionada con el producto o servicio adquirido.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>b) Utilizar la información recibida para fines de mercadeo de nuestros productos y servicios, y de los productos y servicios de terceros con los que AEROALLIANCE S.A.S mantenga una relación de negocios.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>c) Compartir la información y los datos personales con representantes comerciales, operadores turísticos incluyendo hoteles, compañías de alquiler de vehículos, aseguradoras, entre otros, según sea requerido para el manejo de las reservaciones de planes de viajes y de otros servicios turísticos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>d) Suministrar la información y los datos personales a las autoridades de control y vigilancia, administrativas, de policía y judiciales, nacionales e internacionales, en virtud de un requerimiento legal o reglamentario y/o usar o revelar esta información y datos personales en defensa de los derechos y/o de la propiedad de AEROALLIANCE S.A.S, de sus clientes, de nuestro sitio&nbsp;web&nbsp;o de sus usuarios, para la detección o prevención de fraude, para la prevención, detección, aprehensión o persecución de actos criminales o cuando AEROALLIANCE S.A.S de buena fe considere que la entrega de la información y datos personales es en el mejor interés de la seguridad aérea.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>e) Permitir el acceso a la información y datos personales a los auditores o terceros contratados para llevar a cabo procesos de auditoría interna o externa propios de la actividad comercial que desarrollamos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>f) Consultar y actualizar la información y los datos personales.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>AEROALLIANCE S.A.S parte de la base que la información suministrada por los titulares, sus colaboradores, clientes y proveedores, tanto la propia como la de terceros es veraz, actualizada y cuenta con la autorización de los titulares. Así mismo se advierte que la información recibida y los datos personales contenidos en documentos proporcionados, tiene el propósito de ser utilizada con base en la normatividad sobre Habeas Data- Datos Personales (Art. 15 de la Constitución Política Nacional, la Ley Estatutaria No. 1266 del 2008; los Decretos Reglamentarios Decreto 1727 del 2009 y Decreto 2952 del 2010; la Ley Estatutaria No. 1581 del 2012 y sus Decretos reglamentarios 1377 del 2013 y 886 del 2014; y demás normas aplicables) para lo cual, toda persona que provea información de datos sensibles, será consultada sobre la aceptación o no del manejo de sus datos mediante la siguiente pregunta:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>“El titular manifiesta que ha sido informado que </strong><strong>AEROALLIANCE S.A.S</strong><strong> hará tratamiento de sus datos personales con el único y exclusivo propósito de ofrecer los servicios de su actividad comercial y que tiene el derecho a acceder, modificar, rectificar, suprimir, solicitar la copia de su autorización y formular quejas, reclamos y consultas frente al tratamiento que haga </strong><strong>AEROALLIANCE S.A.S</strong><strong> de sus datos personales.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Acepta SI _____&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; NO _____”.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>El acceso y consulta de los datos personales contenidos en los documentos remitidos, quedará de igual forma supeditado, y se deberá dar cumplimiento a lo previsto y dispuesto en las directrices sobre el manejo de datos personales expedida por AEROALLIANCE S.A.S la cual puede ser consultada en la parte superior donde se expone la información de Autorización de Tratamiento de Información.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>La información contenida en este mensaje, así como cualquier archivo anexo, son confidenciales y de uso exclusivo del destinatario. Quien no lo sea, tiene prohibido hacer divulgación, copia o distribución del mensaje, o cualquier acción u omisión tomada en nombre del destinatario, bajo las leyes penales y civiles del país de origen de este correo. Si usted ha recibido este mensaje por error, por favor bórrelo y notifique inmediatamente al remitente.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg\",\"id\":7326,\"hasParallax\":true,\"dimRatio\":50,\"overlayColor\":\"black\",\"minHeight\":316,\"minHeightUnit\":\"px\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"right\":\"50px\",\"bottom\":\"50px\",\"left\":\"50px\"}}}} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"padding-top:50px;padding-right:50px;padding-bottom:50px;padding-left:50px;min-height:316px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-black-background-color has-background-dim\"></span><div role=\"img\" class=\"wp-block-cover__image-background wp-image-7326 has-parallax\" style=\"background-position:50% 50%;background-image:url(http://localhost/aa/wp-content/uploads/2023/03/Politicas-de-Privacidad.jpg)\"></div><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Si tiene alguna Petición, Queja, Reclamo y/o Sugerencia</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"white\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-white-color has-text-color\">Por favor háganoslo saber</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:wpforms/form-selector {\"clientId\":\"d54ebb26-db47-440d-b9e0-95b77cbd1cb2\",\"formId\":\"7309\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:false,\\u0022displayDesc\\u0022:false,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022labelSublabelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.55 )\\u0022,\\u0022labelErrorColor\\u0022:\\u0022#d63637\\u0022,\\u0022buttonSize\\u0022:\\u0022medium\\u0022,\\u0022buttonBorderRadius\\u0022:\\u00223px\\u0022,\\u0022buttonBackgroundColor\\u0022:\\u0022#066aab\\u0022,\\u0022buttonTextColor\\u0022:\\u0022#ffffff\\u0022}\"} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":339,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/aa/wp-content/uploads/2023/03/contact.png\" alt=\"\" class=\"wp-image-339\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p><a href=\"http://localhost/aa/politicas-de-privacidad/\" target=\"_blank\" rel=\"noopener\" title=\"\">Ver Política de Tratamiento de Datos</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->', 'Políticas de Privacidad', '', 'inherit', 'closed', 'closed', '', '7277-revision-v1', '', '', '2023-09-07 22:09:32', '2023-09-08 03:09:32', '', 7277, 'http://localhost/aa/?p=7777', 0, 'revision', '', 0);
